def track_developers(entries):
    """Split raw developer entries into front end and back end rosters."""
    frontend = []
    backend = []
    for name, role in entries:
        normalized = str(role).strip().lower()
        if normalized in ("frontend", "front end", "ui", "client"):
            frontend.append(name)
        elif normalized in ("backend", "back end", "api", "server"):
            backend.append(name)
    roster = {"frontend": frontend, "backend": backend}
    return roster


def manage(events):
    """Route project events into six categories and report their sizes."""
    open_bugs = []
    resolved_bugs = []
    planned_features = []
    finished_features = []
    logs_by_level = {}
    developer_entries = []
    for event in events:
        kind, description, metadata = event
        if kind == "bug":
            if metadata.get("status") == "resolved":
                resolved_bugs.append(description)
            else:
                open_bugs.append(description)
        elif kind == "feature":
            if metadata.get("status") == "done":
                finished_features.append(description)
            else:
                planned_features.append(description)
        elif kind == "developer":
            developer_entries.append((description, metadata.get("role", "")))
        elif kind == "log":
            level = metadata.get("level", "info")
            if level not in logs_by_level:
                logs_by_level[level] = []
            logs_by_level[level].append(description)
    roster = track_developers(developer_entries)
    active_developers = len(roster["frontend"]) + len(roster["backend"])
    total_logs = sum(len(messages) for messages in logs_by_level.values())
    return (
        len(open_bugs),
        len(resolved_bugs),
        len(planned_features),
        len(finished_features),
        active_developers,
        total_logs,
    )


def format_report(counts):
    """Render the six category counts as an aligned text summary."""
    labels = (
        "Open bugs",
        "Resolved bugs",
        "Planned features",
        "Finished features",
        "Active developers",
        "System logs",
    )
    lines = []
    width = max(len(label) for label in labels)
    for label, value in zip(labels, counts):
        lines.append("{0:<{1}} : {2}".format(label, width, value))
    return "\n".join(lines)


def main():
    events = [
        ("bug", "Crash on export", {"status": "open"}),
        ("bug", "Broken pagination", {"status": "resolved"}),
        ("feature", "Dark mode", {"status": "planned"}),
        ("feature", "CSV import", {"status": "done"}),
        ("feature", "Offline cache", {"status": "planned"}),
        ("developer", "Ada", {"role": "backend"}),
        ("developer", "Grace", {"role": "front end"}),
        ("developer", "Linus", {"role": "backend"}),
        ("log", "deploy finished", {"level": "info"}),
        ("log", "disk almost full", {"level": "warning"}),
        ("log", "cache miss spike", {"level": "warning"}),
    ]
    counts = manage(events)
    print(format_report(counts))
    print("summary tuple:", counts)


if __name__ == "__main__":
    main()

import re

STOP_WORDS = {"the", "a", "an", "and", "or", "of", "to", "in", "is", "it",
              "that", "this", "for", "on", "with", "as", "at", "by"}

PUNCTUATION = ".,;:!?'\"()-"


def classify_stop_words(skipped):
    """Split skipped stop words into short and long groups with counts."""
    short_stops = {}
    long_stops = {}
    for word, count in skipped.items():
        if len(word) <= 3:
            short_stops[word] = short_stops.get(word, 0) + count
        else:
            long_stops[word] = long_stops.get(word, 0) + count
    return short_stops, long_stops


def tokenize(text):
    """Return lowercase word tokens of a paragraph."""
    return re.findall(r"[A-Za-z']+", text.lower())


def count_punctuation(text, counts):
    """Accumulate punctuation character counts for one paragraph."""
    for char in text:
        if char in PUNCTUATION:
            counts[char] = counts.get(char, 0) + 1


def index(paragraphs):
    frequencies = {}
    positions = {}
    lengths = []
    unique_per_paragraph = []
    skipped = {}
    punctuation = {}

    for para_no, paragraph in enumerate(paragraphs):
        words = tokenize(paragraph)
        lengths.append(len(words))
        count_punctuation(paragraph, punctuation)
        seen = []
        for offset, word in enumerate(words):
            if word in STOP_WORDS:
                skipped[word] = skipped.get(word, 0) + 1
                continue
            frequencies[word] = frequencies.get(word, 0) + 1
            if word not in positions:
                positions[word] = []
            positions[word].append((para_no, offset))
            if word not in seen:
                seen.append(word)
        unique_per_paragraph.append(len(seen))

    short_stops, long_stops = classify_stop_words(skipped)
    report = {}
    report["short stop words"] = len(short_stops)
    report["long stop words"] = len(long_stops)
    for label, value in report.items():
        print("{}: {}".format(label, value))

    return (len(frequencies), len(positions), len(lengths),
            len(unique_per_paragraph), len(skipped), len(punctuation))


def main():
    paragraphs = [
        "The quick brown fox jumps over the lazy dog.",
        "A dog barks; the fox runs, and the dog sleeps!",
        "Foxes and dogs: rivals in the garden of stories.",
    ]
    summary = index(paragraphs)
    labels = ["words", "indexed", "paragraphs", "unique", "stops", "marks"]
    pairs = []
    for label, number in zip(labels, summary):
        pairs.append("{}={}".format(label, number))
    print(", ".join(pairs))
    return summary


if __name__ == "__main__":
    main()

