MAX_CREDITS = 18
WAITLIST_LIMIT = 3
PERIOD_LOAD = 2


def assign_instructors(sessions):
    """Map each accepted course to an instructor, balancing AM/PM loads."""
    morning = {}
    afternoon = {}
    instructors = {}
    for course, instructor, period in sessions:
        if course in instructors:
            continue
        table = morning if period == "AM" else afternoon
        if instructor not in table:
            table[instructor] = []
        if len(table[instructor]) >= PERIOD_LOAD:
            continue
        table[instructor].append(course)
        instructors[course] = instructor
    return instructors


def register(requests):
    enrolled = {}
    waitlisted = {}
    rejected = {}
    credits = {}
    capacities = {}
    sessions = []
    for student, course, dept, credit_hours, capacity, period, instructor in requests:
        if course not in capacities:
            capacities[course] = capacity
        if course not in enrolled:
            enrolled[course] = []
        if course not in waitlisted:
            waitlisted[course] = []
        if student not in credits:
            credits[student] = 0

        roster = enrolled[course]
        queue = waitlisted[course]
        if student in roster or student in queue:
            reason = "duplicate"
        elif credits[student] + credit_hours > MAX_CREDITS:
            reason = "credit-overload"
        elif len(roster) < capacities[course]:
            reason = None
        elif len(queue) < WAITLIST_LIMIT:
            reason = "waitlisted"
        else:
            reason = "course-full"

        if reason is None:
            roster.append(student)
            credits[student] += credit_hours
            sessions.append((course, instructor, period))
        elif reason == "waitlisted":
            queue.append(student)
        else:
            if dept not in rejected:
                rejected[dept] = []
            rejected[dept].append((student, course, reason))

    instructors = assign_instructors(sessions)
    return (
        sum(len(r) for r in enrolled.values()),
        sum(len(q) for q in waitlisted.values()),
        sum(len(group) for group in rejected.values()),
        len(credits),
        len(capacities),
        len(instructors),
    )


def format_summary(totals):
    labels = ("enrolled", "waitlisted", "rejected", "students", "courses", "instructors")
    lines = []
    for label, value in zip(labels, totals):
        lines.append("{:<12}{}".format(label, value))
    return "\n".join(lines)


