SESSION_TIMEOUT = 1800
MOBILE_MARKERS = ("iphone", "android", "ipad", "mobile")


def parse_user_agents(agents):
    """Split raw user agent strings into mobile and desktop browser counts."""
    mobile = {}
    desktop = {}
    for raw in agents:
        agent = raw.strip()
        if not agent:
            continue
        lowered = agent.lower()
        if any(marker in lowered for marker in MOBILE_MARKERS):
            mobile[agent] = mobile.get(agent, 0) + 1
        else:
            desktop[agent] = desktop.get(agent, 0) + 1
    return mobile, desktop


def analyze(logs):
    """Scan log tuples (session, timestamp, endpoint, status, user_agent)."""
    active = {}
    timed_out = []
    error_groups = {}
    success_endpoints = []
    agents = []
    hits = {}
    for session, timestamp, endpoint, status, user_agent in logs:
        previous = active.get(session)
        if previous is not None and timestamp - previous > SESSION_TIMEOUT:
            timed_out.append(session)
        active[session] = timestamp
        hits[endpoint] = hits.get(endpoint, 0) + 1
        agents.append(user_agent)
        if status >= 400:
            if status not in error_groups:
                error_groups[status] = []
            error_groups[status].append(endpoint)
        else:
            success_endpoints.append(endpoint)
    mobile, desktop = parse_user_agents(agents)
    return (
        len(active),
        len(timed_out),
        len(error_groups),
        len(success_endpoints),
        len(mobile) + len(desktop),
        len(hits),
    )


def format_report(counts):
    labels = (
        "active sessions",
        "timed out sessions",
        "error status groups",
        "successful requests",
        "distinct user agents",
        "endpoints hit",
    )
    lines = []
    for label, value in zip(labels, counts):
        lines.append("{:>20}: {}".format(label, value))
    return "\n".join(lines)


def main():
    logs = [
        ("s1", 1000, "/home", 200, "Mozilla/5.0 (Windows NT 10.0)"),
        ("s2", 1020, "/login", 200, "Mozilla/5.0 (iPhone; CPU iPhone OS 15_0)"),
        ("s1", 1100, "/cart", 404, "Mozilla/5.0 (Windows NT 10.0)"),
        ("s2", 4000, "/checkout", 500, "Mozilla/5.0 (iPhone; CPU iPhone OS 15_0)"),
        ("s3", 4100, "/home", 200, "Mozilla/5.0 (Android 12; Mobile)"),
        ("s1", 4200, "/home", 503, "Mozilla/5.0 (Windows NT 10.0)"),
        ("s3", 9000, "/search", 404, "Mozilla/5.0 (Android 12; Mobile)"),
    ]
    counts = analyze(logs)
    print(format_report(counts))
    print("summary tuple:", counts)


if __name__ == "__main__":
    main()

def process_cancellations(cancelled):
    fraudulent = []
    user_requested = []
    reasons = {}
    for order_id, customer, amount, reason in cancelled:
        if reason == "fraud":
            fraudulent.append((order_id, amount))
        else:
            user_requested.append((order_id, customer, amount))
        reasons[reason] = reasons.get(reason, 0) + 1
    return fraudulent, user_requested, reasons


def summarize_backorders(by_supplier):
    lines = []
    for supplier in sorted(by_supplier):
        items = by_supplier[supplier]
        lines.append("%s: %s" % (supplier, ", ".join(items)))
    return lines


def fulfill(orders):
    packed = []
    backordered = {}
    shipped_boxes = []
    cancelled = []
    notifications = []
    refunds = []

    for order in orders:
        order_id, status, item, supplier, customer, amount = order
        if status == "packed":
            packed.append((order_id, item))
            notifications.append((customer, "Your %s has been packed." % item))
        elif status == "backordered":
            if supplier not in backordered:
                backordered[supplier] = []
            backordered[supplier].append(item)
            notifications.append((customer, "%s is on backorder." % item))
        elif status == "shipped":
            shipped_boxes.append((order_id, item, customer))
            notifications.append((customer, "Box for order %s shipped." % order_id))
        elif status == "cancelled":
            cancelled.append((order_id, customer, amount, supplier))

    fraudulent, user_requested, reasons = process_cancellations(cancelled)
    for order_id, customer, amount in user_requested:
        refunds.append((order_id, customer, amount))
        notifications.append((customer, "Refund of %.2f issued." % amount))
    for order_id, amount in fraudulent:
        notifications.append(("risk-team", "Order %s flagged: %.2f" % (order_id, amount)))

    backordered_items = sum(len(items) for items in backordered.values())
    report = summarize_backorders(backordered)
    for line in report:
        notifications.append(("warehouse", line))
    for reason in sorted(reasons):
        notifications.append(("support", "%d cancellation(s) due to %s" % (reasons[reason], reason)))

    return (len(packed), backordered_items, len(shipped_boxes),
            len(cancelled), len(notifications), len(refunds))


def main():
    orders = [
        (101, "packed", "kettle", "AcmeHome", "ana@example.com", 42.0),
        (102, "backordered", "lamp", "BrightCo", "ben@example.com", 18.5),
        (103, "backordered", "shade", "BrightCo", "cleo@example.com", 9.0),
        (104, "backordered", "rug", "WeaveWorks", "dan@example.com", 75.0),
        (105, "shipped", "kettle", "AcmeHome", "eve@example.com", 42.0),
        (106, "cancelled", "mirror", "AcmeHome", "fay@example.com", 30.0, ),
        (107, "cancelled", "clock", "WeaveWorks", "gil@example.com", 120.0),
    ]
    normalized = []
    for order in orders:
        order_id, status, item, supplier, customer, amount = order[:6]
        reason = "fraud" if status == "cancelled" and amount > 100 else "customer"
        if status == "cancelled":
            normalized.append((order_id, status, item, reason, customer, amount))
        else:
            normalized.append((order_id, status, item, supplier, customer, amount))
    print(fulfill(normalized))


if __name__ == "__main__":
    main()

