def _evaluate_requests(requests):
    stale = {}
    recent = {}
    for sender, target, age_days in requests:
        bucket = stale if age_days > 7 else recent
        if target not in bucket:
            bucket[target] = []
        bucket[target].append(sender)
    pending = {}
    for target, senders in recent.items():
        pending[target] = list(senders)
    for target, senders in stale.items():
        if target not in pending:
            pending[target] = []
        pending[target].extend(senders)
