ALCOHOLIC = {"beer", "wine", "whiskey", "margarita", "old fashioned", "cider"}
COURSES = ("appetizer", "main", "dessert", "drink")


def normalize(ticket):
    """Turn a raw order item into (server, course, item, status)."""
    if not isinstance(ticket, (tuple, list)) or len(ticket) not in (3, 4):
        raise ValueError("each ticket needs server, course, item and optional status")
    server, course, item = ticket[0], ticket[1], ticket[2]
    status = ticket[3] if len(ticket) == 4 else "open"
    return str(server), str(course).strip().lower(), str(item), str(status).strip().lower()


def route_drinks(drink_names):
    """Tally alcoholic and non alcoholic beverages in local collections."""
    alcoholic = []
    non_alcoholic = []
    for name in drink_names:
        if name.strip().lower() in ALCOHOLIC:
            alcoholic.append(name)
        else:
            non_alcoholic.append(name)
    tally = {}
    tally["alcoholic"] = len(alcoholic)
    tally["non_alcoholic"] = len(non_alcoholic)
    return tally


def kitchen(tickets):
    appetizers = []
    mains = []
    desserts = []
    drink_orders = []
    voided = {}
    completed = []
    group_key = None
    last_voider = None
    for raw in tickets:
        server, course, item, status = normalize(raw)
        if course not in COURSES:
            raise ValueError("unknown course: %s" % course)
        if status == "void":
            if server != last_voider:
                group_key = (server, len(voided) + 1)
                voided[group_key] = []
                last_voider = server
            voided[group_key].append(item)
            continue
        if course == "appetizer":
            appetizers.append(item)
        elif course == "main":
            mains.append(item)
        elif course == "dessert":
            desserts.append(item)
        else:
            drink_orders.append(item)
        if status == "served":
            completed.append(item)
    tally = route_drinks(drink_orders)
    drinks = tally["alcoholic"] + tally["non_alcoholic"]
    return (len(appetizers), len(mains), len(desserts), drinks, len(voided), len(completed))


def course_index(tickets):
    """Map each course to the live (non voided) items ordered on it."""
    buckets = {}
    for raw in tickets:
        _server, course, item, status = normalize(raw)
        if status == "void":
            continue
        if course not in buckets:
            buckets[course] = []
        buckets[course].append(item)
    return buckets


def format_report(tickets):
    labels = ("appetizers", "mains", "desserts", "drinks", "void groups", "completed")
    lines = []
    for label, count in zip(labels, kitchen(tickets)):
        lines.append("%-12s %d" % (label, count))
    index = course_index(tickets)
    for course in COURSES:
        if course in index:
            lines.append("%-12s %s" % (course, ", ".join(index[course])))
    return "\n".join(lines)


def main():
    tickets = [
        ("Ana", "appetizer", "calamari"),
        ("Ana", "main", "steak frites", "served"),
        ("Ana", "drink", "Wine"),
        ("Ben", "drink", "iced tea", "served"),
        ("Ben", "dessert", "flan", "void"),
        ("Ben", "main", "risotto", "void"),
        ("Ana", "dessert", "tiramisu", "void"),
        ("Cleo", "drink", "beer", "served"),
        ("Cleo", "appetizer", "bruschetta", "served"),
    ]
    print(format_report(tickets))
    print(kitchen(tickets))


if __name__ == "__main__":
    main()

