def classify_cancellations(cancel_events):
    weather = []
    mechanical = []
    other = []
    for flight_id, reason in cancel_events:
        tag = reason.strip().lower()
        if tag == "weather":
            weather.append(flight_id)
        elif tag == "mechanical":
            mechanical.append(flight_id)
        else:
            other.append(flight_id)
    return {"weather": weather, "mechanical": mechanical, "other": other}


def route(flights):
    grounded = []
    airborne = []
    landing_queue = []
    takeoff_queue = []
    delayed_by_destination = {}
    cancel_events = []
    for event in flights:
        kind = event[0].strip().lower()
        flight_id = event[1]
        if kind == "ground":
            grounded.append(flight_id)
            if flight_id in airborne:
                airborne.remove(flight_id)
        elif kind == "airborne":
            airborne.append(flight_id)
            if flight_id in grounded:
                grounded.remove(flight_id)
        elif kind == "landing":
            landing_queue.append(flight_id)
        elif kind == "takeoff":
            takeoff_queue.append(flight_id)
        elif kind == "delay":
            destination = event[2]
            if destination not in delayed_by_destination:
                delayed_by_destination[destination] = []
            delayed_by_destination[destination].append(flight_id)
        elif kind == "cancel":
            cancel_events.append((flight_id, event[2]))
        else:
            raise ValueError("unknown air traffic event: %r" % (event[0],))
    canceled = classify_cancellations(cancel_events)
    delayed_total = sum(len(group) for group in delayed_by_destination.values())
    canceled_total = sum(len(group) for group in canceled.values())
    return (
        len(grounded),
        len(airborne),
        len(landing_queue),
        len(takeoff_queue),
        delayed_total,
        canceled_total,
    )


