def organize_repair_queue(repair_events):
    """Split repair events into routine maintenance and critical breakdowns."""
    routine = {}
    critical = {}
    for truck_id, severity, note in repair_events:
        if severity == "critical":
            critical.setdefault(truck_id, []).append(note)
        else:
            routine.setdefault(truck_id, []).append(note)
    queue = {}
    for truck_id, notes in critical.items():
        queue[truck_id] = {"priority": 0, "tasks": notes}
    for truck_id, notes in routine.items():
        if truck_id in queue:
            queue[truck_id]["tasks"].extend(notes)
        else:
            queue[truck_id] = {"priority": 1, "tasks": notes}
    return queue


def group_delays_by_region(delay_records):
    """Collect delayed shipments into one sequence per transit region."""
    grouped = []
    current_region = None
    bucket = []
    for region, shipment in delay_records:
        if region != current_region:
            if bucket:
                grouped.append((current_region, bucket))
            bucket = []
            current_region = region
        bucket.append(shipment)
    if bucket:
        grouped.append((current_region, bucket))
    return grouped


def dispatch(vehicles):
    idle = []
    active = {}
    repair_events = []
    drivers = {}
    manifests = {}
    delay_records = []
    for update in vehicles:
        kind, truck_id = update[0], update[1]
        if kind == "idle":
            if truck_id in active:
                del active[truck_id]
            idle.append(truck_id)
        elif kind == "active":
            if truck_id in idle:
                idle.remove(truck_id)
            active[truck_id] = update[2]
        elif kind == "repair":
            repair_events.append((truck_id, update[2], update[3]))
        elif kind == "driver":
            drivers[truck_id] = update[2]
        elif kind == "manifest":
            stops = manifests.setdefault(truck_id, [])
            stops.extend(update[2])
        elif kind == "delay":
            delay_records.append((update[2], truck_id))
    repair_queue = organize_repair_queue(repair_events)
    delayed_regions = group_delays_by_region(delay_records)
    return (len(idle), len(active), len(repair_queue),
            len(drivers), len(manifests), len(delayed_regions))


