MALICIOUS_MARKERS = ("password", "wire transfer", "click here", "bitcoin", "verify account")


def normalize(raw):
    """Turn a raw customer query into a (category, product line, message) triple."""
    parts = list(raw) if isinstance(raw, (tuple, list)) else [raw]
    category = str(parts[0]).strip().lower() if parts else "unassigned"
    product = str(parts[1]).strip().lower() if len(parts) > 1 else "general"
    message = str(parts[2]) if len(parts) > 2 else ""
    if category not in CATEGORIES:
        category = "unassigned"
    return category, product, message


def sift_spam(messages):
    """Split spam traffic into harmless promotions and malicious attempts."""
    promotional = []
    malicious = []
    for message in messages:
        lowered = message.lower()
        if any(marker in lowered for marker in MALICIOUS_MARKERS):
            malicious.append(message)
        else:
            promotional.append(message)
    return {"promotional": promotional, "malicious": malicious}


def support(tickets):
    unassigned = []
    escalated = []
    resolved = []
    pending = []
    spam_messages = []
    alerts = {}
    routes = {
        "unassigned": unassigned,
        "escalated": escalated,
        "resolved": resolved,
        "pending": pending,
    }
    for raw in tickets:
        category, product, message = normalize(raw)
        if category == "priority":
            if product not in alerts:
                alerts[product] = []
            alerts[product].append(message)
        elif category == "spam":
            spam_messages.append(message)
        else:
            routes[category].append((product, message))
    sifted = sift_spam(spam_messages)
    spam_total = len(sifted["promotional"]) + len(sifted["malicious"])
    priority_total = sum(len(group) for group in alerts.values())
    return (len(unassigned), len(escalated), len(resolved), len(pending),
