def log(exercises):
    cardio_sessions = []
    lifting_sets = []
    stretch_routines = []
    skipped_days = []
    personal_records = {}
    calories = 0.0
    for event in exercises:
        kind = event[0]
        if kind == "cardio":
            cardio_sessions.append((event[1], event[2]))
            calories += event[2] * CARDIO_CAL_PER_MIN
        elif kind == "lift":
            lifting_sets.append((event[1], event[2], event[3]))
            calories += event[2] * event[3] * LIFT_CAL_PER_REP_KG
        elif kind == "stretch":
            stretch_routines.append((event[1], event[2]))
        elif kind == "skip":
            skipped_days.append(event[1])
        elif kind == "pr":
            exercise = event[1]
            if exercise not in personal_records:
                personal_records[exercise] = []
            personal_records[exercise].append(event[2])
    dynamic, static = process_stretching(stretch_routines)
    stretch_count = len(dynamic) + len(static)
    calories += stretch_count * STRETCH_CAL
    return (len(cardio_sessions), len(lifting_sets), stretch_count,
            len(skipped_days), len(personal_records), round(calories))


def best_records(exercises):
    """Return the heaviest/longest personal record achieved per exercise."""
    grouped = {}
    for event in exercises:
        if event[0] == "pr":
            if event[1] not in grouped:
                grouped[event[1]] = []
            grouped[event[1]].append(event[2])
    bests = {}
    for name, values in grouped.items():
        bests[name] = max(values)
    return bests


def format_report(counts, bests):
    labels = ("cardio sessions", "lifting sets", "stretches",
              "skipped days", "PR exercises", "estimated calories")
    lines = []
    for label, value in zip(labels, counts):
        lines.append("{:>19}: {}".format(label, value))
    for name in sorted(bests):
        lines.append("{:>19}: {}".format("best " + name, bests[name]))
    return "\n".join(lines)


