def group_by_origin(connections):
    graph = {}
    for origin, destination, distance in connections:
        graph.setdefault(origin, []).append((destination, distance))
    return graph


def search(connections):
    graph = group_by_origin(connections)
    queue = []
    visited = []
    distances = {}
    predecessors = {}
    dead_ends = []
    alternatives = []
    explored = []
    if connections:
        start = connections[0][0]
        queue.append(start)
        distances[start] = 0
    while queue:
        current = min(queue, key=lambda city: distances[city])
        queue.remove(current)
        if current in visited:
            continue
        visited.append(current)
        explored.append(current)
        links = graph.get(current, [])
        if not links:
            dead_ends.append(current)
        for neighbour, distance in links:
            candidate = distances[current] + distance
            known = distances.get(neighbour)
            if known is None or candidate < known:
                distances[neighbour] = candidate
                predecessors[neighbour] = current
                queue.append(neighbour)
            elif candidate == known:
                alternatives.append((current, neighbour, candidate))
    state = {}
    state["explored"] = explored
    state["dead_ends"] = dead_ends
    state["distances"] = distances
    state["predecessors"] = predecessors
    state["alternatives"] = alternatives
    return state


def explore(connections):
    state = search(connections)
    return state["explored"], state["dead_ends"]


def reconstruct_path(predecessors, target):
    path = []
    city = target
    while city is not None:
        path.append(city)
        city = predecessors.get(city)
    path.reverse()
    return path


def report_lines(connections):
    state = search(connections)
    lines = []
    for city in state["explored"]:
        route = reconstruct_path(state["predecessors"], city)
        lines.append("%s: %d via %s" % (city, state["distances"][city], " -> ".join(route)))
    if state["dead_ends"]:
        lines.append("dead ends: " + ", ".join(state["dead_ends"]))
    for origin, destination, distance in state["alternatives"]:
        lines.append("alternative route %s -> %s at %d" % (origin, destination, distance))
    return lines


def main():
    connections = [
        ("alpha", "beta", 10),
        ("alpha", "gamma", 25),
        ("beta", "gamma", 15),
        ("beta", "delta", 40),
        ("gamma", "delta", 25),
    ]
    explored, dead_ends = explore(connections)
    print("explored:", explored)
    print("dead ends:", dead_ends)
    for line in report_lines(connections):
        print(line)


if __name__ == "__main__":
    main()

def tokenize(source):
    tokens = []
    for lineno, text in enumerate(source.splitlines()):
        if lineno:
            tokens.append("\n")
        current = []
        for ch in text:
            if ch in "()[]{}":
                if current:
                    tokens.append("".join(current))
                    current = []
                tokens.append(ch)
            elif ch.isspace():
                if current:
                    tokens.append("".join(current))
                    current = []
            else:
                current.append(ch)
        if current:
            tokens.append("".join(current))
    return tokens


def parse(tokens):
    paren_stack = []
    bracket_stack = []
    brace_stack = []
    blocks = []
    errors = []
    unmatched = []
    open_lines = {}
    variables = {}
    scope_stack = []
    order = []
    openers = {"(": paren_stack, "[": bracket_stack, "{": brace_stack}
    closers = {")": "(", "]": "[", "}": "{"}
    line = 1
    expect_name = False
    for index, token in enumerate(tokens):
        if token == "\n":
            line += 1
        elif token in openers:
            handle = (token, line, index)
            openers[token].append(handle)
            order.append(handle)
            open_lines[index] = line
            if token == "{":
                scope_stack.append(variables)
                variables = {}
        elif token in closers:
            opener = closers[token]
            if not openers[opener]:
                unmatched.append((token, line))
            elif order[-1][0] != opener:
                errors.append("line %d: '%s' closes '%s'" % (line, token, order[-1][0]))
                unmatched.append((token, line))
            else:
                handle = order.pop()
                openers[opener].pop()
                block = {"open": opener, "close": token,
                         "start": open_lines.pop(handle[2]), "end": line}
                if opener == "{":
                    block["vars"] = sorted(variables)
                    variables = scope_stack.pop()
                blocks.append(block)
        elif expect_name:
            variables[token] = line
            expect_name = False
        elif token in ("let", "var"):
            expect_name = True
    for handle in order:
        unmatched.append((handle[0], handle[1]))
    return blocks, errors, unmatched


def format_report(blocks, errors, unmatched):
    lines = []
    counts = {}
    for block in blocks:
        counts[block["open"] + block["close"]] = counts.get(block["open"] + block["close"], 0) + 1
    lines.append("blocks: %d" % len(blocks))
    for kind in sorted(counts):
        lines.append("  %s x%d" % (kind, counts[kind]))
    for block in blocks:
        names = block.get("vars", [])
        if names:
            lines.append("  scope %d-%d defines %s" % (block["start"], block["end"], ", ".join(names)))
    lines.append("errors: %d" % len(errors))
    lines.extend("  " + message for message in errors)
    lines.append("unmatched: %d" % len(unmatched))
    lines.extend("  '%s' at line %d" % item for item in unmatched)
    return "\n".join(lines)


def main():
    print(format_report(*parse(["{", "x", "}"])))
    source = "func f(a, b) {\n  let total = a + b\n  var items = [1, 2]\n}\nextra )\n{ let z = (1]\n"
    print(format_report(*parse(tokenize(source))))


if __name__ == "__main__":
    main()

