def normalize(shipments):
    cleaned = []
    for entry in shipments:
        pid, dept, urgency = entry
        cleaned.append((str(pid).strip(), str(dept).strip().lower(), str(urgency).strip().lower()))
    return cleaned


def pick_courier(dept, loads):
    for courier, served in COURIERS.items():
        if dept in served and len(loads.get(courier, [])) < CAPACITY[courier]:
            return courier
    return None


def route(shipments):
    critical = []
    standard = []
    delayed = []
    refrigerated = []
    loads = {}
