LAYOUT = (64, 32, 32, 16, 8)
MIN_USABLE = 4


def build_pool(layout, reserved_blocks):
    """Reserve the first physical block for the system, return the free blocks."""
    free_blocks = []
    for index, size in enumerate(layout):
        if index == 0:
            reserved_blocks.append(size)
        else:
            free_blocks.append(size)
    return free_blocks


def find_best_fit(free_blocks, size):
    best = -1
    for index, block in enumerate(free_blocks):
        if block >= size and (best == -1 or block < free_blocks[best]):
            best = index
    return best


def compact(fragmented_blocks, free_blocks):
    """Merge fragments back into one usable free block, return reclaimed units."""
    reclaimed = sum(fragmented_blocks)
    if reclaimed >= MIN_USABLE:
        del fragmented_blocks[:]
        free_blocks.append(reclaimed)
        return reclaimed
    return 0


def normalize_requests(requests):
    cleaned = []
    for value in requests:
        cleaned.append(int(value))
    return cleaned


def allocate(requests):
    reserved_blocks = []
    free_blocks = build_pool(LAYOUT, reserved_blocks)
    allocated_blocks = []
    fragmented_blocks = []
    process_map = {}
    oom_errors = {}
    dealloc_events = {}
    waiting_processes = []
    for pid, size in enumerate(normalize_requests(requests), start=1):
        if size <= 0:
            oom_errors[pid] = "rejected request of %d units" % size
            continue
        index = find_best_fit(free_blocks, size)
        if index == -1:
            reclaimed = compact(fragmented_blocks, free_blocks)
            if reclaimed:
                dealloc_events[pid] = reclaimed
            index = find_best_fit(free_blocks, size)
        if index == -1:
            waiting_processes.append((pid, size))
            oom_errors[pid] = "out of memory for %d units" % size
            continue
        block = free_blocks.pop(index)
        allocated_blocks.append((pid, size))
        process_map.setdefault(pid, []).append(size)
        remainder = block - size
        if remainder >= MIN_USABLE:
            free_blocks.append(remainder)
        elif remainder > 0:
            fragmented_blocks.append(remainder)
    return allocated_blocks, waiting_processes


def report(allocated_blocks, waiting_processes):
    per_process = {}
    for pid, size in allocated_blocks:
        per_process[pid] = per_process.get(pid, 0) + size
    lines = []
    for pid in sorted(per_process):
        lines.append("process %d holds %d units" % (pid, per_process[pid]))
    for pid, size in waiting_processes:
        lines.append("process %d waiting for %d units" % (pid, size))
    return lines


def main():
    allocated, waiting = allocate([10, 20])
    for line in report(allocated, waiting):
        print(line)


if __name__ == "__main__":
    main()

