KEYWORDS = frozenset({"let", "print", "if", "else", "while", "return", "def"})
OPERATORS = frozenset("+-*/=<>!%&|")
PUNCTUATION = frozenset("(),;:[]{}")


def _is_number(word):
    if word.isdigit():
        return True
    return word.count(".") == 1 and word.replace(".", "", 1).isdigit()


def classify_word(word, table):
    if not word:
        return
    table["tokens"].append(word)
    if word in KEYWORDS:
        table["keywords"].append(word)
    elif _is_number(word):
        table["literals"].append(word)
        table["constants"][word] = float(word) if "." in word else int(word)
    elif (word[0].isalpha() or word[0] == "_") and all(c.isalnum() or c == "_" for c in word):
        table["identifiers"].append(word)
        table["variables"].setdefault(word, None)
    else:
        table["errors"].append("invalid characters in %r" % word)


def link_assignments(table):
    tokens = table["tokens"]
    for i in range(len(tokens) - 2):
        name, operator, value = tokens[i], tokens[i + 1], tokens[i + 2]
        if operator == "=" and name in table["variables"] and value in table["constants"]:
            table["variables"][name] = table["constants"][value]


def analyze(characters):
    keywords = list()
    identifiers = list()
    literals = list()
    operators = list()
    punctuation = list()
    comments = list()
    errors = list()
    variables = dict()
    constants = dict()
    tokens = list()
    table = {"keywords": keywords, "identifiers": identifiers, "literals": literals,
             "operators": operators, "punctuation": punctuation, "comments": comments,
             "errors": errors, "variables": variables, "constants": constants,
             "tokens": tokens}
    word = ""
    i, n = 0, len(characters)
    while i < n:
        c = characters[i]
        if c == "#":
            end = characters.find("\n", i)
            end = n if end == -1 else end
            classify_word(word, table)
            word = ""
            comments.append(characters[i:end])
            i = end
        elif c.isspace() or c in OPERATORS or c in PUNCTUATION:
            classify_word(word, table)
            word = ""
            if c in OPERATORS:
                operators.append(c)
                tokens.append(c)
            elif c in PUNCTUATION:
                punctuation.append(c)
                tokens.append(c)
            i += 1
        else:
            word += c
            i += 1
    classify_word(word, table)
    link_assignments(table)
    return table


def tokenize(characters):
    table = analyze(characters)
    return table["identifiers"], table["literals"], table["errors"]


def summarize(table):
    counts = dict()
    for key in ("keywords", "identifiers", "literals", "operators", "punctuation", "comments"):
        counts[key] = len(table[key])
    return counts


def format_report(source, table):
