def filter_invalid(rows):
    """Split rows into well formed (key, value) pairs and rejected ones."""
    valid = []
    invalid = []
    for row in rows:
        if not isinstance(row, (tuple, list)) or len(row) != 2 or row[0] is None:
            invalid.append(row)
        else:
            valid.append((row[0], row[1]))
    return valid, invalid


def build_index(rows):
    """Map each key to the list of values carrying it, reporting repeated keys."""
    index = {}
    duplicates = []
    for key, value in rows:
        if key in index:
            duplicates.append(key)
            index[key].append(value)
        else:
            index[key] = [value]
    return index, duplicates


def detect_conflicts(left_index, right_index):
    """Keys present on both sides with more than one value on either side."""
    conflicts = {}
    for key, left_values in left_index.items():
        right_values = right_index.get(key)
        if right_values is not None and (len(left_values) > 1 or len(right_values) > 1):
            conflicts[key] = (list(left_values), list(right_values))
    return conflicts


def combine(tables, diagnostics=None):
    """Merge the left and right tables of `tables` on their common key."""
    left_rows, right_rows = tables
    left_valid, left_invalid = filter_invalid(left_rows)
    right_valid, right_invalid = filter_invalid(right_rows)
    left_index, left_duplicates = build_index(left_valid)
    right_index, right_duplicates = build_index(right_valid)

    matches = []
    left_orphans = []
    right_orphans = []
    for key, left_values in left_index.items():
        if key in right_index:
            for left_value in left_values:
                for right_value in right_index[key]:
                    matches.append((key, left_value, right_value))
        else:
            for left_value in left_values:
                left_orphans.append((key, left_value))
    for key, right_values in right_index.items():
        if key not in left_index:
            for right_value in right_values:
                right_orphans.append((key, right_value))

    if diagnostics is not None:
        diagnostics["duplicates"] = left_duplicates + right_duplicates
        diagnostics["conflicts"] = detect_conflicts(left_index, right_index)
        diagnostics["filtered"] = left_invalid + right_invalid
    return matches, left_orphans, right_orphans


def format_report(matches, left_orphans, right_orphans, diagnostics):
    lines = []
    lines.append("matches: %d" % len(matches))
    for row in matches:
        lines.append("  %s -> %s / %s" % row)
    lines.append("left orphans: %s" % (left_orphans or "none"))
    lines.append("right orphans: %s" % (right_orphans or "none"))
    lines.append("duplicate keys: %s" % (diagnostics["duplicates"] or "none"))
    for key, (left_values, right_values) in diagnostics["conflicts"].items():
        lines.append("  conflict on %s: %s vs %s" % (key, left_values, right_values))
    lines.append("filtered rows: %s" % (diagnostics["filtered"] or "none"))
    return "\n".join(lines)


