def parse_rolls(text):
    """Turn a whitespace separated roll description into pin counts."""
    rolls = []
    for token in text.split():
        if token.upper() == "X":
            rolls.append(10)
        elif token.upper() == "F":
            rolls.append(-1)
        else:
            rolls.append(int(token))
    return rolls


def parse_games(text):
    """Read 'name: rolls' lines into a mapping of game name to pin counts."""
    games = {}
    for line in text.strip().splitlines():
        name, _, values = line.partition(":")
        games[name.strip()] = parse_rolls(values)
    return games


def build_scorecard(rolls):
    regular_frames = []
    strike_frames = []
    spare_frames = []
    open_frames = []
    player_totals = {}
    active_bonuses = {}
    fouls = []
    split_conversions = []

    frame = []
    frame_number = 1
    total = 0
    for index, pins in enumerate(rolls):
        if pins < 0:
            fouls.append(index + 1)
            pins = 0
        total += pins
        for owner in sorted(active_bonuses):
            total += pins
            active_bonuses[owner] -= 1
            if active_bonuses[owner] == 0:
                del active_bonuses[owner]
        if frame_number > 10:
            continue
        frame.append(pins)
        if len(frame) == 1 and pins == 10:
            strike_frames.append(frame_number)
            active_bonuses[frame_number] = 2
        elif len(frame) == 2 and sum(frame) == 10:
            spare_frames.append(frame_number)
            active_bonuses[frame_number] = 1
            if frame[0] <= 4:
                split_conversions.append(frame_number)
        elif len(frame) < 2:
            continue
        else:
            open_frames.append(frame_number)
        regular_frames.append((frame_number, tuple(frame)))
        player_totals[frame_number] = total
        frame = []
        frame_number += 1

    return {"total": total, "regular": regular_frames, "strikes": strike_frames,
            "spares": spare_frames, "opens": open_frames, "totals": player_totals,
            "fouls": fouls, "splits": split_conversions}


def score(rolls):
    card = build_scorecard(rolls)
    return card["total"], card["strikes"]


def format_scorecard(name, card):
    lines = []
    lines.append("%s: %d points" % (name, card["total"]))
    lines.append("  frames: " + " ".join("%d%s" % (n, list(f)) for n, f in card["regular"]))
    lines.append("  strikes: %s  spares: %s  opens: %s"
                 % (card["strikes"], card["spares"], card["opens"]))
    if card["fouls"]:
        lines.append("  fouled rolls: %s" % card["fouls"])
    if card["splits"]:
        lines.append("  split conversions: %s" % card["splits"])
    return "\n".join(lines)


