def validate_sequences(sequences):
    """Normalise the incoming strings and reject empty entries."""
    cleaned = []
    for index, seq in enumerate(sequences):
        text = "".join(seq.split()).upper()
        if not text:
            raise ValueError("sequence %d carries no residues" % index)
        cleaned.append(text)
    if len(cleaned) < 2:
        raise ValueError("at least two sequences are required")
    return cleaned


def pad_to_width(sequences, width):
    """Introduce trailing gap characters so every row has the same width."""
    padded = []
    for seq in sequences:
        padded.append(seq + "-" * (width - len(seq)))
    return padded


def column_counts(column):
    counts = {}
    for residue in column:
        counts[residue] = counts.get(residue, 0) + 1
    return counts


def align(sequences):
    cleaned = validate_sequences(sequences)
    lengths = {}
    for index, seq in enumerate(cleaned):
        lengths[index] = len(seq)
    width = max(lengths.values())
    padded = pad_to_width(cleaned, width)

    exact_matches = []
    partial_mismatches = []
    introduced_gaps = []
    unaligned_regions = []
    alignment_scores = {}
    mutation_frequencies = {}
    consensus = []

    for position in range(width):
        column = [row[position] for row in padded]
        counts = column_counts(column)
        if "-" in counts:
            introduced_gaps.append((position, [i for i, c in enumerate(column) if c == "-"]))
        residues = {base: n for base, n in counts.items() if base != "-"}
        dominant = max(sorted(residues), key=lambda base: residues[base])
        consensus.append(dominant)
        alignment_scores[position] = residues[dominant] / float(len(column))
        if len(residues) == 1 and "-" not in counts:
            exact_matches.append(position)
        else:
            partial_mismatches.append((position, sorted(residues)))
            for base, n in residues.items():
                if base != dominant:
                    mutation_frequencies[base] = mutation_frequencies.get(base, 0) + n

    for index, size in lengths.items():
        if size < width:
            unaligned_regions.append((index, size, width))

    consensus_sequences = ["".join(consensus)]
    if consensus_sequences[0] not in cleaned:
        consensus_sequences.append(consensus_sequences[0].replace("-", ""))
    return exact_matches, unaligned_regions


def report_lines(name, exact_matches, unaligned_regions):
    lines = []
    lines.append("%s: %d exact match columns" % (name, len(exact_matches)))
    if unaligned_regions:
        for index, start, end in unaligned_regions:
            lines.append("  sequence %d unaligned from %d to %d" % (index, start, end))
    else:
        lines.append("  no unaligned regions")
    return lines


