    samples = {}
    samples["identical"] = ["ACGTACGT", "ACGTACGT"]
    samples["mutated"] = ["ACGTACGT", "ACGTTCGT", "ACGTACGA"]
    samples["ragged"] = ["ACGTACGT", "ACGTAC"]
    for name in sorted(samples):
        matches, unaligned = align(samples[name])
        for line in report_lines(name, matches, unaligned):
            print(line)


if __name__ == "__main__":
