def build_theater(rows, cols):
    """Return the per-row lists of free seat labels plus every aisle seat."""
    available = []
    aisles = []
    for r in range(rows):
        row_seats = []
        for c in range(cols):
            label = "%d%s" % (r + 1, chr(ord("A") + c))
            row_seats.append(label)
            if c == 0 or c == cols - 1:
