def normalize_cart(raw):
    """Turn a raw cart into a dict with a name, priced items and coupons."""
    if isinstance(raw, dict):
        cart = dict(raw)
    else:
        cart = {"items": list(raw)}
    cart.setdefault("name", "guest")
    cart.setdefault("coupons", [])
    items = []
    for entry in cart.get("items", []):
        if isinstance(entry, (tuple, list)):
            items.append((entry[0], entry[1] if len(entry) > 1 else None))
        else:
            items.append((entry, None))
    cart["items"] = items
    return cart


def open_stations(count):
    """Map each cashier station to the customer it currently serves."""
    stations = {}
    for index in range(count):
        stations["station-%d" % (index + 1)] = None
    return stations


def scan_cart(cart, station, scanned, bagged, delays):
    """Move every priced item of the cart to the scanned and bagged lists."""
    total = 0.0
    for name, price in cart["items"]:
        if price is None:
            delays.append((station, name))
            continue
        scanned.append(name)
        bagged.append(name)
        total += price
    return total


def apply_coupons(cart, total, coupons):
    for code, amount in cart["coupons"]:
        coupons.append(code)
        total -= amount
    return total


def checkout(shoppers):
    scanned = []
    bagged = []
    coupons = []
    voided = []
    receipts = {}
    delays = []
    loyalty = []
    stations = open_stations(max(1, len(list(shoppers)) // 2 + 1))
    lanes = sorted(stations)
    for position, raw in enumerate(shoppers):
        cart = normalize_cart(raw)
        station = lanes[position % len(lanes)]
        stations[station] = cart["name"]
        if cart.get("loyalty_id"):
            loyalty.append((cart["name"], cart["loyalty_id"]))
        total = scan_cart(cart, station, scanned, bagged, delays)
        total = apply_coupons(cart, total, coupons)
        if total < 0 or not cart["items"]:
            voided.append((station, cart["name"]))
        else:
            receipts[cart["name"]] = round(total, 2)
        stations[station] = None
    print(format_report(receipts, coupons, delays, loyalty, len(bagged)))
