def split_path(path):
    """Split a flat path into clean components, collecting parsing errors."""
    errors = []
    if not isinstance(path, str) or not path.strip():
        errors.append("empty or non-string path: %r" % (path,))
        return [], errors
    parts = []
    for raw in path.replace("\\", "/").split("/"):
        comp = raw.strip()
        if comp in ("", "."):
            continue
        if comp == "..":
            errors.append("parent reference not allowed: %s" % path)
            return [], errors
        parts.append(comp)
    if not parts:
        errors.append("no usable components: %s" % path)
    return parts, errors


def extension_of(name):
    if "." in name[1:]:
        return name.rsplit(".", 1)[1].lower()
    return "none"


def build(paths, tree=None):
    """Build a virtual file system tree from flat paths; return (roots, errors)."""
    if tree is None:
        tree = {}
    roots = []
    subdirs = []
    files = []
    links = []
    sizes = {}
    permissions = {}
    extensions = {}
    targets = {}
    errors = []
    for path in paths:
        parts, path_errors = split_path(path)
        errors.extend(path_errors)
        if not parts:
            continue
        for index in range(len(parts) - 1):
            prefix = "/".join(parts[:index + 1])
            if index == 0:
                if prefix not in roots:
                    roots.append(prefix)
            elif prefix not in subdirs:
                subdirs.append(prefix)
        leaf = parts[-1]
        if "->" in leaf:
            name, _, target = leaf.partition("->")
            full = "/".join(parts[:-1] + [name.strip()])
            links.append(full)
            targets[full] = target.strip()
            permissions[full] = "lrwxrwxrwx"
        else:
            full = "/".join(parts)
            files.append(full)
            sizes[full] = 0
            permissions[full] = "rw-r--r--"
            extensions[full] = extension_of(leaf)
    tree.update(roots=roots, subdirs=subdirs, files=files, links=links,
                sizes=sizes, permissions=permissions, extensions=extensions,
                targets=targets, errors=errors)
    return roots, errors


def summarize(tree):
    counts = {}
    for key in ("roots", "subdirs", "files", "links", "errors"):
        counts[key] = len(tree[key])
    lines = []
    for key in ("roots", "subdirs", "files", "links", "errors"):
        lines.append("%-8s %d" % (key + ":", counts[key]))
    for name in tree["files"]:
        lines.append("  file %s (%d bytes, %s, type=%s)"
                     % (name, tree["sizes"][name], tree["permissions"][name],
                        tree["extensions"][name]))
    for name in tree["links"]:
        lines.append("  link %s -> %s (%s)"
                     % (name, tree["targets"][name], tree["permissions"][name]))
    for message in tree["errors"]:
        lines.append("  error %s" % message)
    return lines


def main():
