KNOWN_WORDS = (
    "the", "world", "is", "quiet", "today", "hello", "write", "word", "check",
    "spell", "engine", "text", "correct", "read", "happy", "place",
)
PREFIX_SPEC = ["un=not", "re=again", "pre=before"]
SUFFIX_SPEC = ["s=plural", "ed=past tense", "ing=progressive", "ly=manner"]
CUSTOM_WORDS = ["python", "regex", "tokenizer"]


def build_affix_map(spec):
    mapping = {}
    for entry in spec:
        affix, gloss = entry.split("=")
        mapping[affix.strip()] = gloss.strip()
    return mapping


PREFIXES = build_affix_map(PREFIX_SPEC)
SUFFIXES = build_affix_map(SUFFIX_SPEC)


def split_token(token):
    letters = []
    punctuation = []
    numbers = []
    for char in token:
        if char.isalpha() or char == "'":
            letters.append(char)
        elif char.isdigit():
            numbers.append(char)
        else:
            punctuation.append(char)
    return "".join(letters), punctuation, numbers


def strip_affixes(word, lexicon):
    for prefix in PREFIXES:
        if word.startswith(prefix) and word[len(prefix):] in lexicon:
            return True
    for suffix in SUFFIXES:
        if word.endswith(suffix) and word[:-len(suffix)] in lexicon:
            return True
    return False


def one_edit_apart(first, second):
    if abs(len(first) - len(second)) > 1:
        return False
    if len(first) == len(second):
        return sum(a != b for a, b in zip(first, second)) <= 1
    short, long = sorted((first, second), key=len)
    i = j = skipped = 0
    while i < len(short) and j < len(long):
        if short[i] != long[j]:
            if skipped:
                return False
            skipped = 1
            j += 1
        else:
            i += 1
            j += 1
    return True


def candidates(word, lexicon):
    found = []
    for entry in sorted(lexicon):
        if one_edit_apart(word, entry) or sorted(word) == sorted(entry):
            found.append(entry)
    return found


def analyze(words):
    lexicon = set(KNOWN_WORDS) | {extra.lower() for extra in CUSTOM_WORDS}
    correct = []
    misspelled = []
    ignored = []
    digits = []
    suggestions = {}
    for text in words:
        for token in text.split():
            core, punctuation, numbers = split_token(token)
            ignored.extend(punctuation)
            digits.extend(numbers)
            if not core:
                continue
            lowered = core.lower()
            if lowered in lexicon or strip_affixes(lowered, lexicon):
                correct.append(core)
            else:
                misspelled.append(core)
                suggestions[core] = candidates(lowered, lexicon)
    return {"correct": correct, "misspelled": misspelled, "ignored": ignored,
            "digits": digits, "suggestions": suggestions}


def check(words):
    report = analyze(words)
    return report["misspelled"], report["ignored"]


def format_report(words):
    report = analyze(words)
    lines = []
    lines.append("correct: %d, misspelled: %d, punctuation: %d, digits: %d" % (
        len(report["correct"]), len(report["misspelled"]),
        len(report["ignored"]), len(report["digits"])))
    for bad, options in report["suggestions"].items():
        lines.append("%s -> %s" % (bad, ", ".join(options) or "no suggestion"))
    return "\n".join(lines)


def main():
    misspelled, ignored = check(["hello wrold"])
    print("misspelled words:", misspelled)
    print("ignored punctuation:", len(ignored))
    print(format_report(["The wrold is quiet, 42 today.", "unhappy tokenizer!"]))


if __name__ == "__main__":
    main()

