    ("technical", "dora"), ("technical", "elias"), ("technical", "fabio"),
    ("technical", "gina"), ("sales", "hugo"), ("sales", "ines"),
    ("cancellation", "joana"), ("cancellation", "kai"),
)


def build_agents(roster):
    agents = {}
    for dept, name in roster:
        agents.setdefault(dept, []).append(name)
    return agents


def classify(call):
    dept = call.get("type")
    if call.get("id") is None or dept not in DEPARTMENTS:
        return None
    return dept


def route(calls):
    billing_queue = []
    technical_queue = []
    sales_queue = []
    cancellation_queue = []
    queues = {
        "billing": billing_queue,
        "technical": technical_queue,
        "sales": sales_queue,
        "cancellation": cancellation_queue,
    }
    agents = build_agents(AGENT_ROSTER)
    active = {}
    escalated = []
    dropped = []

    for call in calls:
        dept = classify(call)
        if dept is None:
            dropped.append(call)
            continue
        if call.get("escalated"):
            escalated.append(call)
        queues[dept].append(call)

    for dept, queue in queues.items():
        free = agents.get(dept, [])
        while queue and free:
            agent = free.pop(0)
            active[agent] = queue.pop(0)

    for line in summarize(active, escalated, dropped):
        print(line)
    waiting = sum(len(queue) for queue in queues.values())
    return len(active), waiting


def summarize(active, escalated, dropped):
    counts = {}
    for call in active.values():
        counts[call["type"]] = counts.get(call["type"], 0) + 1
    lines = []
    for dept in sorted(counts):
        lines.append("%-13s %d connected" % (dept, counts[dept]))
    lines.append("escalated     %d" % len(escalated))
    lines.append("dropped       %d" % len(dropped))
    return lines


def main():
    calls = []
    for number in range(50):
        kind = DEPARTMENTS[number % len(DEPARTMENTS)]
        if number % 17 == 0:
            kind = "spam"
        calls.append({
            "id": number,
            "type": kind,
            "escalated": number % 11 == 0,
        })
    connected, waiting = route(calls)
    print("connected=%d waiting=%d" % (connected, waiting))


if __name__ == "__main__":
    main()

