WEIGHTS = {"easy": 1, "medium": 2, "hard": 3}
PASS_MARK = 60.0


def question_difficulty(submissions):
    """Derive a historical difficulty level for every question seen so far."""
    attempts = {}
    registry = {}
    for sub in submissions:
        for qid, ans in sub.get("answers", {}).items():
            stats = attempts.setdefault(qid, [0, 0])
            stats[0] += 1
            if ans.get("given") == ans.get("correct"):
                stats[1] += 1
    for qid, (total, right) in attempts.items():
        rate = right / total
        if rate >= 0.8:
            registry[qid] = "easy"
        elif rate >= 0.5:
            registry[qid] = "medium"
        else:
            registry[qid] = "hard"
    return registry


def score_submission(sub, registry):
    """Return the weighted percentage, the missed questions and per-topic tallies."""
    missed = []
    topics = {}
    earned = 0
    possible = 0
    for qid, ans in sub.get("answers", {}).items():
        weight = WEIGHTS[registry.get(qid, "medium")]
        possible += weight
        tally = topics.setdefault(ans.get("topic", "general"), [0, 0])
        tally[1] += 1
        if ans.get("given") == ans.get("correct"):
            earned += weight
            tally[0] += 1
        else:
            missed.append((qid, ans.get("given")))
    score = round(100.0 * earned / possible, 1) if possible else 0.0
    return score, missed, topics


def review_reasons(sub):
    """Collect the reasons a submission needs a human teacher to look at it."""
    reasons = []
    answers = sub.get("answers", {})
    if not answers:
        reasons.append("empty submission")
    blanks = sum(1 for ans in answers.values() if not ans.get("given"))
    if blanks:
        reasons.append("%d blank answer(s)" % blanks)
    if sub.get("appeal"):
        reasons.append("appeal filed")
    return reasons


def format_report(roster, mastery, mistakes, flagged):
    lines = []
    mastery_pct = {}
    for topic, (right, total) in sorted(mastery.items()):
        mastery_pct[topic] = round(100.0 * right / total, 1)
        lines.append("topic %-10s mastery %5.1f%%" % (topic, mastery_pct[topic]))
    for qid, wrong in sorted(mistakes.items()):
        lines.append("question %s missed by %d: %s" % (qid, len(wrong), ", ".join(wrong)))
    for student, reasons in flagged:
        lines.append("REVIEW %s -> %s" % (student, "; ".join(reasons)))
    for student, score in sorted(roster.items(), key=lambda kv: -kv[1]):
        lines.append("%-6s %5.1f" % (student, score))
    return "\n".join(lines)


def grade(submissions):
    registry = question_difficulty(submissions)
    roster = {}
    perfect = []
    passing = []
    failing = []
    flagged = []
    mistakes = {}
    mastery = {}
    for sub in submissions:
        student = sub.get("student", "unknown")
        score, missed, topics = score_submission(sub, registry)
        roster[student] = score
        for qid, given in missed:
            mistakes.setdefault(qid, []).append(given or "(blank)")
        for topic, (right, total) in topics.items():
            aggregate = mastery.setdefault(topic, [0, 0])
            aggregate[0] += right
            aggregate[1] += total
        reasons = review_reasons(sub)
        if reasons:
            flagged.append((student, reasons))
        if score == 100.0:
            perfect.append(student)
        elif score >= PASS_MARK:
            passing.append(student)
        else:
            failing.append(student)
    average = round(sum(roster.values()) / len(roster), 1) if roster else 0.0
    print(format_report(roster, mastery, mistakes, flagged))
    print("passing: %d  failing: %d  class average: %.1f" % (len(passing), len(failing), average))
    return average, len(perfect)


def main():
    submissions = [
        {"student": "ana", "answers": {
            "q1": {"given": "A", "correct": "A", "topic": "algebra"},
            "q2": {"given": "C", "correct": "C", "topic": "geometry"}}},
        {"student": "ben", "answers": {
            "q1": {"given": "B", "correct": "A", "topic": "algebra"},
            "q2": {"given": "", "correct": "C", "topic": "geometry"}}},
        {"student": "cleo", "appeal": True, "answers": {
            "q1": {"given": "A", "correct": "A", "topic": "algebra"},
            "q2": {"given": "D", "correct": "C", "topic": "geometry"}}},
    ]
    average, perfect_count = grade(submissions)
    print("result:", (average, perfect_count))


if __name__ == "__main__":
    main()

