    index = 0
    for group in stop_groups:
        for stop in group:
            truck_id = truck_ids[index % len(truck_ids)]
            route = routes.setdefault(truck_id, [])
            if len(route) < capacities[truck_id]:
                route.append(stop)
            index += 1
    return routes


