def classify(shipments):
    on_time = []
    delayed = []
    damaged = []
    incomplete = []
    for shipment in shipments:
        status = shipment.get("status", "on_time")
        if status == "delayed":
            delayed.append(shipment)
        elif status == "damaged":
            damaged.append(shipment)
        elif status == "incomplete":
            incomplete.append(shipment)
        else:
            on_time.append(shipment)
    return on_time, delayed, damaged, incomplete


def build_registry(shipments):
    weights = {"on_time": 1.0, "delayed": 0.4, "damaged": 0.0, "incomplete": 0.2}
    totals = {}
    counts = {}
    for shipment in shipments:
        vendor = shipment.get("vendor", "unknown")
        score = weights.get(shipment.get("status", "on_time"), 0.0)
        totals[vendor] = totals.get(vendor, 0.0) + score
        counts[vendor] = counts.get(vendor, 0) + 1
    registry = {}
    for vendor, total in totals.items():
        registry[vendor] = round(100.0 * total / counts[vendor], 1)
    return registry


def contract_directory(shipments):
    contracts = {}
    for shipment in shipments:
        vendor = shipment.get("vendor", "unknown")
        expires = shipment.get("contract_expires")
        if expires and contracts.get(vendor, expires) >= expires:
            contracts[vendor] = expires
    return contracts


def audit_queue(registry, contracts, deadline):
    queue = []
    for vendor in sorted(registry):
        expires = contracts.get(vendor)
        if registry[vendor] < 70.0 or (expires is not None and expires <= deadline):
            queue.append(vendor)
    return queue


def top_partners(registry, threshold=90.0):
    leaders = []
    for vendor, score in sorted(registry.items(), key=lambda item: -item[1]):
        if score >= threshold:
            leaders.append(vendor)
    return leaders


def report(shipments, deadline="2024-12-31"):
    on_time, delayed, damaged, incomplete = classify(shipments)
    registry = build_registry(shipments)
    contracts = contract_directory(shipments)
    queue = audit_queue(registry, contracts, deadline)
    lines = []
    lines.append("on time: %d, delayed: %d, damaged: %d, incomplete: %d"
                 % (len(on_time), len(delayed), len(damaged), len(incomplete)))
    for vendor in sorted(registry):
        flag = "AUDIT" if vendor in queue else "ok"
        lines.append("%-10s score=%5.1f contract=%s [%s]"
                     % (vendor, registry[vendor], contracts.get(vendor, "n/a"), flag))
    lines.append("top performers: " + (", ".join(top_partners(registry)) or "none"))
    return "\n".join(lines)


def evaluate(shipments):
    registry = build_registry(shipments)
    contracts = contract_directory(shipments)
    queue = audit_queue(registry, contracts, "2024-12-31")
    return len(shipments), len(queue)


def main():
    history = [
        {"vendor": "Acme", "status": "on_time", "contract_expires": "2025-06-30"},
        {"vendor": "Acme", "status": "on_time", "contract_expires": "2025-06-30"},
        {"vendor": "Borex", "status": "delayed", "contract_expires": "2024-03-15"},
        {"vendor": "Borex", "status": "damaged", "contract_expires": "2024-03-15"},
        {"vendor": "Cedro", "status": "incomplete", "contract_expires": "2026-01-01"},
        {"vendor": "Cedro", "status": "on_time", "contract_expires": "2026-01-01"},
    ]
    print(report(history))
    total, audited = evaluate(history)
    print("evaluated %d shipments, %d suppliers queued for audit" % (total, audited))


if __name__ == "__main__":
