def classify(reading):
    load = reading.get("load_mw", 0.0)
    supply = reading.get("supply_mw", 0.0)
    if reading.get("outage"):
        return "blackout"
    margin = supply - load
    if margin < -2.0:
        return "high_demand"
    if margin > 2.0:
        return "surplus"
    return "stable"


def collect_generators(reading):
    outputs = dict()
    for unit in reading.get("generators", list()):
        if unit.get("online"):
            outputs[unit["id"]] = float(unit.get("output_mw", 0.0))
    return outputs


def collect_batteries(reading):
    levels = dict()
    for cell in reading.get("batteries", list()):
        levels[cell["id"]] = float(cell.get("charge_pct", 0.0))
    return levels


def summarize(readings):
    high_demand = list()
    stable = list()
    surplus = list()
    blackouts = list()
    generator_outputs = dict()
    battery_registry = dict()
    maintenance_requests = list()
    disconnected_substations = list()

    queues = {
        "high_demand": high_demand,
        "stable": stable,
        "surplus": surplus,
        "blackout": blackouts,
    }

    for reading in readings:
        district = reading.get("district", "unknown")
        queues[classify(reading)].append(district)
        generator_outputs.update(collect_generators(reading))
        batteries = collect_batteries(reading)
        battery_registry.update(batteries)

        for cell_id, charge in batteries.items():
            if charge < 15.0:
                maintenance_requests.append((district, "recharge " + cell_id))

        for station in reading.get("substations", list()):
            if station.get("faulted"):
                disconnected_substations.append(station["id"])
                maintenance_requests.append((district, "repair " + station["id"]))

    for district in high_demand:
        maintenance_requests.append((district, "dispatch reserve power"))

    return {
        "queues": queues,
        "generators": generator_outputs,
        "batteries": battery_registry,
        "requests": maintenance_requests,
        "disconnected": disconnected_substations,
    }


def balance(readings):
    state = summarize(readings)
    return len(state["generators"]), len(state["queues"]["blackout"])


def report(state):
    lines = list()
    for name in ("high_demand", "stable", "surplus", "blackout"):
        lines.append("%s: %s" % (name, ", ".join(state["queues"][name]) or "none"))
    generators = state["generators"]
    lines.append("active generators: %d (%.1f MW)"
                 % (len(generators), sum(generators.values())))
    batteries = state["batteries"]
    if batteries:
        lines.append("mean battery charge: %.1f%%"
                     % (sum(batteries.values()) / len(batteries)))
    for district, action in state["requests"]:
        lines.append("dispatch -> %s: %s" % (district, action))
    lines.append("disconnected substations: %s"
                 % (", ".join(state["disconnected"]) or "none"))
    return "\n".join(lines)


def main():
    grid = [
        {"district": "Harbor", "load_mw": 40.0, "supply_mw": 35.0,
         "generators": [{"id": "G1", "online": True, "output_mw": 20.0},
                        {"id": "G2", "online": False}],
         "batteries": [{"id": "B1", "charge_pct": 12.0}],
         "substations": [{"id": "S1", "faulted": False}]},
        {"district": "Northgate", "load_mw": 22.0, "supply_mw": 30.0,
         "generators": [{"id": "G3", "online": True, "output_mw": 30.0}],
         "batteries": [{"id": "B2", "charge_pct": 88.0}]},
        {"district": "Old Mill", "load_mw": 18.0, "supply_mw": 0.0, "outage": True,
         "substations": [{"id": "S7", "faulted": True}]},
    ]
    print(report(summarize(grid)))
    active, dark = balance(grid)
    print("totals: %d active generators, %d blackout areas" % (active, dark))


