    delivered = []
    for mission in queue:
        drone = mission["drone"]
        level = batteries.get(drone, 0)
        if blocked_by_zone(mission, zones):
            continue
        if mission.get("damaged"):
            if drone not in inspection:
                inspection.append(drone)
            continue
        if level < 25:
            if drone not in recharging:
                recharging.append(drone)
            continue
        batteries[drone] = level - 20
        delivered.append((drone, mission.get("id")))
    return delivered


def direct(missions):
    medical = []
    standard = []
    returns = []
    surveillance = []
    batteries = {}
    zone_entries = []
    recharging = []
    inspection = []
