import re

KEYWORDS = {"var", "def", "for", "import", "print", "true", "false"}
DEPRECATED = {"print": "use the write() builtin instead"}


def tokenize(source):
    """Split raw source text into keyword/argument tokens, one per statement."""
    tokens = []
    for lineno, raw in enumerate(source.splitlines(), 1):
        text = raw.strip()
        if not text or text.startswith("#"):
            continue
        parts = text.split()
        tokens.append({"line": lineno, "keyword": parts[0], "args": parts[1:]})
    return tokens


def symbol_refs(expression):
    """Return the identifiers an expression depends on."""
    refs = []
    for word in re.findall(r"[A-Za-z_]\w*", expression):
        if word not in KEYWORDS:
            refs.append(word)
    return refs


def build_tree(tokens):
    variables = []
    functions = []
    loops = []
    imports = []
    global_scope = {}
    unresolved = {}
    errors = []
    warnings = []
    statements = 0
    for token in tokens:
        keyword, args, line = token["keyword"], token["args"], token["line"]
        statements += 1
        if keyword == "var":
            if len(args) < 3 or args[1] != "=":
                errors.append("line %d: malformed variable declaration" % line)
                continue
            value = " ".join(args[2:])
            variables.append({"name": args[0], "line": line})
            for ref in symbol_refs(value):
                if ref not in global_scope:
                    unresolved.setdefault(ref, []).append(line)
            global_scope[args[0]] = value
        elif keyword == "def":
            if not args:
                errors.append("line %d: function needs a name" % line)
                continue
            functions.append({"name": args[0], "params": args[1:], "line": line})
            global_scope[args[0]] = "<function>"
        elif keyword == "for":
            if len(args) < 2:
                errors.append("line %d: loop needs a variable and a range" % line)
                continue
            loops.append({"variable": args[0], "line": line})
            global_scope[args[0]] = "<loop var>"
        elif keyword == "import":
            if not args:
                errors.append("line %d: import needs a module" % line)
                continue
            imports.append({"module": args[0], "line": line})
            global_scope[args[0]] = "<module>"
        elif keyword in DEPRECATED:
            warnings.append("line %d: '%s' is deprecated, %s" % (line, keyword, DEPRECATED[keyword]))
        else:
            errors.append("line %d: unknown keyword '%s'" % (line, keyword))
    pending = {}
    for name, lines in unresolved.items():
        if name not in global_scope:
            pending[name] = lines
    return {"variables": variables, "functions": functions, "loops": loops,
            "imports": imports, "scope": global_scope, "unresolved": pending,
            "errors": errors, "warnings": warnings, "statements": statements}


def parse(tokens):
    tree = build_tree(tokens)
    return tree["statements"], len(tree["errors"])


def format_report(tree):
    groups = {}
    for section in ("variables", "functions", "loops", "imports"):
        groups[section] = len(tree[section])
    lines = ["parsed %d statements" % tree["statements"]]
    for section, count in groups.items():
        lines.append("  %-10s %d" % (section, count))
    for name, refs in sorted(tree["unresolved"].items()):
        lines.append("  unresolved '%s' at lines %s" % (name, refs))
    lines.extend("  error: " + message for message in tree["errors"])
    lines.extend("  warning: " + message for message in tree["warnings"])
    return "\n".join(lines)


def main():
    source = """
# demo program
import math
var total = 0
var area = math * radius
def scale factor
for i range
print total
whoops here
var broken 5
"""
    tokens = tokenize(source)
    print(format_report(build_tree(tokens)))
    print("parse() ->", parse(tokens))


if __name__ == "__main__":
    main()

