PLATFORM_LIMIT = 60


def build_queues(commuters):
    inbound = []
    outbound = []
    express = []
    delayed = []
    for record in commuters:
        if record.get("delayed"):
            delayed.append(record)
        elif record.get("express"):
            express.append(record)
        elif record.get("direction") == "inbound":
            inbound.append(record)
        else:
            outbound.append(record)
    return inbound, outbound, express, delayed


def platform_capacities(commuters):
    capacities = {}
    for record in commuters:
        station = record.get("station", "unknown")
        if station not in capacities:
            capacities[station] = PLATFORM_LIMIT
        capacities[station] -= record.get("count", 0)
    return capacities


def maintenance_directory(commuters):
    tracks = {}
    for record in commuters:
        work = record.get("maintenance")
        if work:
            tracks.setdefault(record.get("station", "unknown"), []).append(work)
    return tracks


def congestion_alerts(capacities):
    alerts = []
    for station, remaining in sorted(capacities.items()):
        if remaining < 0:
            alerts.append("%s: over capacity by %d" % (station, -remaining))
    return alerts


def offline_kiosks(commuters):
    offline = []
    for record in commuters:
        station = record.get("station", "unknown")
        for kiosk in record.get("kiosks", []):
            if kiosk.get("status") == "offline":
                offline.append("%s/%s" % (station, kiosk.get("id", "?")))
    return offline


def format_report(capacities, tracks, alerts, offline):
    lines = []
    for station in sorted(capacities):
        lines.append("platform %s free seats: %d" % (station, capacities[station]))
    for station in sorted(tracks):
        lines.append("maintenance at %s: %s" % (station, ", ".join(tracks[station])))
    lines.extend(alerts)
    if offline:
        lines.append("offline kiosks: " + ", ".join(offline))
    return "\n".join(lines)


def guide(commuters):
    inbound, outbound, express, delayed = build_queues(commuters)
    capacities = platform_capacities(commuters)
    tracks = maintenance_directory(commuters)
    alerts = congestion_alerts(capacities)
    offline = offline_kiosks(commuters)
    print(format_report(capacities, tracks, alerts, offline))
    print("delayed services held: %d" % len(delayed))
    active_trains = len(inbound) + len(outbound) + len(express)
    return active_trains, len(alerts)


def main():
    commuters = [
        {"station": "Central", "direction": "inbound", "count": 45},
        {"station": "Central", "direction": "inbound", "count": 30,
         "kiosks": [{"id": "K1", "status": "offline"}]},
        {"station": "Riverside", "direction": "outbound", "count": 22,
         "maintenance": "signal replacement"},
        {"station": "Airport", "direction": "inbound", "count": 50, "express": True},
        {"station": "Depot", "direction": "outbound", "count": 12, "delayed": True},
    ]
    trains, warnings = guide(commuters)
    print("active trains: %d, congestion alerts: %d" % (trains, warnings))


if __name__ == "__main__":
