BLOCKLIST_THRESHOLD = 3
FAILED_LOGIN_LIMIT = 2


def parse_log(line):
    """Turn 'key=value;key=value' text into a dictionary."""
    record = {}
    for field in line.strip().split(";"):
        if "=" in field:
            key, value = field.split("=", 1)
            record[key.strip()] = value.strip()
    return record


def load_signatures():
    """Known malware signatures mapped to the family they belong to."""
    signatures = {}
    signatures["eicar"] = "test-file"
    signatures["mimikatz"] = "credential-dumper"
    signatures["cobaltstrike"] = "beacon"
    return signatures


def match_signature(payload, signatures):
    lowered = payload.lower()
    for token, family in signatures.items():
        if token in lowered:
            return family
    return None


def correlate(logs):
    blocked_addresses = []
    suspicious_payloads = []
    unauthorized_logins = []
    background_traffic = []
    signatures = load_signatures()
    compromised_accounts = {}
    severe_alerts = []
    offline_sensors = []
    hit_counts = {}

    for line in logs:
        record = parse_log(line)
        source = record.get("src", "unknown")
        sensor = record.get("sensor", "unknown")
        if record.get("status") == "sensor_down":
            offline_sensors.append(sensor)
            continue
        family = match_signature(record.get("payload", ""), signatures)
        if family:
            suspicious_payloads.append((source, family))
            severe_alerts.append("malware %s from %s" % (family, source))
            hit_counts[source] = hit_counts.get(source, 0) + 1
        elif record.get("event") == "login_failed":
            user = record.get("user", "unknown")
            unauthorized_logins.append((source, user))
            attempts = compromised_accounts.setdefault(user, [])
            attempts.append(source)
            if len(attempts) >= FAILED_LOGIN_LIMIT:
                severe_alerts.append("account %s under attack" % user)
                hit_counts[source] = hit_counts.get(source, 0) + 1
        else:
            background_traffic.append(source)
        if hit_counts.get(source, 0) >= BLOCKLIST_THRESHOLD:
            if source not in blocked_addresses:
                blocked_addresses.append(source)

    for alert in severe_alerts:
        print("ALERT:", alert)
    print("normal packets: %d, offline sensors: %d" %
          (len(background_traffic), len(offline_sensors)))
    print("distinct suspicious payloads: %d, failed logins: %d" %
          (len(suspicious_payloads), len(unauthorized_logins)))
    return blocked_addresses, compromised_accounts


def main():
    logs = [
        "sensor=s1;src=10.0.0.5;payload=hello world",
        "sensor=s1;src=10.0.0.9;payload=EICAR-test",
        "sensor=s1;src=10.0.0.9;payload=mimikatz dump",
        "sensor=s2;status=sensor_down",
        "sensor=s1;src=10.0.0.9;event=login_failed;user=admin",
        "sensor=s1;src=10.0.0.9;event=login_failed;user=admin",
        "sensor=s1;src=10.0.0.5;event=login_failed;user=guest",
    ]
    blocked, accounts = correlate(logs)
    print("blocked:", ", ".join(blocked) or "none")
    for user, origins in sorted(accounts.items()):
        print("compromised %s via %s" % (user, ", ".join(origins)))


if __name__ == "__main__":
    main()

def classify(animal):
    """Return the routing bucket for one animal record."""
    if animal.get("needs_medical"):
        return "medical"
    if animal.get("age_months", 12) < 4:
        return "foster"
    if animal.get("applicant") is None:
        return "intake"
    return "adopt"


def collect_walkers(animals):
    """Build a directory mapping neighbourhood -> volunteer dog walkers."""
    walkers = {}
    for animal in animals:
        if animal.get("species") != "dog":
            continue
        area = animal.get("area", "unassigned")
        if area not in walkers:
            walkers[area] = []
        for name in animal.get("volunteers", ()):
            if name not in walkers[area]:
                walkers[area].append(name)
    return walkers


def vaccination_schedule(animals, start_day=1):
    """Assign each unvaccinated animal a clinic day, two per day."""
    appointments = []
    pending = [a["name"] for a in animals if not a.get("vaccinated")]
    for index, name in enumerate(pending):
        appointments.append((name, start_day + index // 2))
    return appointments


def pair(animals):
    adopted_dogs = []
    adopted_cats = []
    medical_care = []
    foster_homes = []
    background_checks = {}
    surrender_queue = []
    for animal in animals:
        bucket = classify(animal)
        if bucket == "medical":
            medical_care.append(animal["name"])
        elif bucket == "foster":
            foster_homes.append(animal["name"])
        elif bucket == "intake":
            surrender_queue.append(animal["name"])
        else:
            applicant = animal["applicant"]
            background_checks[applicant] = animal.get("check", "pending")
            if background_checks[applicant] == "cleared":
                if animal.get("species") == "dog":
                    adopted_dogs.append((animal["name"], applicant))
                else:
                    adopted_cats.append((animal["name"], applicant))
            else:
                foster_homes.append(animal["name"])
    walkers = collect_walkers(animals)
    clinic = vaccination_schedule(animals)
    report(adopted_dogs, adopted_cats, medical_care, foster_homes,
           surrender_queue, walkers, clinic)
    adopted = adopted_dogs + adopted_cats
    still_pending = {k: v for k, v in background_checks.items() if v != "cleared"}
    return adopted, still_pending


def report(dogs, cats, medical, foster, queue, walkers, clinic):
    lines = []
    lines.append("Adopted dogs: %d, adopted cats: %d" % (len(dogs), len(cats)))
    lines.append("Medical care: " + (", ".join(medical) or "none"))
    lines.append("Foster homes: " + (", ".join(foster) or "none"))
    lines.append("Surrender queue: " + (", ".join(queue) or "empty"))
    for area in sorted(walkers):
        lines.append("Walkers in %s: %s" % (area, ", ".join(walkers[area])))
    by_day = {}
    for name, day in clinic:
        by_day.setdefault(day, []).append(name)
    for day in sorted(by_day):
        lines.append("Clinic day %d: %s" % (day, ", ".join(by_day[day])))
    print("\n".join(lines))


def main():
    shelter = [
        {"name": "Rex", "species": "dog", "applicant": "Diaz", "check": "cleared",
         "area": "north", "volunteers": ["Ana", "Ben"], "vaccinated": True},
        {"name": "Mimi", "species": "cat", "applicant": "Okoro", "check": "cleared"},
        {"name": "Bolt", "species": "dog", "applicant": "Smith", "check": "pending",
         "area": "north", "volunteers": ["Ana"]},
        {"name": "Pip", "species": "cat", "applicant": "Lee", "age_months": 2},
        {"name": "Duke", "species": "dog", "applicant": "Nair", "needs_medical": True},
        {"name": "Shadow", "species": "cat", "applicant": None},
    ]
    adopted, pending = pair(shelter)
    print("Placed: %s" % ", ".join("%s -> %s" % pairing for pairing in adopted))
    print("Pending checks: %s" % ", ".join(sorted(pending)))


if __name__ == "__main__":
    main()

