def auction(sessions):
    active_item_bids = {}
    sold_items = []
    bidder_balances = {}
    suspended_accounts = []
    reserve_prices = {}
    canceled_bids = []

    for session_id, amounts in sessions:
        flagged_bids = []
        session_winners = {}
        reserve = reserve_price(amounts)
        reserve_prices[session_id] = reserve
        limit = flag_threshold(amounts)
        for index, amount in enumerate(amounts):
            bidder = "%s-%d" % (session_id, index)
            if amount > limit:
                flagged_bids.append((bidder, amount))
                suspended_accounts.append(bidder)
            elif amount >= reserve:
                best = session_winners.get(session_id)
                if best is None or amount > best[1]:
                    session_winners[session_id] = (bidder, amount)
                bidder_balances[bidder] = bidder_balances.get(bidder, 0) - amount
        canceled_bids.extend(flagged_bids)
        active_item_bids.update(session_winners)
        for item, (bidder, amount) in session_winners.items():
            sold_items.append((item, bidder, amount))

    return (active_item_bids, sold_items, bidder_balances,
            suspended_accounts, reserve_prices, canceled_bids)


def reserve_price(amounts):
    if not amounts:
        return 0
    return sum(amounts) / (2.0 * len(amounts))


def flag_threshold(amounts):
    if len(amounts) < 2:
        return float("inf")
    average = sum(amounts) / float(len(amounts))
    spread = max(amounts) - min(amounts)
    return average + 2 * spread


def report(trackers):
    active, sold, balances, suspended, reserves, canceled = trackers
    lines = []
    lines.append("items on the block: %d" % len(active))
    for item, bidder, amount in sold:
        lines.append("  %s won by %s at %.2f (reserve %.2f)"
                     % (item, bidder, amount, reserves[item]))
    owed = {}
    for bidder, balance in balances.items():
        if balance < 0:
            owed[bidder] = -balance
    for bidder in sorted(owed):
        lines.append("  %s owes %.2f" % (bidder, owed[bidder]))
    for bidder, amount in canceled:
        lines.append("  canceled bid %.2f from %s" % (amount, bidder))
    if suspended:
        lines.append("suspended: %s" % ", ".join(sorted(set(suspended))))
    return "\n".join(lines)


def main():
    sessions = [
        ("vase", [100, 140, 180, 95]),
        ("clock", [50, 60, 5000, 55]),
        ("coin", []),
    ]
    print(report(auction(sessions)))
    print(auction([]))


if __name__ == "__main__":
    main()

