def normalize(request):
    """Return a (patient, severity, ward) triple from a raw admission request."""
    if len(request) != 3:
        raise ValueError("an admission request needs a patient, a severity and a ward")
    patient, severity, ward = request
    return str(patient), str(severity).strip().lower(), str(ward).strip()


def hospital(shifts):
    available_beds = {}
    discharged_patients = []
    ward_capacities = {}
    waitlisted_patients = []
    staff_assignments = {}
    emergency_transfers = []
    for shift_time, requests in shifts:
        critical_alerts = []
        temporary_rooms = {}
        for request in requests:
            patient, severity, ward = normalize(request)
            if severity == "severe":
                critical_alerts.append((patient, ward))
            elif severity == "standard":
                temporary_rooms[patient] = ward
                ward_capacities[ward] = ward_capacities.get(ward, 0) + 1
                if shift_time not in staff_assignments:
                    staff_assignments[shift_time] = []
                staff_assignments[shift_time].append(patient)
            elif severity == "discharged":
                discharged_patients.append(patient)
            elif severity == "waitlisted":
                waitlisted_patients.append(patient)
            else:
                raise ValueError("unknown severity %r for patient %s" % (severity, patient))
        for patient, ward in critical_alerts:
            emergency_transfers.append((shift_time, patient, ward))
        available_beds.update(temporary_rooms)
    return (
        available_beds,
        discharged_patients,
        ward_capacities,
        waitlisted_patients,
        staff_assignments,
        emergency_transfers,
    )


def occupancy_report(available_beds, ward_capacities, emergency_transfers):
    """Format a short textual summary of the allocation state."""
    by_ward = {}
    for patient, ward in available_beds.items():
        if ward not in by_ward:
            by_ward[ward] = []
        by_ward[ward].append(patient)
    lines = []
    for ward in sorted(by_ward):
        occupants = ", ".join(sorted(by_ward[ward]))
        lines.append("%s: %d admitted (%s)" % (ward, ward_capacities[ward], occupants))
    for shift_time, patient, ward in emergency_transfers:
        lines.append("TRANSFER %s -> %s during %s" % (patient, ward, shift_time))
    return lines


def main():
    shifts = [
        ("morning", [("Ana", "standard", "Cardiology"),
                     ("Bo", "severe", "ICU"),
                     ("Cleo", "waitlisted", "Cardiology")]),
        ("night", [("Dov", "standard", "Cardiology"),
                   ("Ana", "discharged", "Cardiology"),
                   ("Eve", "standard", "Neurology")]),
    ]
    beds, discharged, capacities, waitlist, staff, transfers = hospital(shifts)
    for line in occupancy_report(beds, capacities, transfers):
        print(line)
    print("discharged:", discharged)
    print("waitlisted:", waitlist)
    for shift_time in sorted(staff):
        print("staff on %s cover %s" % (shift_time, staff[shift_time]))
    print("empty run:", hospital([]))


if __name__ == "__main__":
    main()

