FIELDS = ("ticket", "item", "quantity", "allergens", "customizations", "tip", "oven", "delivery")


def normalize_order(detail):
    """Turn a raw order detail (tuple or mapping) into a complete order dict."""
    if isinstance(detail, dict):
        order = dict(detail)
    else:
        order = {}
        for field, value in zip(FIELDS, detail):
            order[field] = value
    order.setdefault("quantity", 1)
    order.setdefault("allergens", [])
    order.setdefault("customizations", {})
    order.setdefault("tip", 0.0)
    return order


def fulfillable(warning):
    """A sensitive order can be served only if a free-from substitute is stocked."""
    _ticket, allergens, quantity = warning
    for allergen in allergens:
        if INVENTORY.get(allergen + "_free", 0) < quantity:
            return False
    return True


def pizzeria(shifts):
    global INVENTORY, COMPLETED_ORDERS, DRIVER_TIPS
    global VOIDED_TICKETS, OVEN_TEMPS, PENDING_DELIVERIES
    INVENTORY = {}
    COMPLETED_ORDERS = []
    DRIVER_TIPS = {}
    VOIDED_TICKETS = []
    OVEN_TEMPS = {}
    PENDING_DELIVERIES = []
    for period, details in shifts:
        allergy_warnings = []
        special_requests = {}
        for detail in details:
            order = normalize_order(detail)
            if order["allergens"]:
                allergy_warnings.append(
                    (order["ticket"], order["allergens"], order["quantity"]))
            for ingredient, amount in order["customizations"].items():
                special_requests[ingredient] = special_requests.get(ingredient, 0) + amount
            if order.get("oven") is not None:
                OVEN_TEMPS[period] = max(OVEN_TEMPS.get(period, 0), order["oven"])
            driver = order.get("delivery")
            if driver:
                PENDING_DELIVERIES.append((order["ticket"], driver))
                DRIVER_TIPS[driver] = round(DRIVER_TIPS.get(driver, 0.0) + order["tip"], 2)
            COMPLETED_ORDERS.append((period, order["ticket"], order["item"]))
        dropped = set()
        for warning in allergy_warnings:
            if not fulfillable(warning):
                VOIDED_TICKETS.append(warning[0])
                dropped.add(warning[0])
        COMPLETED_ORDERS = [row for row in COMPLETED_ORDERS if row[1] not in dropped]
        INVENTORY.update(special_requests)
    return (INVENTORY, COMPLETED_ORDERS, DRIVER_TIPS,
            VOIDED_TICKETS, OVEN_TEMPS, PENDING_DELIVERIES)


def shift_report(completed, voided, tips, temps):
    per_period = {}
    for period, _ticket, item in completed:
        per_period.setdefault(period, []).append(item)
    lines = []
    for period in sorted(per_period):
        served = ", ".join(per_period[period])
        lines.append("%s (oven %s): %s" % (period, temps.get(period, "off"), served))
    lines.append("voided: " + (", ".join(voided) if voided else "none"))
    for driver in sorted(tips):
        lines.append("tips %s: %.2f" % (driver, tips[driver]))
    return lines


def main():
    shifts = [
        ("morning", [
            ("T1", "margherita", 1, [], {"gluten_free": 4, "dough": 20}, 0.0, 430, None),
            ("T2", "calzone", 2, ["gluten"], {}, 3.5, 450, "Ana"),
        ]),
        ("evening", [
            ("T3", "quattro formaggi", 1, ["gluten"], {"cheese": 6}, 5.0, 460, "Ben"),
            {"ticket": "T4", "item": "marinara", "oven": 440, "tip": 2.25, "delivery": "Ana"},
        ]),
    ]
    inventory, completed, tips, voided, temps, deliveries = pizzeria(shifts)
    for line in shift_report(completed, voided, tips, temps):
        print(line)
    print("inventory:", inventory)
    print("pending deliveries:", deliveries)
    print("empty service:", pizzeria([]))


if __name__ == "__main__":
    main()

