HIGH_SURGE = 900.0
LOW_OUTPUT = 100.0


def parse_readings(raw):
    """Turn a raw sequence of readings into a list of floats, dropping gaps."""
    readings = []
    for item in raw:
        if item is None or item == "":
            continue
        readings.append(float(item))
    return readings


def solar(days):
    panel_outputs = {}
    offline_arrays = []
    grid_contributions = {}
    maintenance_requests = []
    battery_temperatures = {}
    grid_faults = []

    for date, raw in days:
        peak_surges = []
        localized_shading = {}
        readings = parse_readings(raw)

        for index, value in enumerate(readings):
            array_id = "%s#%d" % (date, index)
            if value >= HIGH_SURGE:
                peak_surges.append((array_id, value))
            elif value < LOW_OUTPUT:
                localized_shading[array_id] = value
            if value == 0.0:
                offline_arrays.append(array_id)

        if readings:
            grid_contributions[date] = round(sum(readings), 2)
            battery_temperatures[date] = round(20.0 + max(readings) / 100.0, 2)
        else:
            maintenance_requests.append((date, "no telemetry received"))

        if len(localized_shading) > 2:
            maintenance_requests.append((date, "clean %d arrays" % len(localized_shading)))

        grid_faults.extend(peak_surges)
        panel_outputs.update(localized_shading)

    return (panel_outputs, offline_arrays, grid_contributions,
            maintenance_requests, battery_temperatures, grid_faults)


def format_report(result):
    """Render the six structures returned by solar() as printable lines."""
    outputs, offline, contributions, maintenance, temperatures, faults = result
    faults_by_date = {}
    for array_id, value in faults:
        date = array_id.split("#")[0]
        faults_by_date.setdefault(date, []).append(value)

    lines = []
    for date in sorted(contributions):
        lines.append("%s: %.2f kWh, battery %.2f C, surges %d" % (
            date, contributions[date], temperatures[date],
            len(faults_by_date.get(date, []))))
    for array_id in sorted(outputs):
        lines.append("  shaded %s at %.1f W" % (array_id, outputs[array_id]))
    for array_id in offline:
        lines.append("  offline %s" % array_id)
    for date, note in maintenance:
        lines.append("  ticket %s: %s" % (date, note))
    return lines


def main():
