SUSPICIOUS_LIMIT = 10000.0
REVIEW_LIMIT = 5000.0


def normalize_cycles(raw):
    """Turn raw submissions into (cycle_id, [amount, ...]) tuples."""
    cycles = []
    for entry in raw:
        cycle_id, raw_amounts = entry
        amounts = []
        for value in raw_amounts:
            try:
                amounts.append(float(value))
            except (TypeError, ValueError):
                continue
        cycles.append((str(cycle_id), amounts))
    return cycles


def insurance(cycles):
    policy_deductibles = {}
    approved_claims = []
    adjuster_workloads = {}
    rejected_applications = []
    client_premiums = {}
    pending_reviews = []

    for index, (cycle_id, amounts) in enumerate(cycles):
        fraudulent_flags = []
        coverage_adjustments = {}
        adjuster = "adjuster-%d" % (index % 3 + 1)
        for position, amount in enumerate(amounts):
            if amount < 0 or amount > SUSPICIOUS_LIMIT:
                fraudulent_flags.append((cycle_id, position, amount))
                continue
            coverage_adjustments[position] = round(amount * 0.9, 2)
            adjuster_workloads[adjuster] = adjuster_workloads.get(adjuster, 0) + 1
            if amount >= REVIEW_LIMIT:
                pending_reviews.append((cycle_id, position, amount))
            else:
                approved_claims.append((cycle_id, position, amount))
        covered = sum(coverage_adjustments.values())
        policy_deductibles[cycle_id] = round(covered * 0.05, 2)
        rejected_applications.append(fraudulent_flags)
        client_premiums.setdefault(cycle_id, {}).update(coverage_adjustments)

    return (policy_deductibles, approved_claims, adjuster_workloads,
            rejected_applications, client_premiums, pending_reviews)


def format_report(trackers):
    deductibles, approved, workloads, rejected, premiums, pending = trackers
    lines = []
    flagged = []
    for batch in rejected:
        flagged.extend(batch)
    lines.append("cycles reviewed: %d" % len(deductibles))
    lines.append("approved claims: %d" % len(approved))
    lines.append("pending reviews: %d" % len(pending))
    lines.append("flagged amounts: %d" % len(flagged))
    for adjuster in sorted(workloads):
        lines.append("  %s handled %d claim(s)" % (adjuster, workloads[adjuster]))
    for cycle_id in sorted(premiums):
        adjustments = premiums[cycle_id]
        total = round(sum(adjustments.values()), 2)
        lines.append("  %s: premium %.2f, deductible %.2f"
                     % (cycle_id, total, deductibles[cycle_id]))
    for cycle_id, position, amount in flagged:
        lines.append("  FLAG %s slot %d amount %.2f" % (cycle_id, position, amount))
    return lines


def main():
    submissions = [
        ("C-1001", [1200, 4999.5, "bad", 7500]),
        ("C-1002", [-40, 250, 12000, 3000]),
        ("C-1003", []),
    ]
    trackers = insurance(normalize_cycles(submissions))
    for line in format_report(trackers):
        print(line)
    print("empty run:", insurance([]))


if __name__ == "__main__":
    main()

def parse_request(raw):
    """Normalise a raw patron request into a predictable dictionary."""
    request = {}
    request['patron'] = str(raw['patron']).strip()
    request['tier'] = str(raw.get('tier', 'standard')).lower()
    request['screen'] = str(raw.get('screen', 'main'))
    request['seats'] = max(1, int(raw.get('seats', 1)))
    request['spend'] = round(float(raw.get('spend', 0.0)), 2)
    request['refund'] = bool(raw.get('refund', False))
    request['premiere'] = raw.get('premiere')
    return request


def request_order(raw):
    return (str(raw.get('screen', 'main')), str(raw['patron']))


def theater(weekends):
    screen_capacities = {}
    sold_tickets = []
    concession_revenue = {}
    refunded_purchases = []
    member_points = {}
    upcoming_premieres = []
    for date, requests in weekends:
        upgrade_requests = []
        seat_allocations = {}
        for raw in sorted(requests, key=request_order):
            request = parse_request(raw)
            patron = request['patron']
            screen = request['screen']
            if request['refund']:
                refunded_purchases.append((date, patron, request['spend']))
                continue
            if request['tier'] == 'premium':
                upgrade_requests.append((date, patron, screen, request['seats']))
            else:
                seat_allocations[screen] = seat_allocations.get(screen, 0) + request['seats']
            concession_revenue[screen] = round(
                concession_revenue.get(screen, 0.0) + request['spend'], 2)
            member_points[patron] = member_points.get(patron, 0) + request['seats'] * 10
            if request['premiere']:
                upcoming_premieres.append((date, request['premiere']))
        sold_tickets.extend(upgrade_requests)
        for screen, seats in seat_allocations.items():
            screen_capacities[screen] = screen_capacities.get(screen, 0) + seats
    return (screen_capacities, sold_tickets, concession_revenue,
            refunded_purchases, member_points, upcoming_premieres)


def summarize(trackers):
    capacities, sold, concessions, refunds, points, premieres = trackers
    lines = []
    for screen in sorted(capacities):
        lines.append("{}: {} standard seats, {:.2f} concessions".format(
            screen, capacities[screen], concessions.get(screen, 0.0)))
    lines.append("premium upgrades sold: {}".format(len(sold)))
    refund_totals = {}
    for _date, patron, amount in refunds:
        refund_totals[patron] = round(refund_totals.get(patron, 0.0) + amount, 2)
    for patron in sorted(refund_totals):
        lines.append("refunded {}: {:.2f}".format(patron, refund_totals[patron]))
    ranking = []
    for patron, earned in points.items():
        ranking.append((-earned, patron))
    for earned, patron in sorted(ranking):
        lines.append("member {} holds {} points".format(patron, -earned))
    for date, title in premieres:
        lines.append("premiere {} on {}".format(title, date))
    return "\n".join(lines)


