SOLOIST_FEE = 150
VENUE_RATE = 20


def parse_code(code):
    """Split an availability code into its kind and payload."""
    kind, _, payload = code.partition(":")
    return kind.strip().lower(), payload.strip()


def orchestra(seasons):
    global salaries, performances, repairs, absent, venue_fees, special_rehearsals
    salaries = {}
    performances = []
    repairs = {}
    absent = []
    venue_fees = {}
    special_rehearsals = []

    for season_name, codes in seasons:
        guest_soloists = []
        piece_durations = {}
        for code in codes:
            kind, payload = parse_code(code)
            if kind == "solo":
                guest_soloists.append(payload)
                salaries[payload] = salaries.get(payload, 0) + SOLOIST_FEE
            elif kind == "piece":
                title, _, minutes = payload.partition("/")
                piece_durations[title.strip()] = int(minutes) if minutes.strip() else 0
            elif kind == "repair":
                repairs[payload] = repairs.get(payload, 0) + 1
            elif kind == "absent":
                absent.append(payload)
                if payload in salaries:
                    salaries[payload] -= SOLOIST_FEE
            elif kind == "rehearsal":
                special_rehearsals.append((season_name, payload))
        performances.extend("%s: %s" % (season_name, guest) for guest in guest_soloists)
        venue_fees.update(
            ("%s/%s" % (season_name, title), length * VENUE_RATE)
            for title, length in piece_durations.items()
        )

    return salaries, performances, repairs, absent, venue_fees, special_rehearsals


def report(records):
    """Turn the six records into printable report lines."""
    pay, shows, fixes, missing, fees, extras = records
    by_season = {}
    for entry in shows:
        season_name, _, guest = entry.partition(": ")
        by_season.setdefault(season_name, []).append(guest)
    lines = []
    for season_name in sorted(by_season):
        lines.append("%s -> %s" % (season_name, ", ".join(by_season[season_name])))
    lines.append("payroll: %d" % sum(pay.values()))
    lines.append("repairs: %d" % sum(fixes.values()))
    lines.append("venue total: %d" % sum(fees.values()))
    if missing:
        lines.append("absent: %s" % ", ".join(missing))
    for season_name, label in extras:
        lines.append("extra rehearsal in %s: %s" % (season_name, label))
    return lines


def main():
    plan = [
        ("Spring", ["solo:Anna", "piece:Fugue/12", "repair:Cello", "rehearsal:strings"]),
        ("Summer", ["solo:Bela", "solo:Cora", "piece:Nocturne/9", "absent:Bela"]),
        ("Autumn", ["piece:Overture/15", "repair:Cello", "repair:Oboe"]),
    ]
    for line in report(orchestra(plan)):
        print(line)
    print(orchestra([]))


if __name__ == "__main__":
    main()

