def parse_period(name, raw):
    """Turn raw 'label=value' strings into (label, value) measurement tuples."""
    measurements = []
    for item in raw:
        if isinstance(item, tuple):
            measurements.append(item)
            continue
        label, _, number = item.partition("=")
        measurements.append((label.strip(), float(number)))
    return (name, measurements)


def greenhouse(seasons):
    soil_moistures = {}
    bloomed_flowers = []
    fertilizer_levels = {}
    diseased_plants = []
    sunlight_hours = {}
    new_cuttings = []

    for name, measurements in seasons:
        pest_sightings = []
        humidity_adjustments = {}
        fertilizer = 0.0
        for label, value in measurements:
            if value < 0:
                pest_sightings.append((name, label, value))
            else:
                humidity_adjustments["%s:%s" % (name, label)] = value
                fertilizer += value
            if value >= 8:
                bloomed_flowers.append((name, label))
            elif 0 <= value < 1:
                new_cuttings.append((name, label))
        fertilizer_levels[name] = round(fertilizer, 2)
        sunlight_hours[name] = len(measurements)
        diseased_plants.extend(pest_sightings)
        soil_moistures.update(humidity_adjustments)

    return (soil_moistures, bloomed_flowers, fertilizer_levels,
            diseased_plants, sunlight_hours, new_cuttings)


def summarize(trackers):
    soil_moistures, bloomed, fertilizer, diseased, sunlight, cuttings = trackers
    report = {}
    for season in sunlight:
        readings = {}
        for key, value in soil_moistures.items():
            period, _, label = key.partition(":")
            if period == season:
                readings[label] = value
        report[season] = {
            "readings": readings,
            "fertilizer": fertilizer[season],
            "measurements": sunlight[season],
            "blooms": [label for period, label in bloomed if period == season],
            "pests": [label for period, label, _ in diseased if period == season],
            "cuttings": [label for period, label in cuttings if period == season],
        }
    return report


def format_report(report):
    lines = []
    for season in sorted(report):
        data = report[season]
        lines.append("%s: %d readings, fertilizer %.2f" %
                     (season, data["measurements"], data["fertilizer"]))
        for kind in ("blooms", "pests", "cuttings"):
            if data[kind]:
                lines.append("  %s -> %s" % (kind, ", ".join(data[kind])))
    return "\n".join(lines)


def main():
    raw_seasons = [
        ("spring", ["rose=8.5", "fern=3.2", "seedling=0.4"]),
        ("summer", ["rose=9.1", "aphid=-2.0", "basil=5.5"]),
        ("autumn", ["mildew=-1.5", "kale=4.0"]),
    ]
    seasons = [parse_period(name, raw) for name, raw in raw_seasons]
    print(format_report(summarize(greenhouse(seasons))))
    print(greenhouse([]))


if __name__ == "__main__":
    main()

