def marina(months):
    slip_rentals = {}
    departed_vessels = []
    electricity_usages = {}
    delinquent_accounts = []
    member_discounts = {}
    transient_guests = []

    for month, events in months:
        storm_damages = []
        pump_out_requests = {}
        for kind, vessel, value in events:
            if kind == "damage":
                storm_damages.append((vessel, value))
            elif kind == "pumpout":
                pump_out_requests[vessel] = value
            elif kind == "depart":
                departed_vessels.append((month, vessel))
            elif kind == "power":
                electricity_usages[vessel] = electricity_usages.get(vessel, 0) + value
            elif kind == "discount":
                member_discounts[vessel] = value
            elif kind == "transient":
                transient_guests.append((month, vessel, value))
        delinquent_accounts.append(storm_damages)
        slip_rentals.setdefault(month, {}).update(pump_out_requests)

    return (slip_rentals, departed_vessels, electricity_usages,
            delinquent_accounts, member_discounts, transient_guests)


def rental_totals(slip_rentals):
    totals = {}
    for month, requests in slip_rentals.items():
        totals[month] = sum(requests.values())
    return totals


def damage_costs(delinquent_accounts):
    costs = []
    for damages in delinquent_accounts:
        costs.append(sum(amount for _vessel, amount in damages))
    return costs


def net_power_bill(electricity_usages, member_discounts, rate):
    bills = {}
    for vessel, kilowatt_hours in electricity_usages.items():
        gross = kilowatt_hours * rate
        bills[vessel] = round(gross * (1 - member_discounts.get(vessel, 0)), 2)
    return bills


def format_report(state, rate):
    slip_rentals, departed, power, delinquent, discounts, guests = state
    lines = []
    totals = rental_totals(slip_rentals)
    for month, amount in totals.items():
        lines.append("%s: pump-out billing %.2f" % (month, amount))
    for month, cost in zip(totals, damage_costs(delinquent)):
        lines.append("%s: storm damage %.2f" % (month, cost))
    for vessel, bill in net_power_bill(power, discounts, rate).items():
        lines.append("%s: power bill %.2f" % (vessel, bill))
    for month, vessel in departed:
        lines.append("%s: departed %s" % (month, vessel))
    for month, vessel, nights in guests:
        lines.append("%s: transient %s for %d nights" % (month, vessel, nights))
    return "\n".join(lines)


def main():
    logs = [
        ("April", [("pumpout", "Halcyon", 45.0), ("damage", "Nimbus", 320.0),
                   ("power", "Halcyon", 180), ("discount", "Halcyon", 0.1)]),
        ("May", [("pumpout", "Nimbus", 60.0), ("depart", "Nimbus", None),
                 ("transient", "Sea Fox", 3), ("power", "Halcyon", 95)]),
    ]
    print(format_report(marina(logs), 0.14))


if __name__ == "__main__":
    main()

