SPECIAL_REQUESTS = {"vegan", "gluten-free", "nut-free", "halal", "kosher"}
MENU_PRICES = {"standard": 18.0, "vegan": 24.5, "gluten-free": 26.0,
               "nut-free": 22.0, "halal": 25.0, "kosher": 27.5, "child": 11.0}
BASE_PRICE = 20.0


def parse_bookings(raw_lines):
    """Turn lines like 'Gala: ann=vegan; bob=standard' into booking tuples."""
    events = []
    for line in raw_lines:
        if ":" not in line:
            continue
        name, _, body = line.partition(":")
        preferences = []
        for chunk in body.split(";"):
            chunk = chunk.strip()
            if not chunk:
                continue
            guest, _, request = chunk.partition("=")
            preferences.append((guest.strip(), request.strip().lower() or "standard"))
        events.append((name.strip(), preferences))
    return events


def caterer(events):
    dietary_restrictions = {}
    confirmed_guests = []
    vendor_deposits = {}
    missing_rentals = []
    menu_costs = {}
    leftover_donations = []

    for name, preferences in events:
        urgent_arrivals = []
        table_seatings = {}
        for guest, request in preferences:
            confirmed_guests.append((name, guest))
            if request in SPECIAL_REQUESTS:
                urgent_arrivals.append((guest, request))
            else:
                table_seatings[guest] = request
        plate_total = sum(MENU_PRICES.get(r, BASE_PRICE) for _, r in preferences)
        menu_costs[name] = round(plate_total, 2)
        vendor_deposits[name] = round(plate_total * 0.25, 2)
        missing_rentals.append((name, urgent_arrivals))
        dietary_restrictions.update(table_seatings)
        surplus = len(table_seatings) - len(urgent_arrivals)
        if surplus > 0:
            leftover_donations.append((name, surplus))

    return (dietary_restrictions, confirmed_guests, vendor_deposits,
            missing_rentals, menu_costs, leftover_donations)


def format_report(plan):
    restrictions, guests, deposits, rentals, costs, donations = plan
    headcount = {}
    for event, _guest in guests:
        headcount[event] = headcount.get(event, 0) + 1
    lines = []
    for event in sorted(costs):
        urgent = dict(rentals).get(event, [])
        lines.append("%s: %d guests, menu %.2f, deposit %.2f, %d special"
                     % (event, headcount[event], costs[event],
                        deposits[event], len(urgent)))
    lines.append("standard seatings recorded: %d" % len(restrictions))
    for event, surplus in donations:
        lines.append("donate %d surplus plates from %s" % (surplus, event))
    return "\n".join(lines)


def main():
    raw = ["Spring Gala: ann=vegan; bob=standard; cleo=gluten-free; dan=standard",
           "Board Lunch: erin=standard; finn=halal",
           "Kids Party: gus=child; hana=child; ivo=nut-free"]
    plan = caterer(parse_bookings(raw))
    print(format_report(plan))
    print("empty schedule ->", caterer([]))


if __name__ == "__main__":
    main()

