FILTER_SERVICE_HOURS = 500.0


def normalize_check(check):
    """Return a (tank, kind, value) triple from a tuple or a mapping."""
    if isinstance(check, dict):
        fields = {}
        for key, val in check.items():
            fields[key.lower()] = val
