    tank, kind, value = check
    return tank, str(kind).lower(), value


def aquarium(quarters):
    salinities = {}
    hatchlings = []
    filtration_life = {}
    sick_specimens = []
    tour_guides = {}
    exhibits = []
    for quarter, checks in quarters:
        feeding_anomalies = []
        water_clarities = {}
        for check in checks:
            tank, kind, value = normalize_check(check)
            if kind == "clarity":
                if float(value) < CLARITY_FLOOR:
                    feeding_anomalies.append((quarter, tank, float(value)))
                else:
                    water_clarities[tank] = float(value)
            elif kind == "hatch":
                hatchlings.append((quarter, tank, int(value)))
            elif kind == "filter":
                filtration_life[tank] = float(value)
            elif kind == "guide":
                tour_guides[tank] = str(value)
            elif kind == "exhibit":
                exhibits.append((quarter, str(value)))
        sick_specimens.append(feeding_anomalies)
        salinities.update(water_clarities)
    return (salinities, hatchlings, filtration_life,
            sick_specimens, tour_guides, exhibits)


def format_report(salinities, hatchlings, filtration_life,
                  sick_specimens, tour_guides, exhibits):
    lines = []
    flagged = {}
    for batch in sick_specimens:
        for quarter, tank, clarity in batch:
            flagged[quarter] = flagged.get(quarter, 0) + 1
    lines.append("tanks monitored: %d" % len(salinities))
    for tank in sorted(salinities):
        lines.append("  %s clarity %.1f, guide %s"
                     % (tank, salinities[tank], tour_guides.get(tank, "unassigned")))
