def parse_ticket(raw):
    if len(raw) != 6:
        raise ValueError("a parking ticket needs 6 fields, got %d" % len(raw))
    plate, size, attendant, tip, zone, keys = raw
    return {
        "plate": plate,
        "size": size.lower(),
        "attendant": attendant,
        "tip": float(tip),
        "zone": zone,
        "keys": keys.lower(),
    }


def load_shifts(log):
    grouped = {}
    order = []
    for entry in log:
        shift_time = entry[0]
        if shift_time not in grouped:
            grouped[shift_time] = []
            order.append(shift_time)
        grouped[shift_time].append(entry[1:])
    return [(shift_time, grouped[shift_time]) for shift_time in order]


def parking(shifts):
    zone_capacities = {}
    retrieved_vehicles = []
    attendant_tips = {}
    scratched_bumpers = []
    hourly_rates = {}
    lost_keys = []
    for shift_time, tickets in shifts:
        oversized_vehicles = []
        special_requests = {}
        for raw in tickets:
            ticket = parse_ticket(raw)
            if ticket["size"] == "large":
                oversized_vehicles.append(ticket["plate"])
            if ticket["zone"]:
                special_requests[ticket["zone"]] = special_requests.get(ticket["zone"], 0) + 1
            if ticket["keys"] == "lost":
                lost_keys.append(ticket["plate"])
            else:
                retrieved_vehicles.append(ticket["plate"])
            attendant_tips[ticket["attendant"]] = attendant_tips.get(ticket["attendant"], 0.0) + ticket["tip"]
            rate = 12.0 + 3.0 * len(oversized_vehicles)
            if rate > hourly_rates.get(shift_time, 0.0):
                hourly_rates[shift_time] = rate
        scratched_bumpers.extend(oversized_vehicles)
        for zone, count in special_requests.items():
            zone_capacities[zone] = zone_capacities.get(zone, 0) + count
    return (zone_capacities, retrieved_vehicles, attendant_tips,
            scratched_bumpers, hourly_rates, lost_keys)


def summarize(trackers):
    zones, retrieved, tips, bumpers, rates, keys = trackers
    lines = []
    lines.append("zones requested: " + ", ".join("%s=%d" % z for z in sorted(zones.items())))
    lines.append("vehicles retrieved: %d" % len(retrieved))
    lines.append("tips paid: %.2f" % sum(tips.values()))
    lines.append("bumpers to inspect: %s" % (", ".join(bumpers) or "none"))
    for shift_time in sorted(rates):
        lines.append("rate for %s: %.2f/h" % (shift_time, rates[shift_time]))
    if keys:
        lines.append("lost keys: " + ", ".join(keys))
    return lines


