    log = [
        ("morning", "AB-123", "large", "Rita", 5, "valet-north", "returned"),
        ("morning", "CD-456", "compact", "Rita", 2, "", "returned"),
        ("morning", "EF-789", "compact", "Omar", 3, "ev-charger", "lost"),
        ("evening", "GH-012", "large", "Omar", 8, "valet-north", "returned"),
        ("evening", "IJ-345", "large", "Rita", 4, "", "returned"),
    ]
    trackers = parking(load_shifts(log))
    for line in summarize(trackers):
        print(line)


if __name__ == "__main__":
