CRITICAL_WORDS = ("accident", "collision", "fire", "injury")
MODERATE_WORDS = ("blocked", "flooding", "stalled", "debris")
UNIT_POOL = {"critical": ["AMB-1", "AMB-2"], "moderate": ["PAT-1", "PAT-2"], "minor": ["MNT-1"]}


def parse_incidents(incidents):
    records = []
    malformed = []
    for raw in incidents:
        text = (raw or "").strip().lower()
        if not text:
            malformed.append(raw)
            continue
        if " at " in text:
            kind, location = text.split(" at ", 1)
        else:
            kind, location = text, "unknown location"
        kind = kind.strip()
        location = location.strip()
        if not kind or not location:
            malformed.append(raw)
        else:
            records.append({"report": text, "kind": kind, "location": location})
    return records, malformed


def rank_severity(records):
    priorities = {}
    critical = []
    moderate = []
    minor = []
    for record in records:
        report = record["report"]
        if any(word in report for word in CRITICAL_WORDS):
            level = "critical"
            critical.append(report)
        elif any(word in report for word in MODERATE_WORDS):
            level = "moderate"
            moderate.append(report)
        else:
            level = "minor"
            minor.append(report)
        priorities[report] = level
    ordered = critical + moderate + minor
    return priorities, ordered


def assign_units(priorities, ordered):
    assignments = {}
    unassigned = []
    available = {level: list(units) for level, units in UNIT_POOL.items()}
    for report in ordered:
        level = priorities[report]
        pool = available[level]
        if pool:
            assignments[report] = pool.pop(0)
        else:
            unassigned.append(report)
    return assignments, unassigned


def manage(incidents):
    records, malformed = parse_incidents(incidents)
    priorities, ordered = rank_severity(records)
    assignments, unassigned = assign_units(priorities, ordered)
    unassigned.extend("malformed: %r" % item for item in malformed)
    return assignments, unassigned


def main():
    reports = [
        "accident at main street",
        "broken light",
        "collision at bridge road",
        "flooding at river lane",
        "debris at hill top",
        "stalled truck at tunnel",
        "",
        "graffiti at park gate",
    ]
    assignments, unassigned = manage(reports)
    for report in sorted(assignments):
        print("%-30s -> %s" % (report, assignments[report]))
    for item in unassigned:
        print("UNASSIGNED: %s" % item)


if __name__ == "__main__":
    main()

