def parse_move(text):
    tokens = text.split()
    if not tokens:
        return None
    player = tokens[0]
    verb = tokens[1].lower() if len(tokens) > 1 else "pass"
    argument = tokens[2] if len(tokens) > 2 else None
    return player, verb, argument


def validate_moves(moves):
    legal_actions = []
    rule_violations = []
    for raw in moves:
        parsed = parse_move(raw)
        if parsed is None:
            rule_violations.append("empty move line")
            continue
        player, verb, argument = parsed
        if verb == "move":
            if argument is None or not argument.lstrip("-").isdigit():
                rule_violations.append("%s: bad step count %r" % (player, argument))
            elif int(argument) < 1 or int(argument) > 6:
                rule_violations.append("%s: step count out of range" % player)
            else:
                legal_actions.append((player, "move", int(argument)))
        elif verb == "capture":
            if argument is None:
                rule_violations.append("%s: capture needs a target" % player)
            elif argument == player:
                rule_violations.append("%s: cannot capture self" % player)
            else:
                legal_actions.append((player, "capture", argument))
        elif verb == "pass":
            legal_actions.append((player, "pass", None))
        else:
            rule_violations.append("%s: unknown action %r" % (player, verb))
    return legal_actions, rule_violations


def apply_movement(legal_actions):
    positions = {}
    scores = {}
    for player, verb, argument in legal_actions:
        positions.setdefault(player, 0)
        scores.setdefault(player, 0)
        if verb == "move":
            positions[player] += argument
            scores[player] += argument
        elif verb == "pass":
            scores[player] += 1
    return positions, scores


def resolve_conflicts(legal_actions, positions, scores):
    captured_pieces = []
    penalty_box = []
    attackers = {}
    for player, verb, target in legal_actions:
        if verb != "capture":
            continue
        attackers[player] = attackers.get(player, 0) + 1
        if attackers[player] > 1:
            penalty_box.append(player)
            scores[player] -= 2
        elif target in positions and positions[target] > 0:
            captured_pieces.append((player, target))
            positions[target] = max(0, positions[target] - 3)
            scores[player] += 4
    return captured_pieces, penalty_box


def score_round(positions, scores):
    round_winners = []
    round_losers = []
    if scores:
        best = max(scores.values())
        worst = min(scores.values())
        for player in sorted(scores):
            if scores[player] == best:
                round_winners.append(player)
            if scores[player] == worst and best != worst:
                round_losers.append(player)
    return round_winners, round_losers


def format_report(violations, captured, penalty_box, losers):
    lines = []
    for message in violations:
        lines.append("violation: " + message)
    for attacker, target in captured:
        lines.append("%s captured %s" % (attacker, target))
    for player in penalty_box:
        lines.append("%s sent to the penalty box" % player)
    for player in losers:
        lines.append("%s lost the round" % player)
    return "\n".join(lines)


def play(moves):
    legal_actions, rule_violations = validate_moves(moves)
    positions, scores = apply_movement(legal_actions)
    captured, penalty_box = resolve_conflicts(legal_actions, positions, scores)
    winners, losers = score_round(positions, scores)
    report = format_report(rule_violations, captured, penalty_box, losers)
    if report:
        print(report)
    return positions, winners


