ALLOWED_SPECIES = {"dog": "dogs", "cat": "cats", "bird": "birds"}


def parse_profile(text):
    """Turn a text profile 'name | species | owner | notes' into a dict."""
    fields = [part.strip() for part in text.split("|")]
    if len(fields) < 3:
        raise ValueError("profile needs name, species and owner: %r" % text)
    profile = {}
    profile["name"] = fields[0]
    profile["species"] = fields[1].lower()
    profile["owner"] = fields[2]
    if profile["species"] not in ALLOWED_SPECIES:
        raise ValueError("unsupported species: %r" % fields[1])
    notes = []
    if len(fields) > 3 and fields[3]:
        for tag in fields[3].split(","):
            notes.append(tag.strip().lower())
    profile["notes"] = notes
    return profile


def sort_by_species(profiles):
    """Split the guests into one list per species."""
    dogs = []
    cats = []
    birds = []
    kennels = {"dogs": dogs, "cats": cats, "birds": birds}
    for profile in profiles:
        kennels[ALLOWED_SPECIES[profile["species"]]].append(profile["name"])
    return kennels


def medical_review(profiles):
    """Collect kitchen and nurse duties from the profile notes."""
    special_diets = []
    medication_alerts = []
    for profile in profiles:
        for note in profile["notes"]:
            if note.startswith("diet:"):
                special_diets.append((profile["name"], note[5:].strip()))
            elif note.startswith("med:"):
                medication_alerts.append((profile["name"], note[4:].strip()))
    return special_diets, medication_alerts


def assign_rooms(profiles, first_room=101):
    """Group pets per owner, then give neighbouring rooms to each household."""
    owner_pets = {}
    room_numbers = {}
    for profile in profiles:
        owner_pets.setdefault(profile["owner"], []).append(profile["name"])
    room = first_room
    for owner in sorted(owner_pets):
        for name in owner_pets[owner]:
            room_numbers[name] = room
            room += 1
    return owner_pets, room_numbers


def format_roster(profiles, room_numbers):
    """Human readable check-in list, one line per guest."""
    lines = []
    for profile in sorted(profiles, key=lambda p: room_numbers[p["name"]]):
        lines.append("%d: %s (%s) - owner %s" % (room_numbers[profile["name"]],
                                                 profile["name"],
                                                 profile["species"],
                                                 profile["owner"]))
    return lines


def schedule(pets):
    """Build the daily report for every text profile in 'pets'."""
    report = {}
    profiles = [parse_profile(text) for text in pets]
    owner_pets, room_numbers = assign_rooms(profiles)
    special_diets, medication_alerts = medical_review(profiles)
    report["guests"] = len(profiles)
    report["by_species"] = sort_by_species(profiles)
    report["households"] = owner_pets
    report["rooms"] = room_numbers
    report["special_diets"] = special_diets
    report["medication_alerts"] = medication_alerts
    report["roster"] = format_roster(profiles, room_numbers)
    return report


def main():
    guests = [
        "Rex | dog | Alice | diet:grain-free, med:antibiotic",
        "Mimi | cat | Bob |",
        "Kiwi | bird | Alice | diet:seed mix",
        "Bruno | dog | Carol | med:insulin",
    ]
    daily = schedule(guests)
    for line in daily["roster"]:
        print(line)
    print("meds due:", len(daily["medication_alerts"]))


if __name__ == "__main__":
    main()

MIN_UNACCOMPANIED_AGE = 12
VALID_TICKETS = ("standard", "express", "vip")
ZONE_CAPACITY = {"gardens": 40, "coaster": 24, "aquarium": 60}
SERVICE_WEIGHT = {"vip": 0, "express": 1, "standard": 3}


def classify_guests(guests):
    express_passes = []
    standard_entries = []
    vip_tours = []
    for guest in guests:
        ticket = guest.get("ticket", "standard")
        if ticket == "vip":
            vip_tours.append(guest)
        elif ticket == "express":
            express_passes.append(guest)
        else:
            standard_entries.append(guest)
    return express_passes, standard_entries, vip_tours


def screen_safety(guests):
    denied_entries = []
    lost_children = []
    for guest in guests:
        if guest.get("ticket", "standard") not in VALID_TICKETS:
            denied_entries.append(guest)
            continue
        if guest.get("zone") not in ZONE_CAPACITY:
            denied_entries.append(guest)
            continue
        if guest.get("age", 99) < MIN_UNACCOMPANIED_AGE and not guest.get("accompanied"):
            lost_children.append(guest)
    return denied_entries, lost_children


def plan_logistics(admitted):
    wait_times = {}
    max_capacities = {}
    maintenance_alerts = []
    zone_load = {}
    for guest in admitted:
        zone = guest["zone"]
        weight = SERVICE_WEIGHT[guest.get("ticket", "standard")]
        zone_load[zone] = zone_load.get(zone, 0) + weight
    for zone, capacity in ZONE_CAPACITY.items():
        load = zone_load.get(zone, 0)
        max_capacities[zone] = capacity
        wait_times[zone] = round(load * 60 / capacity)
        if load > capacity:
            maintenance_alerts.append("%s over capacity: %d/%d" % (zone, load, capacity))
        elif wait_times[zone] >= 45:
            maintenance_alerts.append("%s queue exceeds 45 min" % zone)
    return wait_times, max_capacities, maintenance_alerts


def route(guests):
    denied_entries, lost_children = screen_safety(guests)
    admitted = [g for g in guests if g not in denied_entries]
    express_passes, standard_entries, vip_tours = classify_guests(admitted)
    wait_times, max_capacities, maintenance_alerts = plan_logistics(admitted)
    for child in lost_children:
        maintenance_alerts.append("escort needed for %s" % child.get("name", "unknown"))
    for guest in denied_entries:
        maintenance_alerts.append("entry denied for %s" % guest.get("name", "unknown"))
    if len(vip_tours) > max_capacities["gardens"] // 4:
        maintenance_alerts.append("extra vip guides required")
    if len(express_passes) > len(standard_entries):
        maintenance_alerts.append("open second express lane")
    return wait_times, maintenance_alerts


def format_report(wait_times, maintenance_alerts):
    lines = []
    for zone in sorted(wait_times):
        lines.append("%-10s %3d min" % (zone, wait_times[zone]))
    for alert in maintenance_alerts:
        lines.append("ALERT: %s" % alert)
    return lines


def main():
    visitors = [
        {"name": "Ana", "ticket": "vip", "age": 34, "zone": "gardens"},
        {"name": "Bo", "ticket": "express", "age": 9, "zone": "coaster", "accompanied": True},
        {"name": "Cy", "ticket": "standard", "age": 8, "zone": "aquarium"},
        {"name": "Dee", "ticket": "season", "age": 41, "zone": "coaster"},
        {"name": "Eli", "ticket": "standard", "age": 27, "zone": "coaster"},
        {"name": "Fay", "ticket": "express", "age": 52, "zone": "gardens"},
    ]
