def screen_security(passengers):
    missing_passports = []
    contraband = []
    for person in passengers:
        if not person.get("passport"):
            missing_passports.append(person["name"])
        for item in person.get("items", ()):
            if item in ("knife", "fireworks", "fuel"):
                contraband.append((person["name"], item))
    return missing_passports, contraband


def handle_luggage(passengers, cleared_names):
    bag_counts = {}
    upgrades = {}
    late_arrivals = []
    for person in passengers:
        name = person["name"]
        if name not in cleared_names:
