        bags = int(person.get("bags", 0))
        bag_counts[cabin] = bag_counts.get(cabin, 0) + bags
        if cabin == "economy" and bags == 0 and person.get("frequent_flyer"):
            upgrades[name] = "business"
    return bag_counts, upgrades, late_arrivals


