text_nat:
PASS_MARK = 40
INTERMEDIATE_MARK = 60
ADVANCED_MARK = 80

TEACHERS = {
    "beginner": ["Ms. Ada", "Mr. Bo"],
    "intermediate": ["Mrs. Cruz"],
    "advanced": ["Dr. Deng", "Mr. Elias"],
}
ROOMS = {"beginner": "R101", "intermediate": "R204", "advanced": "R310"}
TEXTBOOKS = {
    "beginner": ("First Words", 24.0),
    "intermediate": ("Bridging Grammar", 31.5),
    "advanced": ("Rhetoric and Style", 42.0),
}


def assess_proficiency(students):
    beginners = []
    intermediates = []
    advanced = []
    for student in students:
        score = student["score"]
        if score < PASS_MARK:
            continue
        if score >= ADVANCED_MARK:
            advanced.append(student["name"])
        elif score >= INTERMEDIATE_MARK:
            intermediates.append(student["name"])
        else:
            beginners.append(student["name"])
    return beginners, intermediates, advanced


def review_records(students):
    failed_exams = []
    scholarships = []
    for student in students:
        if student["score"] < PASS_MARK:
            failed_exams.append(student["name"])
        elif student["score"] >= 85 and student.get("needs_aid"):
            scholarships.append(student["name"])
    return failed_exams, scholarships


def build_schedule(groups, scholarships):
    student_teacher = {}
    room_timetable = {}
    textbooks = []
    for level, names in groups.items():
        staff = TEACHERS[level]
        title, price = TEXTBOOKS[level]
        for index, name in enumerate(names):
            teacher = staff[index % len(staff)]
            student_teacher[name] = teacher
            room_timetable.setdefault(ROOMS[level], []).append(name)
            textbooks.append((name, title, 0.0 if name in scholarships else price))
    return student_teacher, room_timetable, textbooks


def validate_roster(students):
    valid = []
    rejected = []
    for record in students:
        name = record.get("name")
        score = record.get("score")
        if not name or not isinstance(score, (int, float)):
            rejected.append(repr(record))
        else:
            valid.append(record)
    return valid, rejected


def place(students):
    roster, rejected = validate_roster(students)
    for entry in rejected:
        print("skipping incomplete record:", entry)
    beginners, intermediates, advanced = assess_proficiency(roster)
    failed_exams, scholarships = review_records(roster)
    groups = {
        "beginner": beginners,
        "intermediate": intermediates,
        "advanced": advanced,
    }
    student_teacher, room_timetable, textbooks = build_schedule(groups, scholarships)
    for name in failed_exams:
        print("retake required:", name)
    for room, occupants in sorted(room_timetable.items()):
        print("%s hosts %d student(s)" % (room, len(occupants)))
    print("textbook orders:", len(textbooks))
    return student_teacher, beginners


def format_report(student_teacher, beginners):
    lines = []
    for name in sorted(student_teacher):
        marker = " (beginner)" if name in beginners else ""
        lines.append("%s -> %s%s" % (name, student_teacher[name], marker))
    return lines


def main():
    exam_results = [
        {"name": "Iris", "score": 92, "needs_aid": True},
        {"name": "Jonas", "score": 71},
        {"name": "Kira", "score": 48},
        {"name": "Liam", "score": 33},
        {"name": "Mei", "score": 88, "needs_aid": False},
        {"name": "Nils", "score": 55},
        {"score": 60},
    ]
    teachers, beginners = place(exam_results)
    print("\n".join(format_report(teachers, beginners)))


if __name__ == "__main__":
    main()

