CATEGORY_KEYS = ("food", "oxygen", "fuel", "medical")

STORAGE_BAYS = {
    "food": "BAY-A1",
    "oxygen": "BAY-B2",
    "fuel": "BAY-C3",
    "medical": "BAY-D4",
}

DEPARTMENTS = {
    "food": "galley",
    "oxygen": "life-support",
    "fuel": "engineering",
    "medical": "infirmary",
}


def parse_manifest(manifest):
    entries = []
    for raw in manifest:
        fields = [field.strip() for field in raw.split(":")]
        if len(fields) < 3:
            raise ValueError("malformed manifest line: %r" % raw)
        category, name, quantity = fields[0].lower(), fields[1], fields[2]
        status = fields[3].lower() if len(fields) > 3 else "intact"
        entries.append({"category": category, "name": name,
                        "quantity": int(quantity), "status": status})
    return entries


def collect_requests(entries):
    requests = {}
    for entry in entries:
        if entry["category"] == "request":
            requests[entry["name"]] = requests.get(entry["name"], 0) + entry["quantity"]
    return requests


def categorize(entries):
    food_crates = []
    oxygen_tanks = []
    fuel_cells = []
    medical_kits = []
    buckets = {"food": food_crates, "oxygen": oxygen_tanks,
               "fuel": fuel_cells, "medical": medical_kits}
    for entry in entries:
        if entry["category"] not in buckets:
            raise ValueError("unknown cargo category: %s" % entry["category"])
        buckets[entry["category"]].append(entry)
    return buckets


def inspect_cargo(buckets, requests):
    damaged_goods = []
    unfulfilled_requests = []
    available = {}
    for category in CATEGORY_KEYS:
        for item in buckets[category]:
            if item["status"] == "damaged":
                damaged_goods.append(item["name"])
            else:
                available[item["name"]] = available.get(item["name"], 0) + item["quantity"]
    for name, wanted in requests.items():
        shortfall = wanted - available.get(name, 0)
        if shortfall > 0:
            unfulfilled_requests.append((name, shortfall))
    return damaged_goods, unfulfilled_requests


def assign_storage(buckets):
    storage = {}
    departments = {}
    for category in CATEGORY_KEYS:
        bay = STORAGE_BAYS[category]
        owner = DEPARTMENTS[category]
        if owner not in departments:
            departments[owner] = []
        for item in buckets[category]:
            if item["status"] == "damaged":
                continue
            storage[item["name"]] = bay
            departments[owner].append(item["name"])
    return storage, departments


def format_report(departments, unfulfilled_requests):
    lines = []
    for owner in sorted(departments):
        lines.append("%s: %s" % (owner, ", ".join(departments[owner]) or "nothing"))
    for name, shortfall in unfulfilled_requests:
        lines.append("shortfall of %d %s for civilian request" % (shortfall, name))
    return lines


def allocate(manifest):
    entries = parse_manifest(manifest)
    cargo = [entry for entry in entries if entry["category"] != "request"]
    requests = collect_requests(entries)
    buckets = categorize(cargo)
    damaged_goods, unfulfilled_requests = inspect_cargo(buckets, requests)
    storage, departments = assign_storage(buckets)
    for line in format_report(departments, unfulfilled_requests):
        print(line)
    return storage, damaged_goods


def main():
    manifest = [
        "food:rations:120",
        "oxygen:o2-tank:8",
        "fuel:cell-mk2:4:damaged",
        "medical:trauma-kit:6",
        "food:protein-paste:30:damaged",
        "request:rations:200",
        "request:trauma-kit:2",
    ]
    storage, damaged = allocate(manifest)
    print("stored:", storage)
    print("damaged:", damaged)


if __name__ == "__main__":
    main()

