MULTIPLIERS = {"pristine": 1.0, "worn": 0.6, "heavily_read": 0.3, "damaged": 0.1}


def parse_descriptions(descriptions):
    """Turn 'Title|issue|grade|missing_pages|signed|base_value' strings into records."""
    records = []
    for line in descriptions:
        fields = [part.strip() for part in line.split("|")]
        if len(fields) != 6:
            raise ValueError("malformed comic description: %r" % line)
        title, issue, grade, missing, signed, base = fields
        records.append({
            "title": title,
            "issue": issue,
            "grade": float(grade),
            "missing_pages": int(missing),
            "signed": signed.lower() in ("yes", "true", "1"),
            "base_value": float(base),
        })
    return records


def grade_conditions(records):
    """Split records into condition buckets by their numeric grade (0.0 - 10.0)."""
    pristine = []
    worn = []
    heavily_read = []
    damaged = []
    for record in records:
        grade = record["grade"]
        if grade >= 9.0:
            pristine.append(record)
        elif grade >= 6.0:
            worn.append(record)
        elif grade >= 3.0:
            heavily_read.append(record)
        else:
            damaged.append(record)
    return {"pristine": pristine, "worn": worn,
            "heavily_read": heavily_read, "damaged": damaged}


def authenticate(records):
    """Flag incomplete books and signed editions."""
    missing_pages = []
    autographed = []
    for record in records:
        if record["missing_pages"] > 0:
            missing_pages.append(record)
        if record["signed"]:
            autographed.append(record)
    return missing_pages, autographed


def valuate(buckets, missing_pages, autographed):
    """Estimate a price per book and route repair candidates to restoration experts."""
    prices = {}
    restorers = {}
    incomplete = [id(record) for record in missing_pages]
    signed = [id(record) for record in autographed]
    needs_work = 0
    for condition, books in buckets.items():
        for record in books:
            key = "%s #%s" % (record["title"], record["issue"])
            value = record["base_value"] * MULTIPLIERS[condition]
            if id(record) in signed:
                value *= 1.5
            if id(record) in incomplete:
                value *= 0.6
            prices[key] = round(value, 2)
            if condition == "damaged" or id(record) in incomplete:
                restorers[key] = EXPERTS[needs_work % len(EXPERTS)]
                needs_work += 1
    return prices, restorers


def format_report(prices, restorers):
    lines = []
    for key in sorted(prices):
        expert = restorers.get(key)
        suffix = " -> restoration by %s" % expert if expert else ""
        lines.append("%-24s $%8.2f%s" % (key, prices[key], suffix))
    return "\n".join(lines)


def appraise(comics):
    records = parse_descriptions(comics)
    buckets = grade_conditions(records)
    missing_pages, autographed = authenticate(records)
    prices, restorers = valuate(buckets, missing_pages, autographed)
    print(format_report(prices, restorers))
    return prices, buckets["pristine"]


