def register(signups):
    """Split raw signups into solo players, duo teams and full squads."""
    solo_players = []
    duo_teams = []
    full_squads = []
    for entry in signups:
        name = entry.get("name", "").strip()
        roster = [p.strip() for p in entry.get("players", []) if p.strip()]
        team = {"name": name, "players": roster}
        if len(roster) == 1:
            solo_players.append(team)
        elif len(roster) == 2:
            duo_teams.append(team)
        else:
            full_squads.append(team)
    return solo_players, duo_teams, full_squads


def vet(solo_players, duo_teams, full_squads):
    """Remove invalid squads and park incomplete rosters in the standby queue."""
    disqualified = []
    standby = []
    seen = {}
    accepted = []
    for team in full_squads:
        key = team["name"].lower()
        if not team["name"] or len(team["players"]) > 4:
            disqualified.append(team)
        elif key in seen:
            disqualified.append(team)
        else:
            seen[key] = team
            accepted.append(team)
    for team in solo_players + duo_teams:
        standby.append(team)
    return accepted, disqualified, standby


def build_bracket(squads, start_hour=18, prize_fund=1000):
    """Seed the accepted squads, schedule matches and split the prize fund."""
    seeds = {}
    match_times = {}
    prize_pool = {}
    ordered = sorted(squads, key=lambda t: (-len(t["players"]), t["name"].lower()))
    for index, team in enumerate(ordered, start=1):
        seeds[team["name"]] = index
    for pair_index in range(0, len(ordered), 2):
        home = ordered[pair_index]["name"]
        hour = start_hour + pair_index // 2
        if pair_index + 1 < len(ordered):
            away = ordered[pair_index + 1]["name"]
            label = "{} vs {}".format(home, away)
        else:
            label = "{} (bye)".format(home)
        match_times[label] = "{:02d}:00".format(hour)
    shares = [0.5, 0.3, 0.2]
    for team, share in zip(ordered, shares):
        prize_pool[team["name"]] = round(prize_fund * share, 2)
    return seeds, match_times, prize_pool


def report(seeds, prize_pool, disqualified, standby):
    """Build human readable lines describing the competition setup."""
    lines = []
    for name, seed in sorted(seeds.items(), key=lambda item: item[1]):
        money = prize_pool.get(name, 0)
        lines.append("#{} {} - prize {:.2f}".format(seed, name, money))
    for team in disqualified:
        lines.append("disqualified: {}".format(team["name"] or "<unnamed>"))
    for team in standby:
        lines.append("standby: {} ({} players)".format(team["name"], len(team["players"])))
    return lines


def bracket(teams):
    solo_players, duo_teams, full_squads = register(teams)
    accepted, disqualified, standby = vet(solo_players, duo_teams, full_squads)
    seeds, match_times, prize_pool = build_bracket(accepted)
    for line in report(seeds, prize_pool, disqualified, standby):
        print(line)
    return match_times, accepted


