CLIMBERS = ("Ana", "Boris", "Chen")

HARDWARE = ("hardware", "climbing")
THERMAL = ("thermal", "clothing")
COOKING = ("cooking", "food")
MEDICAL = ("first_aid", "medical")


def normalize(equipment):
    items = []
    for entry in equipment:
        name = str(entry.get("name", "")).strip()
        try:
            weight = float(entry.get("weight", 0))
        except (TypeError, ValueError):
            continue
        if not name or weight <= 0:
            continue
        items.append({
            "name": name,
            "category": str(entry.get("category", "")).lower(),
            "weight": weight,
            "condition": str(entry.get("condition", "good")).lower(),
        })
    return items


def sort_gear(items):
    climbing_hardware = []
    thermal_clothing = []
    cooking_supplies = []
    first_aid = []
    for item in items:
        category = item["category"]
        if category in HARDWARE:
            climbing_hardware.append(item)
        elif category in THERMAL:
            thermal_clothing.append(item)
        elif category in COOKING:
            cooking_supplies.append(item)
        elif category in MEDICAL:
            first_aid.append(item)
    return climbing_hardware, thermal_clothing, cooking_supplies, first_aid


def check_quality(groups):
    frayed_ropes = []
    left_at_base = []
    for group in groups:
        approved = []
        for item in group:
            if "rope" in item["name"].lower() and item["condition"] == "frayed":
                frayed_ropes.append(item["name"])
            elif item["condition"] in ("worn", "expired"):
                left_at_base.append(item["name"])
            else:
                approved.append(item)
        group[:] = approved
    return frayed_ropes, left_at_base


def distribute(groups, climbers):
    weights = {}
    shared_loads = {}
    for climber in climbers:
        weights[climber] = 0.0
    turn = 0
    for group in groups:
        for item in group:
            carrier = climbers[turn % len(climbers)]
            if item["weight"] >= 4.0:
                helper = climbers[(turn + 1) % len(climbers)]
                share = item["weight"] / 2.0
                weights[carrier] = round(weights[carrier] + share, 2)
                weights[helper] = round(weights[helper] + share, 2)
                shared_loads[item["name"]] = [carrier, helper]
            else:
                weights[carrier] = round(weights[carrier] + item["weight"], 2)
            turn += 1
    return weights, shared_loads


def summarize(frayed_ropes, left_at_base, shared_loads):
    lines = []
    for rope in frayed_ropes:
        lines.append("retired frayed rope: " + rope)
    for name in left_at_base:
        lines.append("left at base camp: " + name)
    for name, team in sorted(shared_loads.items()):
        lines.append("shared load %s: %s" % (name, " + ".join(team)))
    return lines


def pack(equipment):
    groups = sort_gear(normalize(equipment))
    frayed_ropes, left_at_base = check_quality(list(groups))
    weights, shared_loads = distribute(groups, CLIMBERS)
    for line in summarize(frayed_ropes, left_at_base, shared_loads):
        print(line)
    return weights, groups[0]


def main():
    equipment = [
        {"name": "Ice Screws", "category": "hardware", "weight": 2.5},
        {"name": "Dynamic Rope", "category": "climbing", "weight": 6.0},
        {"name": "Backup Rope", "category": "climbing", "weight": 5.5, "condition": "frayed"},
        {"name": "Down Jacket", "category": "thermal", "weight": 1.2},
        {"name": "Old Mittens", "category": "clothing", "weight": 0.4, "condition": "worn"},
