        {"name": "Bandages", "category": "first_aid", "weight": 0.6},
        {"name": "Serum", "category": "medical", "weight": 0.3, "condition": "expired"},
    ]
    weights, hardware = pack(equipment)
    for climber in CLIMBERS:
        print("%s carries %.2f kg" % (climber, weights[climber]))
    print("hardware packed: " + ", ".join(item["name"] for item in hardware))


if __name__ == "__main__":
