def sort_materials(toys):
    wooden_blocks = []
    plastic_figures = []
    plush_animals = []
    electronic_gadgets = []
    for toy in toys:
        material = toy.get("material", "").lower()
        if material == "wood":
            wooden_blocks.append(toy)
        elif material == "plastic":
            plastic_figures.append(toy)
        elif material == "plush":
            plush_animals.append(toy)
        elif material == "electronic":
            electronic_gadgets.append(toy)
    return {
        "wood": wooden_blocks,
        "plastic": plastic_figures,
        "plush": plush_animals,
        "electronic": electronic_gadgets,
    }


def quality_control(toys):
    missing_batteries = []
    safety_failures = []
    for toy in toys:
        if toy.get("needs_batteries") and not toy.get("batteries_included"):
            missing_batteries.append(toy["name"])
        if not toy.get("safety_passed", False):
            safety_failures.append(toy["name"])
    return missing_batteries, safety_failures


def plan_logistics(groups, missing_batteries, safety_failures):
    box_sizes = {}
    destinations = {}
    for category, items in groups.items():
        for toy in items:
            name = toy["name"]
            if name in safety_failures:
                continue
            box_sizes[name] = CATEGORY_BOXES[category]
            if name in missing_batteries:
                destinations[toy["batch"]] = "Battery Depot"
            else:
                destinations.setdefault(toy["batch"], CATEGORY_DESTINATIONS[category])
    return box_sizes, destinations


def assemble(toys):
    groups = sort_materials(toys)
    missing_batteries, safety_failures = quality_control(toys)
    _boxes, destinations = plan_logistics(groups, missing_batteries, safety_failures)
    return destinations, safety_failures


def summarize(groups):
    counts = {}
    for category, items in groups.items():
        counts[category] = len(items)
    return counts


def main():
    daily_output = [
        {"name": "block set", "material": "wood", "batch": "B1", "safety_passed": True},
        {"name": "robot", "material": "electronic", "batch": "B2",
         "needs_batteries": True, "batteries_included": False, "safety_passed": True},
        {"name": "teddy", "material": "plush", "batch": "B3", "safety_passed": False},
        {"name": "dino", "material": "plastic", "batch": "B4", "safety_passed": True},
