    destinations, failures = assemble(daily_output)
    for batch in sorted(destinations):
        print("{} -> {}".format(batch, destinations[batch]))
    print("Safety failures:", ", ".join(failures) or "none")
    for category, total in summarize(sort_materials(daily_output)).items():
        print("{}: {} item(s)".format(category, total))


