def process_actions(events):
    """Collect the puzzle actions performed by each team."""
    unlocked_doors = []
    solved_ciphers = []
    requested_clues = []
    time_penalties = []
    for event in events:
        team = event.get("team", "unknown")
        kind = event.get("type")
        if kind == "door_unlocked":
            unlocked_doors.append((team, event["door"]))
        elif kind == "cipher_solved":
            solved_ciphers.append((team, event["cipher"]))
        elif kind == "clue_requested":
            requested_clues.append((team, event.get("room", "lobby")))
        elif kind == "time_penalty":
            time_penalties.append((team, event.get("seconds", 30)))
    return unlocked_doors, solved_ciphers, requested_clues, time_penalties


def process_hardware(events):
    """Collect facility hardware incidents."""
    broken_props = []
    triggered_alarms = []
    for event in events:
        team = event.get("team", "unknown")
        kind = event.get("type")
        if kind == "prop_broken":
            broken_props.append((team, event["prop"]))
        elif kind == "alarm_triggered":
            triggered_alarms.append((team, event.get("zone", "corridor")))
    return broken_props, triggered_alarms


def add_points(totals, team, amount):
    totals[team] = totals.get(team, 0) + amount


def score_teams(events, actions, hardware):
    """Turn actions and incidents into point totals and escape times."""
    unlocked_doors, solved_ciphers, requested_clues, time_penalties = actions
    broken_props, triggered_alarms = hardware
    team_points = {}
    escape_times = {}
    for team, _door in unlocked_doors:
