VALID_FORMATS = ("dcp", "mp4", "mov")
SHORT_LIMIT = 40
FIRST_SLOT = 18 * 60
SLOT_GAP = 15


def _clock(total_minutes):
    hours, minutes = divmod(total_minutes % (24 * 60), 60)
    return "{:02d}:{:02d}".format(hours, minutes)


def find_rejections(films):
    format_errors = []
    late_submissions = []
    for film in films:
        if film.get("file_format", "").lower() not in VALID_FORMATS:
            format_errors.append(film["title"])
        elif film.get("days_late", 0) > 0:
            late_submissions.append(film["title"])
    return format_errors, late_submissions


def categorize(films):
    short_narratives = []
    feature_lengths = []
    nature_documentaries = []
    student_animations = []
    for film in films:
        genre = film.get("genre", "").lower()
        if genre == "documentary" and film.get("subject") == "nature":
            nature_documentaries.append(film["title"])
        elif genre == "animation" and film.get("student"):
            student_animations.append(film["title"])
        elif film["minutes"] < SHORT_LIMIT:
            short_narratives.append(film["title"])
        else:
            feature_lengths.append(film["title"])
    return short_narratives, feature_lengths, nature_documentaries, student_animations


def build_schedule(films, ordering):
    director_contacts = {}
    theater_showtimes = {}
    by_title = {}
    for film in films:
        by_title[film["title"]] = film
    clock = FIRST_SLOT
    for title in ordering:
        film = by_title[title]
        director_contacts[film["director"]] = film.get("email", "unknown")
        theater_showtimes[title] = _clock(clock)
        clock += film["minutes"] + SLOT_GAP
    return director_contacts, theater_showtimes


def curate(films):
    format_errors, late_submissions = find_rejections(films)
    blocked = set(format_errors) | set(late_submissions)
    accepted = []
    for film in films:
        if film["title"] not in blocked:
            accepted.append(film)
    shorts, features, docs, animations = categorize(accepted)
    ordering = features + docs + animations + shorts
    contacts, showtimes = build_schedule(accepted, ordering)
    for director in sorted(contacts):
        print("contact:", director, "->", contacts[director])
    for title in format_errors:
        print("rejected (format):", title)
    for title in late_submissions:
        print("rejected (late):", title)
    return showtimes, features


def main():
    pitches = [
        {"title": "Dust Roads", "director": "Ana Vela", "email": "ana@vela.tv",
         "minutes": 96, "genre": "drama", "file_format": "DCP"},
        {"title": "Tidepool", "director": "Ben Okoro", "email": "ben@okoro.net",
         "minutes": 62, "genre": "documentary", "subject": "nature", "file_format": "mp4"},
        {"title": "Paper Moth", "director": "Cai Lin", "email": "cai@school.edu",
         "minutes": 11, "genre": "animation", "student": True, "file_format": "mov"},
        {"title": "Last Bus", "director": "Dara Iqbal", "email": "dara@bus.co",
         "minutes": 22, "genre": "comedy", "file_format": "avi"},
        {"title": "Nightshift", "director": "Eve Marsh", "email": "eve@marsh.io",
         "minutes": 34, "genre": "thriller", "file_format": "dcp", "days_late": 3},
    ]
    showtimes, features = curate(pitches)
    for title in sorted(showtimes):
        print(showtimes[title], title)
    print("feature lengths:", ", ".join(features))


if __name__ == "__main__":
    main()

