def sort_styles(batches):
    """Split batch reports into the four cellar style shelves."""
    hoppy_ales = []
    crisp_lagers = []
    dark_stouts = []
    tart_sours = []
    for batch in batches:
        style = batch.get("style", "").lower()
        if "sour" in style or "gose" in style or "lambic" in style:
            tart_sours.append(batch)
        elif "stout" in style or "porter" in style:
            dark_stouts.append(batch)
        elif "lager" in style or "pilsner" in style:
            crisp_lagers.append(batch)
        else:
            hoppy_ales.append(batch)
    return hoppy_ales, crisp_lagers, dark_stouts, tart_sours


def check_sanitation(batches):
    """Flag barrels that went bad and fermentations that drifted."""
    contaminated_barrels = []
    yeast_mutations = []
    for batch in batches:
        style = batch.get("style", "").lower()
        ph = batch.get("ph", 4.4)
        if "sour" not in style and ph > 4.6:
            contaminated_barrels.append(batch["id"])
        og, fg = batch["og"], batch["fg"]
        if og > 1.0 and (og - fg) / (og - 1.0) > 0.95:
            yeast_mutations.append(batch["id"])
    return contaminated_barrels, yeast_mutations


def take_inventory(batches):
    """Total the hops drawn from the store and the finished strengths."""
    hop_stock = {}
    alcohol_percentages = {}
    for batch in batches:
        for variety, grams in batch.get("hops", {}).items():
            hop_stock[variety] = hop_stock.get(variety, 0) + grams
        alcohol_percentages[batch["id"]] = round((batch["og"] - batch["fg"]) * 131.25, 2)
    return hop_stock, alcohol_percentages


def brew(batches):
    """Evaluate the batch reports for the cellar master."""
    hop_stock, alcohol_percentages = take_inventory(batches)
    contaminated_barrels, _mutations = check_sanitation(batches)
    for barrel in contaminated_barrels:
        alcohol_percentages[barrel] = 0.0
    for variety in hop_stock:
        if hop_stock[variety] < 0:
            raise ValueError("negative hop draw for " + variety)
    return alcohol_percentages, contaminated_barrels


def format_report(batches, alcohol_percentages, contaminated_barrels):
    lines = []
    shelves = zip(("Hoppy ales", "Crisp lagers", "Dark stouts", "Tart sours"), sort_styles(batches))
    for label, shelf in shelves:
        ids = ", ".join(b["id"] for b in shelf) or "none"
        lines.append("{0}: {1}".format(label, ids))
    for batch_id, abv in sorted(alcohol_percentages.items()):
        lines.append("  {0} -> {1:.2f}% ABV".format(batch_id, abv))
    lines.append("Dumped barrels: " + (", ".join(contaminated_barrels) or "none"))
    return "\n".join(lines)


def main():
    batches = [
        {"id": "B1", "style": "IPA", "og": 1.062, "fg": 1.012, "ph": 4.3, "hops": {"Cascade": 80, "Citra": 45}},
        {"id": "B2", "style": "Pilsner", "og": 1.048, "fg": 1.010, "ph": 4.9, "hops": {"Saaz": 60}},
        {"id": "B3", "style": "Stout", "og": 1.070, "fg": 1.018, "ph": 4.5, "hops": {"Fuggle": 30}},
        {"id": "B4", "style": "Gose", "og": 1.040, "fg": 1.006, "ph": 3.4, "hops": {"Hallertau": 15}},
        {"id": "B5", "style": "Pale Ale", "og": 1.050, "fg": 1.001, "ph": 4.4, "hops": {"Cascade": 50}},
    ]
    percentages, dumped = brew(batches)
    print(format_report(batches, percentages, dumped))
    mutated = check_sanitation(batches)[1]
    print("Yeast mutations: " + (", ".join(mutated) or "none"))
    hop_stock = take_inventory(batches)[0]
    for variety, grams in sorted(hop_stock.items()):
        print("{0}: {1} g used".format(variety, grams))


if __name__ == "__main__":
    main()

