def divide_riders(rides):
    """Split ride events into the four judging divisions."""
    shortboard = []
    longboard = []
    big_wave = []
    junior = []
    for ride in rides:
        if ride.get("age", 99) < 18:
            junior.append(ride)
        elif ride["height"] >= 15.0:
            big_wave.append(ride)
        elif ride["board"] == "longboard":
            longboard.append(ride)
        else:
            shortboard.append(ride)
    return {
        "shortboard": shortboard,
        "longboard": longboard,
        "big wave": big_wave,
        "junior": junior,
    }


def collect_penalties(rides):
    """Return the names behind dramatic wipeouts and priority interferences."""
    wipeouts = []
    interferences = []
    for ride in rides:
        if ride.get("wipeout"):
            wipeouts.append(ride["surfer"])
        if ride.get("interference"):
            interferences.append(ride["surfer"])
    return wipeouts, interferences


def tabulate(rides):
    """Add up surfer points and rate the difficulty of every wave ridden."""
    surfer_points = {}
    wave_difficulty = {}
    for index, ride in enumerate(rides):
        difficulty = ride["height"] * 1.5 + ride.get("maneuvers", 0) * 0.5
        wave_difficulty[index] = round(difficulty, 2)
        if ride.get("wipeout"):
            continue
        earned = ride["height"] * 1.2 + ride.get("maneuvers", 0) * 2.0
        surfer_points[ride["surfer"]] = round(
            surfer_points.get(ride["surfer"], 0.0) + earned, 2)
    return surfer_points, wave_difficulty


def score(waves):
    """Score a sequence of ride events; return (surfer points, wipeouts)."""
    surfer_points, _difficulty = tabulate(waves)
    wipeouts, interferences = collect_penalties(waves)
    for surfer in interferences:
        surfer_points[surfer] = round(max(0.0, surfer_points.get(surfer, 0.0) - 5.0), 2)
    return surfer_points, wipeouts


def format_report(divisions, surfer_points, wave_difficulty):
    lines = []
    for division, riders in sorted(divisions.items()):
        totals = {}
        for ride in riders:
            totals[ride["surfer"]] = surfer_points.get(ride["surfer"], 0.0)
        lines.append(division.upper())
        for surfer, total in sorted(totals.items(), key=lambda kv: -kv[1]):
            lines.append("  {:<10} {:6.2f}".format(surfer, total))
    hardest = max(wave_difficulty, key=wave_difficulty.get)
    lines.append("hardest wave: ride {} rated {:.2f}".format(hardest, wave_difficulty[hardest]))
    return "\n".join(lines)


def main():
    waves = [
        {"surfer": "Kai", "board": "shortboard", "height": 6.0, "maneuvers": 4},
        {"surfer": "Kai", "board": "shortboard", "height": 8.5, "maneuvers": 5},
        {"surfer": "Mele", "board": "longboard", "height": 5.0, "maneuvers": 2},
        {"surfer": "Mele", "board": "longboard", "height": 4.0, "maneuvers": 3,
         "interference": True},
        {"surfer": "Rui", "board": "gun", "height": 22.0, "maneuvers": 1},
        {"surfer": "Rui", "board": "gun", "height": 18.0, "maneuvers": 2,
         "wipeout": True},
        {"surfer": "Ana", "board": "shortboard", "height": 3.5, "maneuvers": 6,
         "age": 15},
    ]
    surfer_points, wipeouts = score(waves)
    _points, wave_difficulty = tabulate(waves)
    print(format_report(divide_riders(waves), surfer_points, wave_difficulty))
    print("wipeouts: " + (", ".join(wipeouts) or "none"))


if __name__ == "__main__":
    main()

