SHAPE_GLAZES = {
    "mug": "cobalt blue",
    "bowl": "celadon green",
    "plate": "bone white",
    "vase": "copper red",
}

SHAPE_TEMPS = {
    "mug": 1220,
    "bowl": 1240,
    "plate": 1250,
    "vase": 1280,
}

DRY_LIMIT = 4.0


def sort_by_shape(pieces):
    mugs = []
    bowls = []
    plates = []
    vases = []
    for piece in pieces:
        shape = piece["shape"]
        if shape == "mug":
            mugs.append(piece)
        elif shape == "bowl":
            bowls.append(piece)
        elif shape == "plate":
            plates.append(piece)
        elif shape == "vase":
            vases.append(piece)
    return {"mug": mugs, "bowl": bowls, "plate": plates, "vase": vases}


def inspect_pieces(shelves):
    cracked_clay = []
    needs_drying = []
    ready = {}
    for shape, items in shelves.items():
        approved = []
        for piece in items:
            if piece.get("cracks"):
                cracked_clay.append(piece["name"])
            elif piece["moisture"] > DRY_LIMIT:
                needs_drying.append(piece["name"])
            else:
                approved.append(piece)
        ready[shape] = approved
    return ready, cracked_clay, needs_drying


def load_kiln(ready):
    glaze_recipes = {}
    kiln_temps = {}
    for shape, items in ready.items():
        if not items:
            continue
        glaze_recipes[shape] = SHAPE_GLAZES[shape]
        kiln_temps[shape] = SHAPE_TEMPS[shape]
    return glaze_recipes, kiln_temps


def fire(pieces):
    shelves = sort_by_shape(pieces)
    ready, cracked_clay, needs_drying = inspect_pieces(shelves)
    glaze_recipes, kiln_temps = load_kiln(ready)
    for shape, glaze in sorted(glaze_recipes.items()):
        names = ", ".join(p["name"] for p in ready[shape])
        print("%s: %s at %dC (%s)" % (shape, glaze, kiln_temps[shape], names))
    for name in needs_drying:
        print("%s returned to the drying rack" % name)
    return kiln_temps, cracked_clay


def main():
    sculpted = [
        {"name": "striped mug", "shape": "mug", "moisture": 2.1, "cracks": False},
        {"name": "wide bowl", "shape": "bowl", "moisture": 6.5, "cracks": False},
        {"name": "supper plate", "shape": "plate", "moisture": 1.0, "cracks": False},
        {"name": "tall vase", "shape": "vase", "moisture": 3.2, "cracks": True},
        {"name": "thumb mug", "shape": "mug", "moisture": 3.9, "cracks": False},
    ]
    temps, cracked = fire(sculpted)
    print("kiln program:", temps)
    print("scrapped clay:", cracked or "none")


if __name__ == "__main__":
    main()

