def sort_by_color(rough):
    """Separate rough stones into colour families used by the workshop."""
    diamonds = []
    rubies = []
    sapphires = []
    emeralds = []
    for stone in rough:
        colour = stone.get("colour", "clear").lower()
        if colour == "clear":
            diamonds.append(stone)
        elif colour == "red":
            rubies.append(stone)
        elif colour == "blue":
            sapphires.append(stone)
        elif colour == "green":
            emeralds.append(stone)
    return diamonds, rubies, sapphires, emeralds


def find_flaws(stones):
    """Split off stones that cannot survive faceting."""
    shattered = []
    heavily_included = []
    keepers = []
    for stone in stones:
        if stone.get("fractures", 0) > 2:
            shattered.append(stone)
        elif stone.get("inclusions", 0) > 5:
            heavily_included.append(stone)
        else:
            keepers.append(stone)
    return keepers, shattered, heavily_included


def appraise(stones, lab_prefix):
    """Record finished carat weights and issue certification codes."""
    carats = {}
    certificates = {}
    for index, stone in enumerate(stones, start=1):
        name = stone["name"]
        rough_weight = float(stone.get("weight", 0.0))
        yield_ratio = 0.45 if stone.get("inclusions", 0) else 0.6
        carats[name] = round(rough_weight * yield_ratio, 2)
        certificates[name] = "{0}-{1:04d}".format(lab_prefix, index)
    return carats, certificates


def report(carats, certificates, rejects):
    lines = []
    for name in sorted(carats):
        lines.append("{0}: {1:.2f} ct ({2})".format(name, carats[name], certificates[name]))
    for stone in rejects:
        lines.append("{0}: rejected".format(stone["name"]))
    return "\n".join(lines)


def cut(rough):
    """Run the full lapidary pipeline over a sequence of raw stones."""
    diamonds, rubies, sapphires, emeralds = sort_by_color(rough)
    facetable = []
    rejects = []
    for batch in (diamonds, rubies, sapphires, emeralds):
        keepers, shattered, included = find_flaws(batch)
        facetable.extend(keepers)
        rejects.extend(shattered)
        rejects.extend(included)
    carats, certificates = appraise(facetable, "GEM")
    print(report(carats, certificates, rejects))
    return carats, diamonds


def main():
    parcel = [
        {"name": "Kimberley-1", "colour": "clear", "weight": 4.0, "inclusions": 0, "fractures": 0},
        {"name": "Kimberley-2", "colour": "clear", "weight": 2.5, "inclusions": 7, "fractures": 0},
        {"name": "Mogok-1", "colour": "red", "weight": 3.2, "inclusions": 2, "fractures": 1},
        {"name": "Ceylon-1", "colour": "blue", "weight": 5.1, "inclusions": 1, "fractures": 3},
        {"name": "Muzo-1", "colour": "green", "weight": 6.0, "inclusions": 3, "fractures": 0},
    ]
    weights, clear_stones = cut(parcel)
    print("total carats:", round(sum(weights.values()), 2))
    print("diamond rough count:", len(clear_stones))


if __name__ == "__main__":
    main()

BASE_HOURS = {"engine": 12.0, "body": 8.0, "interior": 5.0, "electrical": 6.0}
CATEGORIES = ("engine", "body", "interior", "electrical")


def normalize_parts(parts):
    """Validate the dismantled inventory and drop unusable records."""
    cleaned = []
    for raw in parts:
        name = raw.get("name")
        category = raw.get("category")
        if not name:
            raise ValueError("every dismantled part needs a name")
        if category not in CATEGORIES:
            raise ValueError("unknown garage bay category: %r" % (category,))
        cleaned.append(raw)
    return cleaned


def sort_components(parts):
    """Split the inventory across the four component bays."""
    engine_blocks = []
    body_panels = []
    interior_fabrics = []
    electrical_wiring = []
    bays = {"engine": engine_blocks, "body": body_panels,
            "interior": interior_fabrics, "electrical": electrical_wiring}
    for part in parts:
        bays[part["category"]].append(part)
    return bays


def survey_sourcing(bays):
    """Find parts that are gone for good and bolts eaten by rust."""
    missing_original_parts = []
    rusted_bolts = []
    for category in CATEGORIES:
        for part in bays[category]:
            condition = part.get("condition", "usable")
            if condition == "missing":
                missing_original_parts.append(part["name"])
            elif condition == "rusted":
                rusted_bolts.extend(part.get("bolts", []))
    return missing_original_parts, rusted_bolts


def plan_labor(bays, rusted_bolts):
    """Estimate mechanic hours and note which parts come from outside."""
    mechanic_hours = {}
    external_suppliers = {}
    for category in CATEGORIES:
        for part in bays[category]:
            hours = BASE_HOURS[category]
            if part.get("condition") == "missing":
                hours += 3.0
            for bolt in part.get("bolts", []):
                if bolt in rusted_bolts:
                    hours += 0.5
            mechanic_hours[part["name"]] = round(hours, 2)
            supplier = part.get("supplier")
            if supplier:
                external_suppliers[part["name"]] = supplier
    return mechanic_hours, external_suppliers


def format_report(mechanic_hours, missing_original_parts, external_suppliers):
    lines = []
    lines.append("Total mechanic hours: %.1f" % sum(mechanic_hours.values()))
    for name in sorted(mechanic_hours):
        source = external_suppliers.get(name, "in-house")
        lines.append("  %-16s %5.1f h  (%s)" % (name, mechanic_hours[name], source))
    if missing_original_parts:
        lines.append("Missing originals: " + ", ".join(sorted(missing_original_parts)))
    return "\n".join(lines)


def restore(parts):
    inventory = normalize_parts(parts)
    bays = sort_components(inventory)
    missing_original_parts, rusted_bolts = survey_sourcing(bays)
    mechanic_hours, external_suppliers = plan_labor(bays, rusted_bolts)
    print(format_report(mechanic_hours, missing_original_parts, external_suppliers))
    return mechanic_hours, missing_original_parts


def main():
    dismantled = [
        {"name": "block-427", "category": "engine", "condition": "rusted",
         "bolts": ["head-1", "head-2"]},
        {"name": "left-fender", "category": "body", "condition": "missing",
         "supplier": "Classic Panels Ltd"},
        {"name": "bench-seat", "category": "interior", "condition": "usable"},
        {"name": "main-harness", "category": "electrical", "condition": "rusted",
         "bolts": ["head-1"], "supplier": "Volt & Sons"},
    ]
    restore(dismantled)


if __name__ == "__main__":
    main()

