def sort_by_element(spells):
    fire_invocations = []
    water_healing = []
    earth_wards = []
    air_illusions = []
    for spell in spells:
        element = spell.get("element", "").lower()
        if element == "fire":
            fire_invocations.append(spell["name"])
        elif element == "water":
            water_healing.append(spell["name"])
        elif element == "earth":
            earth_wards.append(spell["name"])
        elif element == "air":
            air_illusions.append(spell["name"])
    return fire_invocations, water_healing, earth_wards, air_illusions


def sort_by_restriction(spells):
    forbidden_dark_magic = []
    needs_rare_components = []
    for spell in spells:
        if spell.get("forbidden"):
            forbidden_dark_magic.append(spell["name"])
        if spell.get("components"):
            needs_rare_components.append(spell["name"])
    return forbidden_dark_magic, needs_rare_components


def sort_by_academics(spells):
    mana_rates = {}
    incantation_authors = {}
    for spell in spells:
        name = spell["name"]
        mana_rates[name] = spell.get("mana", 0)
        incantation_authors[name] = spell.get("author", "unknown")
    return mana_rates, incantation_authors


def read_scrolls(scrolls):
    spells = []
    for scroll in scrolls:
        fields = [part.strip() for part in scroll.split("|")]
        name, element, mana, author, flags = fields
        marks = [mark.strip() for mark in flags.split(",") if mark.strip()]
        spells.append({
            "name": name,
            "element": element,
            "mana": int(mana),
            "author": author,
            "forbidden": "forbidden" in marks,
            "components": "rare" in marks,
        })
    return spells


def format_report(elements, restrictions, academics):
    fire, water, earth, air = elements
    forbidden, rare = restrictions
    mana_rates, authors = academics
    lines = []
    for label, group in (("Fire", fire), ("Water", water), ("Earth", earth), ("Air", air)):
        lines.append("%s (%d): %s" % (label, len(group), ", ".join(group) or "none"))
    for name in sorted(mana_rates, key=lambda key: -mana_rates[key]):
        note = " [forbidden]" if name in forbidden else ""
        note += " [rare components]" if name in rare else ""
        lines.append("%s by %s costs %d mana%s" % (name, authors[name], mana_rates[name], note))
    return "\n".join(lines)


def catalog(spells):
    elements = sort_by_element(spells)
    restrictions = sort_by_restriction(spells)
    academics = sort_by_academics(spells)
    print(format_report(elements, restrictions, academics))
    return academics[0], restrictions[0]


def main():
    scrolls = [
        "Cinder Lance | fire | 40 | Pyrra of Ash | ",
        "Tidal Mercy | water | 25 | Nerin the Kind | rare",
        "Stonehide Aegis | earth | 30 | Brant Delve | ",
        "Whispering Veil | air | 15 | Sylwen | ",
        "Marrow Bloom | earth | 90 | The Nameless | forbidden, rare",
    ]
    mana_rates, forbidden = catalog(read_scrolls(scrolls))
    print("Total mana charted:", sum(mana_rates.values()))
    print("Sealed away:", ", ".join(forbidden))


if __name__ == "__main__":
    main()

