        marks = [mark.strip() for mark in flags.split(",") if mark.strip()]
        spells.append({
            "name": name,
            "element": element,
            "mana": int(mana),
            "author": author,
            "forbidden": "forbidden" in marks,
            "components": "rare" in marks,
        })
    return spells


def format_report(elements, restrictions, academics):
    fire, water, earth, air = elements
    forbidden, rare = restrictions
    mana_rates, authors = academics
    lines = list()
    for label, group in (("Fire", fire), ("Water", water), ("Earth", earth), ("Air", air)):
        lines.append("%s (%d): %s" % (label, len(group), ", ".join(group) or "none"))
    for name in sorted(mana_rates, key=lambda key: -mana_rates[key]):
        note = " [forbidden]" if name in forbidden else ""
        note += " [rare components]" if name in rare else ""
        lines.append("%s by %s costs %d mana%s" % (name, authors[name], mana_rates[name], note))
    return "\n".join(lines)


def catalog(spells):
    elements = sort_by_element(spells)
    restrictions = sort_by_restriction(spells)
    academics = sort_by_academics(spells)
    print(format_report(elements, restrictions, academics))
    return academics[0], restrictions[0]


