CATEGORY_BY_MATERIAL = {
    "sherd": "pottery",
    "amphora": "pottery",
    "tile": "pottery",
    "coin": "metal",
    "nail": "metal",
    "buckle": "metal",
    "bone": "biological",
    "seed": "biological",
    "shell": "biological",
}

FIELD_NAMES = ("trench", "material", "condition", "era", "researcher", "notable")


def parse_find(line):
    """Turn a pipe-separated field note into a find record."""
    fields = line.split("|")
    if len(fields) != len(FIELD_NAMES):
        raise ValueError("malformed field note: %r" % line)
    record = {}
    for name, value in zip(FIELD_NAMES, fields):
        record[name] = value.strip()
    record["notable"] = record["notable"].lower() in ("yes", "true", "1")
    return record


def category_of(material):
    return CATEGORY_BY_MATERIAL.get(material.lower(), "unidentified")


def catalogue(finds):
    pottery = []
    metal = []
    biological = []
    unidentified = []
    buckets = {
        "pottery": pottery,
        "metal": metal,
        "biological": biological,
        "unidentified": unidentified,
    }
    trench_items = {}
    researcher_finds = {}
    era_items = {}
    preservation_queue = []
    reconstruction_queue = []

    for find in finds:
        condition = find["condition"].lower()
        if condition == "debris":
            continue
        label = "%s (%s)" % (find["material"], find["era"])
        buckets[category_of(find["material"])].append(label)
        trench_items.setdefault(find["trench"], []).append(label)
        era_items.setdefault(find["era"], []).append(label)
        if find["notable"]:
            researcher_finds.setdefault(find["researcher"], []).append(label)
        if condition == "intact":
            preservation_queue.append(label)
        else:
            reconstruction_queue.append(label)

    total = sum(len(items) for items in buckets.values())
    top_era = max(era_items, key=lambda era: (len(era_items[era]), era), default="")
    top_researcher = max(
        researcher_finds,
        key=lambda name: (len(researcher_finds[name]), name),
        default="",
    )
    return total, top_era, top_researcher


def format_report(total, top_era, top_researcher):
    lines = []
    lines.append("Catalogued items: %d" % total)
    lines.append("Dominant era: %s" % (top_era or "unknown"))
    lines.append("Leading researcher: %s" % (top_researcher or "none"))
    return "\n".join(lines)


def main():
    notes = [
        "T1|sherd|broken|Roman|Alvarez|yes",
        "T1|coin|intact|Roman|Beck|no",
