        "T3|amphora|broken|Roman|Chen|yes",
        "T3|glass bead|intact|Medieval|Alvarez|yes",
    ]
    finds = []
    for note in notes:
        finds.append(parse_find(note))
    print(format_report(*catalogue(finds)))


