def manage(orders):
    awaiting_cutting = []
    stitching = []
    ready_for_fitting = []
    completed_suits = []
    measurements = {}
    fabric_yardage = {}
    tailor_tasks = {}
    suspense = []
    priority_queue = []

    for order in orders:
        customer = order.get("customer")
        profile = order.get("measurements")
        if not profile:
            suspense.append(order)
            continue
        measurements[customer] = profile
        if order.get("rush"):
            priority_queue.append(order)
        fabric = order.get("fabric", "unspecified")
        needed = order.get("yardage", 0)
        fabric_yardage[fabric] = fabric_yardage.get(fabric, 0) - needed
        tailor = order.get("tailor")
        if tailor:
            tailor_tasks.setdefault(tailor, []).append(customer)
        awaiting_cutting.append(order)

    for order in priority_queue + [o for o in awaiting_cutting if not o.get("rush")]:
        stage = order.get("stage", "cutting")
        if stage == "cutting":
            continue
        stitching.append(order)
        if stage in ("fitting", "done"):
            ready_for_fitting.append(order)
        if stage == "done":
            completed_suits.append(order)

    fabric_counts = {}
    for order in awaiting_cutting:
        fabric = order.get("fabric", "unspecified")
        fabric_counts[fabric] = fabric_counts.get(fabric, 0) + 1
    top_fabric = max(fabric_counts, key=fabric_counts.get) if fabric_counts else None
    busiest = max(tailor_tasks, key=lambda t: len(tailor_tasks[t])) if tailor_tasks else None
    return (top_fabric, len(completed_suits), busiest)


def report(orders, shifts):
    workload = {}
    for tailor, hours in shifts.items():
        workload[tailor] = {"hours": hours, "customers": []}
    for order in orders:
        tailor = order.get("tailor")
        if tailor in workload and order.get("measurements"):
            workload[tailor]["customers"].append(order["customer"])
    lines = []
    for tailor in sorted(workload):
        entry = workload[tailor]
        names = ", ".join(entry["customers"]) or "idle"
        lines.append("{0} ({1}h): {2}".format(tailor, entry["hours"], names))
    return "\n".join(lines)


