        {"diver": "Rosa", "grid": "C2", "bottom_time": 22.25,
         "finds": [{"type": "personal", "label": "leather shoe"}],
         "symptoms": ["joint pain", "dizziness"], "broken": ["stage bottle regulator"]},
    ]
    grid, diver, cost = coordinate(logs)
    print("richest grid: %s | longest bottom time: %s | preservation cost: %.2f" % (grid, diver, cost))


if __name__ == "__main__":
    main()

def track(tapestries):
    moth_damaged = []
    heavy_fading = []
    edge_reweaving = []
    perfectly_preserved = []
    dye_sources = {}
    castle_crests = {}
    restorer_hours = {}
    quarantine = []
    loom_schedule = []

    for record in tapestries:
        name = record.get("name", "unnamed hanging")
        condition = record.get("condition", "")
        if condition == "moth":
            moth_damaged.append(name)
        elif condition == "faded":
            heavy_fading.append(name)
        elif condition == "frayed_edges":
            edge_reweaving.append(name)
        elif condition == "pristine":
            perfectly_preserved.append(name)

        for color, dye in record.get("threads", []):
            sources = dye_sources.get(color)
            if sources is None:
                sources = []
                dye_sources[color] = sources
            if dye not in sources:
                sources.append(dye)

        castle = record.get("castle")
        if castle:
            crests = castle_crests.setdefault(castle, [])
            crest = record.get("crest")
            if crest and crest not in crests:
                crests.append(crest)

        restorer = record.get("restorer")
        if restorer:
            restorer_hours[restorer] = restorer_hours.get(restorer, 0.0) + float(record.get("hours", 0))

        if record.get("mold"):
            quarantine.append(name)
        if record.get("needs_backing"):
            loom_schedule.append(name)

    top_color = max(dye_sources, key=lambda c: (len(dye_sources[c]), c)) if dye_sources else None
    top_restorer = max(restorer_hours, key=lambda r: (restorer_hours[r], r)) if restorer_hours else None
    return top_color, top_restorer, len(perfectly_preserved)


def parse_assessments(documents):
    parsed = []
    for text in documents:
        record = {}
        threads = []
        for field in text.split(";"):
            if ":" not in field:
                continue
            key, value = (part.strip() for part in field.split(":", 1))
            if key == "thread":
                color, dye = value.split("=", 1)
                threads.append((color.strip(), dye.strip()))
            elif key == "hours":
                record[key] = float(value)
            elif key in ("mold", "needs_backing"):
                record[key] = value.lower() in ("yes", "true", "1")
            else:
                record[key] = value
        record["threads"] = threads
        parsed.append(record)
    return parsed


