def _tally_tools(era_tools):
    counts = {}
    for era, tool in era_tools:
        counts[tool] = counts.get(tool, 0) + 1
    return counts


def _top_tool(counts):
    best_tool = None
    best_count = 0
    for tool, count in counts.items():
        if count > best_count:
            best_tool = tool
            best_count = count
    return best_tool


def restore(clocks):
    waiting_disassembly = []
    in_cleaner = []
    reassembling = []
    tested = []
    scrap = []
    artisan_backlog = []

    deposits = {}
    era_tools = []
    supplier_stock = {}

    for clock in clocks:
        client = clock.get("client", "unknown")
        deposits[client] = deposits.get(client, 0.0) + float(clock.get("deposit", 0.0))

        era = clock.get("era", "modern")
        era_tools.append((era, _tool_for_era(era)))

        part = clock.get("part_number")
        if part is not None:
            suppliers = supplier_stock.setdefault(part, {})
            for name, units in clock.get("suppliers", {}).items():
                suppliers[name] = suppliers.get(name, 0) + int(units)

        if clock.get("rusted"):
            scrap.append(clock.get("id", client))
            continue

        engraving = clock.get("engraving")
        if engraving:
            artisan_backlog.append((client, engraving))

        stage = clock.get("stage", "waiting")
        if stage == "waiting":
            waiting_disassembly.append(clock)
        elif stage == "cleaning":
            in_cleaner.append(clock)
        elif stage == "reassembly":
            reassembling.append(clock)
        elif stage == "tested":
            tested.append(clock)

    top_client = max(deposits, key=deposits.get) if deposits else None
    return (top_client, _top_tool(_tally_tools(era_tools)), len(tested))


