ADVANCE_THRESHOLD = 2.0
RETREAT_THRESHOLD = -5.0
RISK_LEVELS = ("high", "extreme")


def classify_sectors(surveys):
    advancing = []
    retreating = []
    stable = []
    crevasses = []
    for record in surveys:
        sector = record["sector"]
        shift = record["front_change"]
        if shift >= ADVANCE_THRESHOLD:
            advancing.append(sector)
        elif shift <= RETREAT_THRESHOLD:
            retreating.append(sector)
        else:
            stable.append(sector)
        if record.get("new_crevasse"):
            crevasses.append(sector)
    return advancing, retreating, stable, crevasses


def map_measurements(surveys):
    discharge = {}
    thickness = {}
    caches = {}
    for record in surveys:
        valley = record["valley"]
        discharge[valley] = discharge.get(valley, 0.0) + record["discharge"]
        thickness.setdefault(tuple(record["coord"]), []).append(record["thickness"])
        caches.setdefault(record["team"], []).extend(record["caches"])
    return discharge, thickness, caches


def flag_operations(surveys):
    retakes = []
    warnings = []
    for record in surveys:
        if record["image_quality"] == "obscured":
            retakes.append(record["image_id"])
        if record["avalanche_risk"] in RISK_LEVELS:
            warnings.append(record["sector"])
    return retakes, warnings


def analyze(surveys):
    advancing, retreating, stable, crevasses = classify_sectors(surveys)
    discharge, thickness, caches = map_measurements(surveys)
    retakes, warnings = flag_operations(surveys)
    averages = dict((coord, sum(s) / len(s)) for coord, s in thickness.items())
    wettest = max(discharge, key=discharge.get) if discharge else None
    thinnest = min(averages, key=averages.get) if averages else None
    report = []
    for label, items in (("retreating", retreating), ("stable", stable), ("new crevasses", crevasses),
                         ("retake images", retakes), ("avalanche warnings", warnings)):
        report.append("%s: %s" % (label, ", ".join(items or ["none"])))
    for team, kit in sorted(caches.items()):
        report.append("%s cache: %s" % (team, ", ".join(kit)))
    for line in report:
        print(line)
    return wettest, thinnest, len(advancing)


def main():
    surveys = [
        {"sector": "Nord Face", "front_change": 3.4, "valley": "Zermatt", "discharge": 12.5,
         "coord": (46.02, 7.75), "thickness": 84.0, "team": "Alpha", "caches": ["drill"], "image_id": "IMG-01", "image_quality": "clear", "avalanche_risk": "low"},
