        {"brand": "Conway Stewart", "year": 1936, "fault": "cracked_body", "flex": "rigid",
         "line_width": 0.7, "collector": "Maeve", "feed": "sound", "rare": True},
        {"brand": "Onoto", "year": 1919, "fault": "none", "flex": "wet-noodle",
