def classify(pens):
    """Sort assessment tags into the four bench categories plus special routes."""
    bent_nibs = list()
    leaking_bladders = list()
    cracked_bodies = list()
    restored = list()
    harvest = list()
    museum = list()
    for pen in pens:
        fault = pen.get("fault", "")
        if fault == "bent_nib":
            bent_nibs.append(pen)
        elif fault == "leaking_bladder":
            leaking_bladders.append(pen)
        elif fault == "cracked_body":
            cracked_bodies.append(pen)
        elif fault == "none":
            restored.append(pen)
        if pen.get("feed") == "corroded":
            harvest.append(pen)
        if pen.get("rare"):
            museum.append(pen)
    return {
        "bent_nibs": bent_nibs,
        "leaking_bladders": leaking_bladders,
        "cracked_bodies": cracked_bodies,
        "restored": restored,
        "harvest": harvest,
        "museum": museum,
    }


def index_brand_years(pens):
    """Map each brand to the earliest manufacturing year seen on the bench."""
    years = dict()
    for pen in pens:
        brand = pen["brand"]
        year = pen["year"]
        if brand not in years or year < years[brand]:
            years[brand] = year
    return years


def index_flex_widths(pens):
    """Map nib flex ratings to the line widths measured for them."""
    widths = dict()
    for pen in pens:
        flex = pen.get("flex")
        if flex is None:
            continue
        widths.setdefault(flex, list()).append(pen.get("line_width", 0.0))
    return {flex: round(sum(v) / len(v), 2) for flex, v in widths.items()}


def index_collector_requests(pens):
    """Associate collectors with their outstanding purchase requests."""
    requests = dict()
    for pen in pens:
        collector = pen.get("collector")
        if collector:
            requests.setdefault(collector, list()).append(pen["brand"])
    return requests


def compile(pens):
    benches = classify(pens)
    brand_years = index_brand_years(pens)
    requests = index_collector_requests(pens)
    oldest_brand = min(brand_years, key=lambda b: brand_years[b]) if brand_years else None
    top_collector = max(requests, key=lambda c: len(requests[c])) if requests else None
    return oldest_brand, top_collector, len(benches["restored"])


def report(pens):
    """Human readable bench summary built from the daily notes."""
    benches = classify(pens)
    widths = index_flex_widths(pens)
    lines = list()
    for name in ("bent_nibs", "leaking_bladders", "cracked_bodies", "restored", "harvest", "museum"):
        brands = [pen["brand"] for pen in benches[name]]
        lines.append("%-18s %s" % (name, ", ".join(brands) or "-"))
    for flex in sorted(widths):
        lines.append("flex %-13s %.2f mm" % (flex, widths[flex]))
    return "\n".join(lines)


