PENALTY_POINTS = {"tangle": 1.5, "crash": 3.0, "line-cross": 0.5}


def wind_bracket(speed):
    if speed < 8:
        return "light"
    if speed < 18:
        return "moderate"
    return "strong"


def average_scores(pilot_scores):
    averages = {}
    for pilot, scores in pilot_scores.items():
        averages[pilot] = round(sum(scores) / len(scores), 2)
    return averages


def format_report(penalties, highlights, bracket_designs, averages, deductions):
    lines = []
    lines.append("=== Kite Festival Report ===")
    for pilot, avg in sorted(averages.items()):
        lines.append("{0:<16} average {1} (penalties -{2})".format(
            pilot, avg, deductions.get(pilot, 0.0)))
    for pilot, incident, cost in penalties:
        lines.append("PENALTY {0}: {1} (-{2})".format(pilot, incident, cost))
    for bracket in ("light", "moderate", "strong"):
        designs = bracket_designs.get(bracket, [])
        lines.append("{0} wind favours: {1}".format(bracket, ", ".join(designs) or "n/a"))
    for note in highlights:
        lines.append("HIGHLIGHT " + note)
    return "\n".join(lines)


def judge(flights):
    stunt_kites = []
    paper_kites = []
    inflatable_kites = []
    team_flights = []
    pilot_scores = {}
    country_rosters = {}
    bracket_designs = {}
    penalties = []
    highlights = []
    deductions = {}
    for flight in flights:
        pilot = flight["pilot"]
        country = flight.get("country", "UNK")
        category = flight.get("category", "stunt")
        design = flight.get("design", "unnamed")
        score = float(flight.get("score", 0.0))
        if category == "stunt":
            stunt_kites.append(design)
        elif category == "paper":
            paper_kites.append(design)
        elif category == "inflatable":
            inflatable_kites.append(design)
        elif category == "team":
            team_flights.append(design)
        pilot_scores.setdefault(pilot, []).append(score)
        roster = country_rosters.setdefault(country, [])
        if pilot not in roster:
            roster.append(pilot)
        if score >= 8.0:
            designs = bracket_designs.setdefault(wind_bracket(flight.get("wind", 0)), [])
            if design not in designs:
                designs.append(design)
        incident = flight.get("incident")
        if incident:
            cost = PENALTY_POINTS.get(incident, 1.0)
            penalties.append((pilot, incident, cost))
            deductions[pilot] = deductions.get(pilot, 0.0) + cost
        if flight.get("applause", 0) >= 90:
            highlights.append("{0} wowed the crowd with the {1}".format(pilot, design))
    best_scores = {}
    for pilot, scores in pilot_scores.items():
        best_scores[pilot] = max(scores)
    top_country = max(country_rosters, key=lambda c: (len(country_rosters[c]), c), default="")
    top_pilot = max(best_scores, key=lambda p: (best_scores[p], p), default="")
    print(format_report(penalties, highlights, bracket_designs,
                        average_scores(pilot_scores), deductions))
    return (top_country, top_pilot, len(inflatable_kites))


