def direct(logs):
    automated_beacons = []
    manned_towers = []
    offshore_platforms = []
    decommissioned_sites = []
    bulb_wattage = {}
    storm_tally = {}
    technician_routes = {}
    critical_repairs = []
    maritime_feedback = []

    for entry in logs:
        kind = entry.get("type", "")
        name = entry.get("name", "")
        if kind == "automated":
            automated_beacons.append(name)
        elif kind == "manned":
            manned_towers.append(name)
        elif kind == "offshore":
            offshore_platforms.append(name)
        elif kind == "decommissioned":
            decommissioned_sites.append(name)

        if "wattage" in entry:
            bulb_wattage[name] = entry["wattage"]

        region = entry.get("region")
        if region:
            storm_tally[region] = storm_tally.get(region, 0) + entry.get("storms", 0)

        technician = entry.get("technician")
        if technician:
            route = technician_routes.setdefault(technician, [])
            route.extend(entry.get("route", []))

        if entry.get("crack"):
            critical_repairs.append((name, entry["crack"]))
        if entry.get("complaint"):
            maritime_feedback.append((entry.get("ship", "unknown"), entry["complaint"]))

    worst_region = max(storm_tally, key=storm_tally.get) if storm_tally else None
    busiest = None
    if technician_routes:
        busiest = max(technician_routes, key=lambda t: len(technician_routes[t]))
    return (worst_region, busiest, len(offshore_platforms))


def summarize(logs):
    region, technician, offshore_count = direct(logs)
    lines = []
    lines.append("Stormiest region: {}".format(region or "n/a"))
    lines.append("Longest route technician: {}".format(technician or "n/a"))
    lines.append("Offshore platform lights: {}".format(offshore_count))
    return "\n".join(lines)


