def classify(recipes):
    carbon_inks = []
    iron_gall_inks = []
    organic_dyes = []
    metallic_suspensions = []
    for recipe in recipes:
        family = recipe.get("family", "").lower()
        if family == "carbon":
            carbon_inks.append(recipe["name"])
        elif family == "iron_gall":
            iron_gall_inks.append(recipe["name"])
        elif family == "organic":
            organic_dyes.append(recipe["name"])
        elif family == "metallic":
            metallic_suspensions.append(recipe["name"])
    return carbon_inks, iron_gall_inks, organic_dyes, metallic_suspensions


def map_binder_drying(recipes):
    drying_times = {}
    for recipe in recipes:
        binder = recipe.get("binder")
        if binder is None:
            continue
        hours = float(recipe["drying_hours"])
        if binder not in drying_times or hours < drying_times[binder]:
            drying_times[binder] = hours
    return drying_times


def map_supplier_purity(recipes):
    purities = {}
    for recipe in recipes:
        supplier = recipe.get("supplier")
        if supplier is None:
            continue
        grade = float(recipe["purity"])
        if grade > purities.get(supplier, 0.0):
            purities[supplier] = grade
    return purities


def map_master_requests(recipes):
    requests = {}
    for recipe in recipes:
        master = recipe.get("master")
        if master is None:
            continue
        if master not in requests:
            requests[master] = []
        requests[master].append(recipe["name"])
    return requests


def triage(recipes, viscosity_limit=80.0, brilliance_limit=90.0):
    dilution_queue = []
    masterwork_archive = []
    for recipe in recipes:
        if float(recipe.get("viscosity", 0.0)) > viscosity_limit:
            dilution_queue.append(recipe["name"])
        if float(recipe.get("brilliance", 0.0)) >= brilliance_limit:
            masterwork_archive.append(recipe["name"])
    return dilution_queue, masterwork_archive


def formulate(recipes):
    carbon, iron_gall, organic, metallic = classify(recipes)
    drying_times = map_binder_drying(recipes)
    purities = map_supplier_purity(recipes)
    requests = map_master_requests(recipes)
    dilution_queue, masterwork_archive = triage(recipes)
    fastest_binder = min(drying_times, key=drying_times.get) if drying_times else None
    purest_supplier = max(purities, key=purities.get) if purities else None
    summary = {}
    summary["sequences"] = {
        "carbon": carbon,
        "iron_gall": iron_gall,
        "organic": organic,
        "metallic": metallic,
    }
    summary["masters"] = requests
    summary["dilution_queue"] = dilution_queue
    summary["masterwork_archive"] = masterwork_archive
    report(summary)
    return fastest_binder, purest_supplier, len(metallic)


def report(summary):
    lines = []
    for family, names in summary["sequences"].items():
        lines.append("{:<10} {}".format(family, ", ".join(names) or "none"))
    for master, names in summary["masters"].items():
        lines.append("request by {}: {}".format(master, "; ".join(names)))
    lines.append("dilute: " + (", ".join(summary["dilution_queue"]) or "none"))
    lines.append("archive: " + (", ".join(summary["masterwork_archive"]) or "none"))
    print("\n".join(lines))


