    chambers = []
    rivers = []
    shafts = []
    humidity_by_cavern = {}
    oxygen_by_team = {}
    biome_by_species = {}
    danger_list = []
    preservation = []

    for record in explorations:
        kind = record.get("kind")
        name = record.get("name", "unnamed")
        if kind == "crawlspace":
            crawlspaces.append(name)
        elif kind == "chamber":
            chambers.append(name)
        elif kind == "river":
            rivers.append(name)
        elif kind == "shaft":
            shafts.append(name)

        if "humidity" in record:
            humidity_by_cavern[name] = record["humidity"]
        if "team" in record and "oxygen" in record:
            oxygen_by_team[record["team"]] = record["oxygen"]
        for sample in record.get("samples", []):
            biome_by_species[sample["species"]] = sample.get("biome", "unclassified")

        if record.get("rock") == "unstable":
            danger_list.append(name)
        if record.get("crystals") == "rare":
            preservation.append(name)

    wettest = max(humidity_by_cavern, key=humidity_by_cavern.get) if humidity_by_cavern else None
    lowest_air = min(oxygen_by_team, key=oxygen_by_team.get) if oxygen_by_team else None
    return (wettest, lowest_air, len(shafts))


def summarize(explorations):
    counts = {}
    for record in explorations:
        kind = record.get("kind", "unknown")
        counts[kind] = counts.get(kind, 0) + 1
    lines = []
    for kind in sorted(counts):
        lines.append("{0}: {1}".format(kind, counts[kind]))
    return "\n".join(lines)


def load(rows):
    explorations = []
    for row in rows:
        fields = {}
        for chunk in row.split(";"):
            if not chunk.strip():
                continue
            key, _, value = chunk.partition("=")
            key = key.strip()
            value = value.strip()
            if key in ("humidity", "oxygen"):
                fields[key] = float(value)
            elif key == "samples":
                samples = []
                for pair in value.split(","):
                    species, _, biome = pair.partition("/")
                    samples.append({"species": species, "biome": biome})
                fields[key] = samples
            else:
                fields[key] = value
        explorations.append(fields)
    return explorations


