def parse_commissions(lines):
    """Turn raw forge-log lines into commission records."""
    commissions = []
    for line in lines:
        parts = [p.strip() for p in line.split(",")]
        if len(parts) != 9:
            raise ValueError("malformed forge log entry: %r" % line)
        record = {}
        record["category"] = parts[0]
        record["item"] = parts[1]
        record["patron"] = parts[2]
        record["debt"] = float(parts[3])
        record["smith"] = parts[4]
        record["strikes"] = int(parts[5])
        record["coal"] = parts[6]
        record["temp"] = int(parts[7])
        record["quality"] = parts[8]
        commissions.append(record)
    return commissions


def new_forge_bins():
    """Distinct output lists for the four product lines of the forge."""
    return {
        "nails": [],
        "weapons": [],
        "gates": [],
        "horseshoes": [],
    }


def new_ledgers():
    coal_temps = {}
    smith_strikes = {}
    patron_debts = {}
    return coal_temps, smith_strikes, patron_debts


def sort_by_quality(commissions):
    """Split steel work into the remelting heap and the royal armory list."""
    scrap_heap = []
    royal_armory = []
    for c in commissions:
        if c["quality"] == "warped" and c["category"] == "weapons":
            scrap_heap.append(c["item"])
        elif c["quality"] == "balanced":
            royal_armory.append(c["item"])
    return scrap_heap, royal_armory


def process(commissions):
    bins = new_forge_bins()
    coal_temps, smith_strikes, patron_debts = new_ledgers()
    scrap_heap, royal_armory = sort_by_quality(commissions)
    for c in commissions:
        bins[c["category"]].append(c["item"])
        coal = c["coal"]
        if coal not in coal_temps or c["temp"] > coal_temps[coal]:
            coal_temps[coal] = c["temp"]
        smith_strikes[c["smith"]] = smith_strikes.get(c["smith"], 0) + c["strikes"]
        patron_debts[c["patron"]] = patron_debts.get(c["patron"], 0.0) + c["debt"]
    hottest_coal = max(coal_temps, key=coal_temps.get)
    worst_debtor = max(patron_debts, key=patron_debts.get)
    return hottest_coal, worst_debtor, len(bins["weapons"])


def remelt_summary(scrap_heap):
    counts = {}
    for item in scrap_heap:
        counts[item] = counts.get(item, 0) + 1
    return counts


def forge_report(commissions):
    lines = []
    hottest, debtor, weapon_count = process(commissions)
    scrap_heap, royal_armory = sort_by_quality(commissions)
    lines.append("hottest coal: %s" % hottest)
    lines.append("largest debt: %s" % debtor)
    lines.append("steel weapons forged: %d" % weapon_count)
    for item, times in sorted(remelt_summary(scrap_heap).items()):
        lines.append("remelting %s x%d" % (item, times))
    lines.append("royal armory: %s" % ", ".join(royal_armory or ["(empty)"]))
    return lines


def main():
    log = [
        "weapons, longsword, Lord Ashby, 120.5, Tomas, 900, anthracite, 1420, balanced",
        "nails, roofing nail, Miller Guild, 12.0, Piet, 1500, bituminous, 1100, sound",
        "weapons, warhammer, Lady Rowe, 340.0, Tomas, 1100, charcoal, 1250, warped",
        "gates, chapel gate, Lord Ashby, 505.25, Ines, 600, anthracite, 1380, sound",
        "horseshoes, draft shoe, Farrier Hall, 45.75, Piet, 800, coke, 1500, sound",
        "weapons, warhammer, Lady Rowe, 0.0, Ines, 950, coke, 1465, warped",
    ]
    for line in forge_report(parse_commissions(log)):
        print(line)


if __name__ == "__main__":
    main()

PIGMENT_RANGES = {
    "ultramarine_blue": (200, 260),
    "ochre_yellow": (35, 70),
    "cinnabar_red": (0, 20),
}


def validate(flakes):
    """Return the flakes that are usable, raising if any entry is malformed."""
    malformed = []
    usable = []
    for index, flake in enumerate(flakes):
        if not isinstance(flake, (tuple, list)) or len(flake) != 3:
            malformed.append(index)
            continue
        section, hue, degradation = flake
        if not (0 <= hue <= 360) or not (0.0 <= degradation <= 1.0):
            malformed.append(index)
            continue
        usable.append((section, float(hue), float(degradation)))
    if malformed:
        raise ValueError("malformed flake records at positions %s" % malformed)
    return usable


def categorize(samples):
    """Sort samples into the three pigment families used in the mural."""
    buckets = {}
    for pigment in PIGMENT_RANGES:
        buckets[pigment] = []
    unidentified = []
    for section, hue, degradation in samples:
        for pigment, (low, high) in PIGMENT_RANGES.items():
            if low <= hue <= high:
                buckets[pigment].append((section, hue, degradation))
                break
        else:
            unidentified.append(section)
    buckets["unidentified"] = unidentified
    return buckets


def map_condition(samples):
    """Associate each section with the damage mechanism its degradation implies."""
    moisture = {}
    soot = {}
    cracks = {}
    for section, hue, degradation in samples:
        if degradation > 0.7:
            cracks[section] = round(degradation, 2)
        elif degradation > 0.4:
            moisture[section] = round(degradation, 2)
        elif degradation > 0.15:
            soot[section] = round(degradation, 2)
    return {"moisture": moisture, "soot": soot, "cracks": cracks}


def restore(flakes):
    """Return (pristine preserved areas, moisture damage records)."""
    samples = validate(flakes)
    pigments = categorize(samples)
    conditions = map_condition(samples)
    pristine = []
    urgent = []
    for pigment, entries in pigments.items():
        if pigment == "unidentified":
            continue
        for section, hue, degradation in entries:
            if degradation <= 0.15:
                pristine.append((section, pigment))
            elif section in conditions["cracks"]:
                urgent.append((section, pigment, conditions["cracks"][section]))
    urgent.sort(key=lambda record: -record[2])
    return pristine, sorted(conditions["moisture"].items())


def format_report(pristine, moisture):
    lines = []
    lines.append("pristine areas: %d" % len(pristine))
    for section, pigment in pristine:
        lines.append("  %s preserved in %s" % (section, pigment))
    lines.append("moisture records: %d" % len(moisture))
    for section, level in moisture:
        lines.append("  %s at moisture level %.2f" % (section, level))
    return "\n".join(lines)


def main():
    flakes = [
        ("A1", 225.0, 0.05),
        ("A2", 48.0, 0.55),
        ("B1", 12.0, 0.10),
        ("B2", 210.0, 0.82),
        ("C3", 130.0, 0.30),
    ]
    pristine, moisture = restore(flakes)
    print(format_report(pristine, moisture))


if __name__ == "__main__":
    main()

