import math

MATCH_TOLERANCE_DEG = 0.05
BINARY_TOLERANCE_DEG = 0.2


def base_name(identifier):
    return identifier.split(":", 1)[-1]


def parse_records(stars):
    catalog_one = []
    catalog_two = []
    anomalies = []
    for record in stars:
        if len(record) != 4:
            anomalies.append((record, "malformed record"))
            continue
        identifier, ra, dec, classification = record
        if not 0.0 <= ra < 360.0 or not -90.0 <= dec <= 90.0:
            anomalies.append((identifier, "coordinates out of range"))
        elif identifier.startswith("C1:"):
            catalog_one.append((identifier, ra, dec, classification))
        elif identifier.startswith("C2:"):
            catalog_two.append((identifier, ra, dec, classification))
        else:
            anomalies.append((identifier, "unknown catalog prefix"))
    return catalog_one, catalog_two, anomalies


def group_by_class(records):
    binaries = {}
    variables = {}
    high_proper_motion = {}
    buckets = {"binary": binaries, "variable": variables, "hpm": high_proper_motion}
    for identifier, ra, dec, classification in records:
        bucket = buckets.get(classification)
        if bucket is not None:
            bucket.setdefault(base_name(identifier), []).append(identifier)
    return buckets


def angular_distance(ra1, dec1, ra2, dec2):
    delta_ra = (ra1 - ra2) * math.cos(math.radians((dec1 + dec2) / 2.0))
    return math.hypot(delta_ra, dec1 - dec2)


def match_catalogs(catalog_one, catalog_two, buckets):
    matched = []
    orphans = []
    claimed = {}
    for identifier, ra, dec, classification in catalog_one:
        tolerance = MATCH_TOLERANCE_DEG
        if base_name(identifier) in buckets["binary"]:
            tolerance = BINARY_TOLERANCE_DEG
        best_index, best_distance = None, None
        for index, candidate in enumerate(catalog_two):
            if index in claimed:
                continue
            distance = angular_distance(ra, dec, candidate[1], candidate[2])
            if distance <= tolerance and (best_distance is None or distance < best_distance):
                best_index, best_distance = index, distance
        if best_index is None:
            orphans.append(identifier)
        else:
            claimed[best_index] = identifier
            matched.append((identifier, catalog_two[best_index][0], round(best_distance, 6)))
    for index, candidate in enumerate(catalog_two):
        if index not in claimed:
            orphans.append(candidate[0])
    return matched, orphans


def format_report(matched, orphans, anomalies, buckets):
    lines = []
    for label, bucket in buckets.items():
        lines.append("%s systems: %d" % (label, len(bucket)))
    for left, right, distance in matched:
        lines.append("matched %s <-> %s at %.6f deg" % (left, right, distance))
    for identifier in orphans:
        lines.append("orphan %s" % identifier)
    for identifier, reason in anomalies:
        lines.append("anomaly %s (%s)" % (identifier, reason))
    return "\n".join(lines)


def crossmatch(stars):
    catalog_one, catalog_two, anomalies = parse_records(stars)
    buckets = group_by_class(catalog_one + catalog_two)
    matched, orphans = match_catalogs(catalog_one, catalog_two, buckets)
    if anomalies:
        orphans.extend(identifier for identifier, _ in anomalies if isinstance(identifier, str))
    return matched, orphans


def main():
    stars = [
        ("C1:HD1", 10.0, 20.0, "binary"),
        ("C2:HD1", 10.001, 20.0, "binary"),
        ("C1:HD2", 200.5, -30.0, "variable"),
        ("C2:HD2", 200.52, -30.01, "variable"),
        ("C2:HD9", 45.0, 5.0, "hpm"),
    ]
    catalog_one, catalog_two, anomalies = parse_records(stars)
    buckets = group_by_class(catalog_one + catalog_two)
    matched, orphans = crossmatch(stars)
    print(format_report(matched, orphans, anomalies, buckets))
    print("totals: %d pairs, %d orphans" % (len(matched), len(orphans)))


if __name__ == "__main__":
    main()

