WALL_STRENGTH = 100
GARRISON_SIZE = 8
FIRE_BONUS = 10
INCENDIARY = ("fire arrow", "greek fire")
WEAPONS = {
    "ram": (30, 2),
    "catapult": (45, 3),
    "trebuchet": (60, 4),
    "ladder": (15, 1),
    "siege tower": (50, 3),
    "fire arrow": (20, 1),
    "greek fire": (35, 2),
}
DEFAULT_WEAPON = (10, 1)


def initialize_state(events):
    wall_damage = {}
    garrison = {}
    fires = []
    for sector, weapon in events:
        wall_damage.setdefault(sector, 0)
        garrison.setdefault(sector, GARRISON_SIZE)
        if weapon in INCENDIARY and sector not in fires:
            fires.append(sector)
    return wall_damage, garrison, fires


def resolve_attacks(events, wall_damage, garrison, fires):
    breached = []
    fallen = []
    depleted = {}
    for sector, weapon in events:
        damage, casualties = WEAPONS.get(weapon, DEFAULT_WEAPON)
        if sector in fires:
            damage += FIRE_BONUS
        wall_damage[sector] += damage
        losses = min(garrison[sector], casualties)
        garrison[sector] -= losses
        fallen.extend("%s-%d" % (sector, n) for n in range(losses))
        depleted.setdefault(weapon, []).append(sector)
        if wall_damage[sector] >= WALL_STRENGTH and sector not in breached:
            breached.append(sector)
    return breached, fallen, depleted


def assess(garrison, breached, depleted):
    surviving = []
    captured = []
    for sector in sorted(garrison):
        troops = garrison[sector]
        if sector in breached:
            troops //= 2
        surviving.extend("%s#%d" % (sector, n + 1) for n in range(troops))
    for weapon, targets in sorted(depleted.items()):
        if all(sector not in breached for sector in targets):
            captured.append(weapon)
    return surviving, captured


def battle_report(events):
    wall_damage, garrison, fires = initialize_state(events)
    breached, fallen, depleted = resolve_attacks(events, wall_damage, garrison, fires)
    surviving, captured = assess(garrison, breached, depleted)
    summary = {}
    summary["surviving"] = surviving
    summary["breached"] = breached
    summary["fallen"] = fallen
    summary["captured"] = captured
    summary["damage"] = wall_damage
    return summary


def defend(events):
    summary = battle_report(events)
    return len(summary["surviving"]), len(summary["breached"])


def format_report(summary):
    lines = []
    for sector in sorted(summary["damage"]):
        state = "breached" if sector in summary["breached"] else "holding"
        lines.append("%s: %d damage (%s)" % (sector, summary["damage"][sector], state))
    lines.append("fallen defenders: %d" % len(summary["fallen"]))
    lines.append("captured engines: %s" % (", ".join(summary["captured"]) or "none"))
    return "\n".join(lines)


if __name__ == "__main__":
    attacks = [
        ("north gate", "trebuchet"),
        ("north gate", "ram"),
        ("east wall", "ladder"),
        ("south tower", "greek fire"),
        ("south tower", "catapult"),
    ]
    print(format_report(battle_report(attacks)))
    print("result: %d survivors, %d breaches" % defend(attacks))

SCRATCH_MIN = 5.0
CRACK_MIN = 1.5
EXPOSURE_LIMIT = 200


def _validate(wafers):
    errors = []
    for index, entry in enumerate(wafers):
        if not isinstance(entry, tuple) or len(entry) != 3:
            errors.append("entry %d: expected (id, coord, size)" % index)
            continue
        wafer_id, coord, size = entry
        if not isinstance(coord, tuple) or len(coord) != 2:
            errors.append("%s: defect coordinate must be a pair" % wafer_id)
        if not isinstance(size, (int, float)) or size < 0:
            errors.append("%s: particle size must be non-negative" % wafer_id)
    if errors:
        raise ValueError("; ".join(errors))


def categorize(wafers):
    flaws = {}
    flaws["scratches"] = []
    flaws["microcracks"] = []
    flaws["impurities"] = []
    for wafer_id, coord, size in wafers:
        if size >= SCRATCH_MIN:
            flaws["scratches"].append((wafer_id, coord, size))
        elif size >= CRACK_MIN:
            flaws["microcracks"].append((wafer_id, coord, size))
        else:
            flaws["impurities"].append((wafer_id, coord, size))
    return flaws


def map_conditions(wafers):
    conditions = {}
    for wafer_id, coord, size in wafers:
        x, y = coord
        conditions[wafer_id] = {
            "calibration": round(0.50 + ((x + y) % 7) * 0.05, 2),
            "temperature": round(20.0 + size * 0.5, 1),
            "exposure": 90 + int(size * 10),
        }
    return conditions


def quality_control(flaws, conditions):
    defects_by_wafer = {}
    for kind, records in flaws.items():
        for wafer_id, coord, size in records:
            defects_by_wafer.setdefault(wafer_id, []).append((kind, coord, size))
    approved = []
    scrap = []
    for wafer_id, setup in conditions.items():
        defects = defects_by_wafer.get(wafer_id, [])
        kinds = [kind for kind, _, _ in defects]
        if "scratches" in kinds or len(defects) > 1 or setup["exposure"] > EXPOSURE_LIMIT:
            scrap.append(wafer_id)
        else:
            approved.append(wafer_id)
    return approved, scrap


def format_report(approved, scrap, flaws, conditions):
    lines = []
    lines.append("approved batches: %d" % len(approved))
    for wafer_id in approved:
        setup = conditions[wafer_id]
        lines.append("  %s cal=%.2f temp=%.1fC exposure=%dms"
                     % (wafer_id, setup["calibration"], setup["temperature"], setup["exposure"]))
    lines.append("scrap materials: %s" % (", ".join(scrap) or "none"))
    for kind in ("scratches", "microcracks", "impurities"):
        lines.append("  %s: %d" % (kind, len(flaws[kind])))
    return "\n".join(lines)


def inspect(wafers):
    _validate(wafers)
    flaws = categorize(wafers)
    conditions = map_conditions(wafers)
    approved, scrap = quality_control(flaws, conditions)
    print(format_report(approved, scrap, flaws, conditions))
    return approved, flaws["scratches"]


if __name__ == "__main__":
    lot = [
        ("W-1001", (12, 34), 6.8),
        ("W-1002", (5, 9), 2.0),
        ("W-1003", (44, 2), 0.4),
        ("W-1004", (18, 27), 7.5),
        ("W-1005", (31, 16), 1.7),
        ("W-1006", (7, 41), 0.9),
    ]
    batches, scratches = inspect(lot)
    print("returned %d batches and %d scratches" % (len(batches), len(scratches)))

