SELF_INVERSE = ("H", "X", "Y", "Z", "CX", "CNOT", "SWAP")
MEASURE_NAMES = ("MEASURE", "M")
PHASE_SHIFTS = {"S": 0.5, "T": 0.25, "Z": 1.0}
ERROR_RATES = {"single": 0.001, "multi": 0.012, "measure": 0.021}


def parse_instructions(gates):
    categories = {}
    for key in ("single", "multi", "measure"):
        categories[key] = []
    for index, text in enumerate(gates):
        fields = text.split()
        if len(fields) < 2:
            raise ValueError("malformed instruction: %r" % text)
        name = fields[0].upper()
        targets = []
        for field in fields[1:]:
            if not field.lstrip("-").isdigit():
                raise ValueError("bad qubit index in %r" % text)
            targets.append(int(field))
        if name in MEASURE_NAMES:
            categories["measure"].append((index, name, targets))
        elif len(targets) > 1:
            categories["multi"].append((index, name, targets))
        else:
            categories["single"].append((index, name, targets))
    return categories


def build_state_map(categories):
    pairs = []
    phases = {}
    errors = {}
    for key in ("single", "multi", "measure"):
        for _index, name, targets in categories[key]:
            for qubit in targets:
                phases[qubit] = phases.get(qubit, 0.0) + PHASE_SHIFTS.get(name, 0.0)
                errors[qubit] = errors.get(qubit, 0.0) + ERROR_RATES[key]
            if key == "multi":
                pair = tuple(sorted(targets))
                if pair not in pairs:
                    pairs.append(pair)
    return pairs, phases, errors


def find_redundant(ordered):
    redundant = []
    stack = []
    for index, name, targets in ordered:
        if name in MEASURE_NAMES:
            stack = []
        elif name in SELF_INVERSE and stack and stack[-1][1:] == (name, targets):
            previous = stack.pop()
            redundant.append(previous[0])
            redundant.append(index)
        else:
            stack.append((index, name, targets))
    return redundant


def format_report(pairs, phases, errors):
    lines = []
    for pair in pairs:
        lines.append("entangled %d<->%d" % pair)
    for qubit in sorted(phases):
        lines.append("qubit %d phase=%.2f error=%.3f" % (qubit, phases[qubit], errors[qubit]))
    return "\n".join(lines)


def optimize(gates):
    categories = parse_instructions(gates)
    pairs, phases, errors = build_state_map(categories)
    ordered = []
    for key in ("single", "multi", "measure"):
        ordered.extend(categories[key])
    ordered.sort(key=lambda item: item[0])
    removed = find_redundant(ordered)
    sequence = []
    for index, name, targets in ordered:
        if index in removed:
            continue
        sequence.append(" ".join([name] + [str(target) for target in targets]))
    optimize.last_report = format_report(pairs, phases, errors)
    return sequence, pairs


def main():
    program = ["H 0", "H 0", "X 1", "CX 0 1", "MEASURE 0", "MEASURE 1"]
    sequence, pairs = optimize(program)
    print("optimized %d -> %d gates" % (len(program), len(sequence)))
    for line in sequence:
        print("  " + line)
    print("pairs:", pairs)
    print(optimize.last_report)


if __name__ == "__main__":
    main()

