from itertools import combinations


def parse_position(position):
    """Split a raw stage position into a zone and an optional prop."""
    if ":" in position:
        zone, prop = position.split(":", 1)
        return zone.strip(), prop.strip()
    return position.strip(), None


def classify_routines(moves):
    """Divide the routines into solo moves, partner lifts and group formations."""
    by_beat = {}
    for dancer, position, beat in moves:
        by_beat.setdefault(beat, []).append(dancer)
    solos = []
    lifts = []
    groups = []
    for beat in sorted(by_beat):
        dancers = sorted(by_beat[beat])
        if len(dancers) == 1:
            solos.append((beat, dancers[0]))
        elif len(dancers) == 2:
            lifts.append((beat, dancers))
        else:
            groups.append((beat, dancers))
    return solos, lifts, groups


def map_environment(moves):
    """Associate beats with stage positions, costume changes and prop usage."""
    stage = {}
    costumes = {}
    props = {}
    last_zone = {}
    for dancer, position, beat in sorted(moves, key=lambda move: (move[2], move[0])):
        zone, prop = parse_position(position)
        if beat not in stage:
            stage[beat] = {}
        stage[beat][dancer] = zone
        if prop is not None:
            props.setdefault(beat, []).append((dancer, prop))
        previous = last_zone.get(dancer)
        if previous is not None and previous != zone:
            costumes.setdefault(dancer, []).append((beat, previous, zone))
        last_zone[dancer] = zone
    return stage, costumes, props


def find_collisions(stage):
    """Evaluate trajectories and collect dancers sharing a zone on one beat."""
    collisions = []
    for beat in sorted(stage):
        zones = {}
        for dancer, zone in sorted(stage[beat].items()):
            zones.setdefault(zone, []).append(dancer)
        for zone in sorted(zones):
            for first, second in combinations(zones[zone], 2):
                collisions.append((beat, zone, first, second))
    return collisions


def build_timeline(stage, props, costumes, kinds):
    """Compile the final performance timeline, one step per beat."""
    timeline = []
    for beat in sorted(stage):
        changes = []
        for dancer in sorted(costumes):
            for change_beat, old_zone, new_zone in costumes[dancer]:
                if change_beat == beat:
                    changes.append((dancer, old_zone, new_zone))
        timeline.append({
            "beat": beat,
            "routine": kinds[beat],
            "positions": dict(stage[beat]),
            "props": list(props.get(beat, [])),
            "costume_changes": changes,
        })
    return timeline


def sequence(moves):
    cleaned = []
    for move in moves:
        if len(move) != 3:
            raise ValueError("each move needs a dancer, a position and a beat")
        dancer, position, beat = move
        cleaned.append((str(dancer), str(position), int(beat)))
    solos, lifts, groups = classify_routines(cleaned)
    kinds = {}
    for beat, _dancer in solos:
        kinds[beat] = "solo"
    for beat, _dancers in lifts:
        kinds[beat] = "lift"
    for beat, _dancers in groups:
        kinds[beat] = "group"
    stage, costumes, props = map_environment(cleaned)
    collisions = find_collisions(stage)
    timeline = build_timeline(stage, props, costumes, kinds)
    return timeline, collisions


def main():
    moves = [
        ("Ada", "center", 1),
        ("Ben", "left:fan", 2),
        ("Ada", "left", 3),
        ("Cleo", "right:ribbon", 4),
        ("Ben", "right", 5),
    ]
    timeline, collisions = sequence(moves)
    for step in timeline:
        print("beat {beat}: {routine} {positions}".format(**step))
    print("steps: {0}, collisions: {1}".format(len(timeline), len(collisions)))


if __name__ == "__main__":
    main()

