def sort_events(tremors):
    convergent = []
    divergent = []
    transform = []
    for region, magnitude, depth in tremors:
        if depth >= 70.0:
            convergent.append((region, magnitude, depth))
        elif magnitude < 6.0:
            divergent.append((region, magnitude, depth))
        else:
            transform.append((region, magnitude, depth))
    return convergent, divergent, transform


def map_shifts(convergent, divergent, transform):
    shifts = {}
    for region, magnitude, depth in convergent:
        record = shifts.setdefault(region, new_record())
        record["crustal_stress"] += magnitude * (1.0 + depth / 300.0)
        record["tsunami_risk"] += magnitude - 5.0 if depth < 200.0 else 0.4
    for region, magnitude, depth in divergent:
        record = shifts.setdefault(region, new_record())
        record["magma_pressure"] += magnitude * 2.0 - depth / 50.0
        record["crustal_stress"] += magnitude * 0.3
    for region, magnitude, depth in transform:
        record = shifts.setdefault(region, new_record())
        record["crustal_stress"] += magnitude * 1.5
        record["magma_pressure"] += 0.2
    return shifts


def new_record():
    record = {}
    record["crustal_stress"] = 0.0
    record["magma_pressure"] = 0.0
    record["tsunami_risk"] = 0.0
    return record


def analyse(shifts):
    high_risk = []
    stable_shields = []
    for region in sorted(shifts):
        record = shifts[region]
        if record["crustal_stress"] >= 9.0 and record["tsunami_risk"] > 0.5:
            high_risk.append(region)
        elif record["crustal_stress"] < 3.0 and record["magma_pressure"] < 4.0:
            stable_shields.append(region)
    return high_risk, stable_shields


def format_report(shifts, high_risk, stable_shields):
    lines = []
    for region in sorted(shifts):
        record = shifts[region]
        lines.append(
            "%-12s stress=%5.2f magma=%5.2f tsunami=%5.2f"
            % (region, record["crustal_stress"], record["magma_pressure"],
               record["tsunami_risk"])
        )
    lines.append("high risk zones: " + (", ".join(high_risk) or "none"))
    lines.append("stable shields: " + (", ".join(stable_shields) or "none"))
    return "\n".join(lines)


def map(tremors):
    convergent, divergent, transform = sort_events(tremors)
    shifts = map_shifts(convergent, divergent, transform)
    high_risk, _stable = analyse(shifts)
    return high_risk, convergent


def main():
    tremors = [
        ("Cascadia", 7.4, 120.0),
        ("Cascadia", 6.1, 45.0),
        ("Tohoku", 8.1, 30.0),
        ("Tohoku", 6.8, 90.0),
        ("Iceland", 5.2, 8.0),
        ("Iceland", 4.6, 12.0),
        ("Anatolia", 6.5, 15.0),
        ("Baltica", 3.9, 20.0),
    ]
    convergent, divergent, transform = sort_events(tremors)
    shifts = map_shifts(convergent, divergent, transform)
    high_risk, stable_shields = analyse(shifts)
    print(format_report(shifts, high_risk, stable_shields))
    zones, boundaries = map(tremors)
    print("returned %d high risk zones and %d convergent boundaries"
          % (len(zones), len(boundaries)))


if __name__ == "__main__":
    main()

RATE_UNITS_PER_MIN = 50.0
PASS_WINDOW_MIN = 12.0
STATIONS = {"GS-ALPHA": 900, "GS-BETA": 600, "GS-GAMMA": 450}
WEATHER_DELAY_MIN = {"GS-ALPHA": 1.5, "GS-BETA": 4.0, "GS-GAMMA": 2.5}


def queue_requests(requests):
    high = []
    medium = []
    low = []
    for entry in requests:
        sat, volume, priority = entry
        if volume <= 0:
            raise ValueError("data volume must be positive for %s" % sat)
        level = str(priority).lower()
        if level == "high":
            high.append((sat, float(volume)))
        elif level == "medium":
            medium.append((sat, float(volume)))
        elif level == "low":
            low.append((sat, float(volume)))
        else:
            raise ValueError("unknown priority %r for %s" % (priority, sat))
    return {"high": high, "medium": medium, "low": low}


def flatten_queues(buckets):
    ordered = []
    for level in ("high", "medium", "low"):
        for sat, volume in buckets[level]:
            ordered.append((sat, volume, level))
    return ordered


def map_infrastructure(ordered):
    assignments = {}
    bandwidth = {}
    delays = {}
    names = sorted(STATIONS)
    for index, (sat, volume, _level) in enumerate(ordered):
        station = names[index % len(names)]
        assignments[sat] = station
        bandwidth[station] = bandwidth.get(station, 0.0) + volume
        delays[sat] = WEATHER_DELAY_MIN[station]
    return assignments, bandwidth, delays


def evaluate(ordered, assignments, bandwidth, delays):
    downlinks = []
    missed = []
    for sat, volume, level in ordered:
        station = assignments[sat]
        duration = volume / RATE_UNITS_PER_MIN + delays[sat]
        if bandwidth[station] > STATIONS[station]:
            missed.append((sat, station, level, "station saturated"))
        elif duration > PASS_WINDOW_MIN:
            missed.append((sat, station, level, "pass too short"))
        else:
            downlinks.append((sat, station, level, round(duration, 2)))
    return downlinks, missed


def schedule(requests):
    ordered = flatten_queues(queue_requests(requests))
    assignments, bandwidth, delays = map_infrastructure(ordered)
    return evaluate(ordered, assignments, bandwidth, delays)


def format_report(downlinks, missed):
    lines = []
    lines.append("successful downlinks: %d" % len(downlinks))
    for sat, station, level, duration in downlinks:
        lines.append("  %s -> %s (%s) %.2f min" % (sat, station, level, duration))
    lines.append("missed passes: %d" % len(missed))
    for sat, station, level, reason in missed:
        lines.append("  %s -> %s (%s) %s" % (sat, station, level, reason))
    return "\n".join(lines)


def main():
    requests = [
        ("SAT-1", 400, "high"),
        ("SAT-2", 250, "low"),
        ("SAT-3", 700, "medium"),
        ("SAT-4", 120, "high"),
    ]
    downlinks, missed = schedule(requests)
    print(format_report(downlinks, missed))


if __name__ == "__main__":
    main()

