def validate(samples):
    """Clean the raw balloon telemetry and order it by altitude."""
    cleaned = []
    for entry in samples:
        if len(entry) != 3:
            raise ValueError("each sample needs altitude, concentration, temperature")
        altitude, concentration, temperature = entry
        cleaned.append((float(altitude), float(concentration), float(temperature)))
    cleaned.sort(key=lambda reading: reading[0])
    return cleaned


def categorize(readings):
    """Sort readings into carbon dioxide layers, methane pockets and N2O traces."""
    layers = {}
    layers["carbon_dioxide"] = []
    layers["methane"] = []
    layers["nitrous_oxide"] = []
    for reading in readings:
        concentration = reading[1]
        if concentration >= 350.0:
            layers["carbon_dioxide"].append(reading)
        elif concentration >= 50.0:
            layers["methane"].append(reading)
        else:
            layers["nitrous_oxide"].append(reading)
    return layers


def map_climate(readings):
    """Associate every altitude with its climate indicators."""
    climate = {}
    previous_temperature = None
    for altitude, concentration, temperature in readings:
        traits = {}
        traits["ozone_depletion"] = round(concentration / 450.0, 3)
        traits["thermal_inversion"] = (previous_temperature is not None
                                       and temperature > previous_temperature)
        traits["solar_absorption"] = round(concentration * (1.0 + altitude / 10000.0), 1)
        climate[altitude] = traits
        previous_temperature = temperature
    return climate


def forecast(layers, climate):
    """Compile severe warming zones and stable atmospheric layers."""
    gas_at_altitude = {}
    for gas, group in layers.items():
        for altitude, _concentration, _temperature in group:
            gas_at_altitude[altitude] = gas
    severe_zones = []
    stable_layers = []
    for altitude in sorted(climate):
        traits = climate[altitude]
        warming = traits["ozone_depletion"] > 0.8 and (traits["thermal_inversion"]
                                                       or traits["solar_absorption"] > 400.0)
        if warming and gas_at_altitude[altitude] != "nitrous_oxide":
            severe_zones.append(altitude)
        else:
            stable_layers.append(altitude)
    return severe_zones, stable_layers


def _analyze(samples):
    readings = validate(samples)
    layers = categorize(readings)
    climate = map_climate(readings)
    severe_zones, stable_layers = forecast(layers, climate)
    return layers, climate, severe_zones, stable_layers


def profile(samples):
    _layers, _climate, severe_zones, stable_layers = _analyze(samples)
    return severe_zones, _layers["methane"]


def summarize(samples):
    layers, climate, severe_zones, stable_layers = _analyze(samples)
    lines = []
    lines.append("severe warming zones: %s" % severe_zones)
    lines.append("stable atmospheric layers: %s" % stable_layers)
    for gas in ("carbon_dioxide", "methane", "nitrous_oxide"):
        lines.append("%s readings: %d" % (gas, len(layers[gas])))
    for altitude in severe_zones:
        traits = climate[altitude]
        lines.append("  %.0f m -> ozone %.3f, absorption %.1f, inversion %s"
                     % (altitude, traits["ozone_depletion"],
                        traits["solar_absorption"], traits["thermal_inversion"]))
    return "\n".join(lines)


def main():
    flight = [(500, 380, 18), (1500, 180, 12), (3000, 30, 4),
              (5000, 430, -2), (7000, 40, -15), (9000, 410, -12)]
    severe_zones, methane_pockets = profile(flight)
    print("zones=%d pockets=%d" % (len(severe_zones), len(methane_pockets)))
    print(summarize(flight))


if __name__ == "__main__":
    main()

import math

EARTH_RADIUS = 6378137.0
MERCATOR_SAFE = 66.5
POLAR_START = 85.0
MIN_ELEVATION = -11000.0
MAX_ELEVATION = 9000.0


def classify(coordinates):
    northern = []
    southern = []
    equatorial = []
    for point in coordinates:
        latitude = point[0]
        if latitude > 0:
            northern.append(point)
        elif latitude < 0:
            southern.append(point)
        else:
            equatorial.append(point)
    groups = {}
    groups["northern"] = northern
    groups["southern"] = southern
    groups["equatorial"] = equatorial
    return groups


def validate(point):
    if len(point) != 3:
        return "malformed record"
    latitude, longitude, elevation = point
    if abs(latitude) > 90:
        return "latitude out of bounds"
    if abs(longitude) > 180:
        return "longitude out of bounds"
    if elevation < MIN_ELEVATION or elevation > MAX_ELEVATION:
        return "elevation out of bounds"
    return None


def assign_region(latitude):
    if abs(latitude) >= POLAR_START:
        return "polar"
    if abs(latitude) <= MERCATOR_SAFE:
        return "mercator"
    return "robinson"


def project_point(latitude, longitude, elevation, region):
    scale = 1.0 + elevation / EARTH_RADIUS
    radius = EARTH_RADIUS * scale
    x = radius * math.radians(longitude)
    linear = radius * math.radians(latitude)
    if region == "mercator":
        y = radius * math.log(math.tan(math.pi / 4 + math.radians(latitude) / 2))
    elif region == "robinson":
        edge = radius * math.log(math.tan(math.pi / 4 + math.radians(MERCATOR_SAFE) / 2))
        weight = (abs(latitude) - MERCATOR_SAFE) / (POLAR_START - MERCATOR_SAFE)
        blended = edge * (1 - weight) + abs(linear) * weight
        y = blended if latitude >= 0 else -blended
        x = x * (1 - 0.15 * weight)
    else:
        polar_radius = radius * math.tan(math.pi / 4 - math.radians(abs(latitude)) / 2)
        y = (radius - polar_radius) if latitude >= 0 else (polar_radius - radius)
        x = x * math.cos(math.radians(abs(latitude)))
    return x, y


def convert(coordinates):
    projected = []
    errors = []
    groups = classify(coordinates)
    for hemisphere, points in groups.items():
        for point in points:
            problem = validate(point)
            if problem is not None:
                errors.append((point, problem))
                continue
            latitude, longitude, elevation = point
            region = assign_region(latitude)
            x, y = project_point(latitude, longitude, elevation, region)
            mapped = {}
            mapped["hemisphere"] = hemisphere
            mapped["region"] = region
            mapped["source"] = point
            mapped["x"] = round(x, 2)
            mapped["y"] = round(y, 2)
            projected.append(mapped)
    return projected, errors


def format_report(projected, errors):
    region_counts = {}
    for mapped in projected:
        region_counts[mapped["region"]] = region_counts.get(mapped["region"], 0) + 1
    lines = []
    lines.append("projected points: %d" % len(projected))
    for mapped in projected:
        lines.append("  %s/%s %s -> (%.2f, %.2f)" % (mapped["hemisphere"], mapped["region"],
                                                     mapped["source"], mapped["x"], mapped["y"]))
    for region in sorted(region_counts):
        lines.append("  region %s: %d" % (region, region_counts[region]))
    lines.append("projection errors: %d" % len(errors))
    for point, problem in errors:
        lines.append("  %s -> %s" % (point, problem))
    return "\n".join(lines)


def main():
    coordinates = [
        (48.85, 2.35, 35.0),
        (-33.86, 151.21, 58.0),
        (0.0, -78.52, 2850.0),
        (91.0, 10.0, 0.0),
        (87.2, 25.0, 1200.0),
        (-70.4, 12.5, 2100.0),
    ]
    projected, errors = convert(coordinates)
    print(format_report(projected, errors))


if __name__ == "__main__":
    main()

"""Indexing tool for comparative folklore studies."""

CATEGORY_KEYWORDS = {
    "creation myths": ("creation", "origin", "cosmogony", "first"),
    "trickster tales": ("trickster", "cunning", "coyote", "theft"),
    "heroic epics": ("hero", "quest", "epic", "warrior"),
}

ELEMENT_KEYWORDS = {
    "animal spirits": ("animal", "raven", "serpent", "coyote", "spirit"),
    "pantheon deities": ("deity", "god", "pantheon", "creation"),
    "underworld journeys": ("underworld", "descent", "death", "shadow"),
}


def classify(theme, keyword_table):
    words = [word.strip(",.;").lower() for word in theme.split()]
    for label, keywords in keyword_table.items():
        for word in words:
            if word in keywords:
                return label
    return None


def categorize(tales):
    categories = {}
    for label in CATEGORY_KEYWORDS:
        categories[label] = []
    unsorted_titles = []
    for title, region, theme in tales:
        label = classify(theme, CATEGORY_KEYWORDS)
        if label is None:
            unsorted_titles.append(title)
        else:
            categories[label].append((title, region))
    categories["unsorted"] = unsorted_titles
    return categories


def map_cultural_elements(tales):
    elements = {}
    for title, region, theme in tales:
        if region not in elements:
            record = {}
            for kind in ELEMENT_KEYWORDS:
                record[kind] = []
            elements[region] = record
        kind = classify(theme, ELEMENT_KEYWORDS)
        if kind is not None:
            elements[region][kind].append(title)
    return elements


def cross_reference(tales):
    motif_regions = {}
    for title, region, theme in tales:
        motif = theme.strip().lower()
        if motif not in motif_regions:
            motif_regions[motif] = []
        if region not in motif_regions[motif]:
            motif_regions[motif].append(region)
    shared = []
    unique = {}
    for motif, regions in motif_regions.items():
        if len(regions) > 1:
            shared.append((motif, sorted(regions)))
        else:
            unique.setdefault(regions[0], []).append(motif)
    return shared, unique


def format_report(categories, elements, shared, unique):
    lines = []
    lines.append("FOLKLORE INDEX")
    for label, entries in categories.items():
        lines.append("%s: %d" % (label, len(entries)))
    for region, record in sorted(elements.items()):
        tracked = []
        for kind, titles in record.items():
            if titles:
                tracked.append("%s=%s" % (kind, ", ".join(titles)))
        lines.append("  %s -> %s" % (region, "; ".join(tracked) or "no elements"))
    for motif, regions in shared:
        lines.append("shared motif '%s' in %s" % (motif, " & ".join(regions)))
    for region, motifs in sorted(unique.items()):
        lines.append("local legend of %s: %s" % (region, ", ".join(motifs)))
    return lines


def index(tales):
    categories = categorize(tales)
    elements = map_cultural_elements(tales)
    shared, unique = cross_reference(tales)
    print("\n".join(format_report(categories, elements, shared, unique)))
    return shared, categories["creation myths"]


def main():
    tales = [
        ("The Sky Egg", "West Africa", "Creation of the world"),
        ("Raven Steals the Light", "Pacific Northwest", "Trickster theft"),
        ("First Mother", "Mesoamerica", "Creation of the world"),
        ("Descent of the Warrior", "Aegean", "Hero descent to death"),
    ]
    shared, creation = index(tales)
    print("%d shared motif(s), %d creation myth(s)" % (len(shared), len(creation)))


if __name__ == "__main__":
    main()

