def categorize(vents):
    """Split vents into black smokers, white smokers and cold seeps."""
    black_smokers = []
    white_smokers = []
    cold_seeps = []
    for name, temp, depth in vents:
        if temp >= 300:
            black_smokers.append((name, temp, depth))
        elif temp >= 100:
            white_smokers.append((name, temp, depth))
        else:
            cold_seeps.append((name, temp, depth))
    return black_smokers, white_smokers, cold_seeps


def map_ecology(black_smokers, white_smokers, cold_seeps):
    """Associate each vent with the communities it is expected to host."""
    ecology = {}
    for name, temp, depth in black_smokers:
        ecology[name] = ["extremophile bacteria", "mineral deposits"]
    for name, temp, depth in white_smokers:
        colonies = ["tubeworm colonies", "mineral deposits"]
        if temp >= 200:
            colonies.append("extremophile bacteria")
        ecology[name] = colonies
    for name, temp, depth in cold_seeps:
        ecology[name] = ["tubeworm colonies"]
    return ecology


def chart_routes(vents, black_smokers):
    """Compile submersible routes that avoid scalding plumes and crush depths."""
    scalding = {name for name, temp, depth in black_smokers}
    safe_routes = []
    hazard_zones = []
    for name, temp, depth in vents:
        if depth > 3000:
            hazard_zones.append((name, "crush pressure", depth))
        elif name in scalding:
            hazard_zones.append((name, "scalding plume", depth))
        else:
            safe_routes.append((name, depth))
    return safe_routes, hazard_zones


def summarize(ecology, hazard_zones):
    """Build a per-community census and a reason-keyed hazard index."""
    census = {}
    for name, communities in ecology.items():
        for community in communities:
            census.setdefault(community, []).append(name)
    hazard_index = {}
    for name, reason, depth in hazard_zones:
        hazard_index.setdefault(reason, []).append((name, depth))
    return census, hazard_index


def explore(vents):
    black_smokers, white_smokers, cold_seeps = categorize(vents)
    ecology = map_ecology(black_smokers, white_smokers, cold_seeps)
    safe_routes, hazard_zones = chart_routes(vents, black_smokers)
    census, hazard_index = summarize(ecology, hazard_zones)
    for community in sorted(census):
        print("{}: {}".format(community, ", ".join(sorted(census[community]))))
    for reason in sorted(hazard_index):
        spots = ["{} at {}m".format(n, d) for n, d in hazard_index[reason]]
        print("HAZARD {} -> {}".format(reason, "; ".join(spots)))
    return safe_routes, black_smokers


def main():
    survey = [
        ("V-01", 364.0, 2450),
        ("V-02", 215.5, 1980),
        ("V-03", 12.0, 2100),
        ("V-04", 88.0, 3400),
    ]
    routes, smokers = explore(survey)
    print("safe routes:", routes)
    print("black smokers:", smokers)


if __name__ == "__main__":
