def classify_word(word):
    """Return the linguistic feature a vocabulary word illustrates."""
    if any(ord(ch) > 127 for ch in word):
        return "loan_words"
    if "'" in word or "\u2019" in word:
        return "phonetic_shifts"
    return "slang"


def parse_patterns(sentences):
    """Sort raw records into SVO, SOV and anomalous speech patterns."""
    svo = []
    sov = []
    anomalous = []
    for record in sentences:
        if len(record) != 3:
            anomalous.append(("unknown", "malformed", record))
            continue
        region, structure, word = record
        tag = str(structure).strip().upper()
        if tag == "SVO":
            svo.append((region, word))
        elif tag == "SOV":
            sov.append((region, word))
        else:
            anomalous.append((region, tag, word))
    return {"SVO": svo, "SOV": sov, "anomalous": anomalous}


def map_evolution(parsed):
    """Associate each region with its slang, phonetic shifts and loan words."""
    regions = {}
    pairs = [(r, w) for r, w in parsed["SVO"] + parsed["SOV"]]
    pairs.extend((item[0], item[2]) for item in parsed["anomalous"] if isinstance(item[2], str))
    for region, word in pairs:
        profile = regions.get(region)
        if profile is None:
            profile = {}
            profile["slang"] = []
            profile["phonetic_shifts"] = []
            profile["loan_words"] = []
            regions[region] = profile
        bucket = profile[classify_word(word)]
        if word not in bucket:
            bucket.append(word)
    return regions


def analyze_rules(parsed):
    """Compile rules attested in several regions and region-specific divergences."""
    usage = {}
    for rule in ("SVO", "SOV"):
        for region, _word in parsed[rule]:
            holders = usage.get(rule)
            if holders is None:
                holders = []
                usage[rule] = holders
            if region not in holders:
                holders.append(region)
    shared = []
    diverging = {}
    for rule in sorted(usage):
