SPECIES_KEYS = ("monarch", "swallowtail", "painted_lady")
SPECIES_TOKENS = {"monarch": "monarch", "swallowtail": "swallowtail", "painted_lady": "painted lady"}
HEALTHY_WING = 5.0
MIN_ROUTE_STOPS = 2


def classify(name):
    label = name.strip().lower()
    for key in SPECIES_KEYS:
        if SPECIES_TOKENS[key] in label:
            return key
    return None


def group_sightings(sightings):
    groups = {}
    for key in SPECIES_KEYS:
        groups[key] = []
    for record in sightings:
        if len(record) != 3:
            raise ValueError("each sighting needs species, location and wing condition")
        species, location, wing = record
        if not 0 <= wing <= 10:
            raise ValueError("wing condition must be rated from 0 to 10: %r" % (wing,))
        key = classify(species)
        if key is not None:
            groups[key].append((location.strip(), float(wing)))
    return groups


def map_journey(groups):
    journey = {}
    for key in SPECIES_KEYS:
        for location, wing in groups[key]:
            if location not in journey:
                entry = {}
                entry["resting"] = []
                entry["nectar"] = []
                entry["predators"] = []
                journey[location] = entry
            if wing >= HEALTHY_WING:
                journey[location]["resting"].append(key)
                journey[location]["nectar"].append(key)
            else:
                journey[location]["predators"].append(key)
    return journey


def route_journey(groups, journey):
    paths = []
    stragglers = []
    for key in SPECIES_KEYS:
        records = groups[key]
        if not records:
            continue
        stops = []
        for location, _wing in records:
            if location not in stops:
                stops.append(location)
        condition = sum(wing for _loc, wing in records) / len(records)
        if len(stops) >= MIN_ROUTE_STOPS and condition >= HEALTHY_WING:
            path = {}
            path["species"] = key
            path["route"] = stops
            path["nectar_stops"] = sum(len(journey[stop]["nectar"]) for stop in stops)
            paths.append(path)
        else:
            straggler = {}
            straggler["species"] = key
            straggler["last_seen"] = stops[-1]
            straggler["condition"] = round(condition, 1)
            stragglers.append(straggler)
    return paths, stragglers


def follow(sightings):
    groups = group_sightings(sightings)
    journey = map_journey(groups)
    return route_journey(groups, journey)


def format_report(paths, stragglers):
    lines = []
    for path in paths:
        lines.append("%s migrates via %s (%d nectar stops)"
                     % (path["species"], " -> ".join(path["route"]), path["nectar_stops"]))
    for straggler in stragglers:
        lines.append("%s left behind at %s, wings %.1f"
                     % (straggler["species"], straggler["last_seen"], straggler["condition"]))
    return "\n".join(lines)


def main():
    observations = [
        ("Monarch butterfly", "Cape May", 8),
        ("Monarch butterfly", "Veracruz", 7),
        ("Eastern Swallowtail", "Austin", 6),
        ("Eastern Swallowtail", "Monterrey", 9),
