    cleaned = []
    for entry in visits:
        if len(entry) != 3:
            raise ValueError("each visit needs a building, an insect and a plant")
        building, insect, plant = entry
        cleaned.append((building.strip(), insect.strip().lower(), plant.strip().lower()))
    return cleaned


def classify_insects(records):
    groups = {}
    for _, insect, _ in records:
        if not insect:
            continue
        if "honey" in insect:
            label = "honeybees"
        elif "bumble" in insect:
            label = "bumblebees"
        else:
            label = "solitary bees"
        groups.setdefault(label, []).append(insect)
    return groups


def map_ecosystem(records):
    ecosystem = {}
    for building, insect, plant in records:
        if building not in ecosystem:
            record = {}
            record["plants"] = []
            record["nesting_sites"] = []
            record["pesticide_risks"] = []
            ecosystem[building] = record
        record = ecosystem[building]
        if plant and plant not in record["plants"]:
            record["plants"].append(plant)
        if insect and "honey" not in insect and "bumble" not in insect:
            if plant not in record["nesting_sites"]:
                record["nesting_sites"].append(plant)
        if plant in PESTICIDE_PLANTS and plant not in record["pesticide_risks"]:
            record["pesticide_risks"].append(plant)
    return ecosystem


def evaluate_routes(ecosystem):
