    isolated = []
    for building in sorted(ecosystem):
        record = ecosystem[building]
        if not record["plants"]:
            isolated.append(building)
        elif len(record["plants"]) >= 2 or record["nesting_sites"]:
            corridors.append(building)
        else:
            isolated.append(building)
    return {"corridors": corridors, "isolated": isolated}


