REGIONS = {"N": "northern airspace", "NE": "north-eastern airspace",
           "E": "eastern airspace", "SE": "south-eastern airspace",
           "S": "southern airspace", "SW": "south-western airspace",
           "W": "western airspace", "NW": "north-western airspace"}


def _band(height):
    for name, low, high in BANDS:
        if low <= height < high:
            return name
    return "low atmospheric ash"


def _region(wind):
    if isinstance(wind, (int, float)):
        key = SECTORS[int(round((wind % 360) / 45.0)) % 8]
    else:
        key = str(wind).strip().upper()
    return REGIONS.get(key, "unclassified airspace")


def classify_altitude(eruptions):
    layers = {}
    for name, height, wind in eruptions:
        band = _band(float(height))
        if band not in layers:
            layers[band] = []
        layers[band].append((name, float(height), wind))
    return layers


def _new_region():
    region = {}
    region["grounded_flights"] = []
    region["air_quality_warnings"] = []
    region["ashfall_deposits"] = []
    return region


def map_hazards(layers):
    hazard_map = {}
    for band, events in layers.items():
        for name, height, wind in events:
            region = _region(wind)
            if region not in hazard_map:
                hazard_map[region] = _new_region()
            entry = hazard_map[region]
            if band == "stratospheric ash":
                entry["grounded_flights"].append((name, height))
            elif band == "tropospheric ash":
                entry["air_quality_warnings"].append((name, height))
            else:
                entry["ashfall_deposits"].append((name, height))
    return hazard_map


def forecast(hazard_map):
    safe_corridors = []
    hazardous_zones = []
    for region in sorted(hazard_map):
        if hazard_map[region]["grounded_flights"]:
            hazardous_zones.append(region)
        else:
            safe_corridors.append(region)
    return safe_corridors, hazardous_zones


def model(eruptions):
    hazard_map = map_hazards(classify_altitude(eruptions))
    safe_corridors, _zones = forecast(hazard_map)
    grounded_flights = []
    for region in sorted(hazard_map):
        for name, height in hazard_map[region]["grounded_flights"]:
            grounded_flights.append((region, name, height))
    return safe_corridors, grounded_flights


def report(eruptions):
    lines = []
    hazard_map = map_hazards(classify_altitude(eruptions))
    safe_corridors, hazardous_zones = forecast(hazard_map)
    for region in sorted(hazard_map):
        entry = hazard_map[region]
        lines.append("%s: %d grounded, %d warnings, %d ashfall" % (
            region, len(entry["grounded_flights"]),
            len(entry["air_quality_warnings"]),
            len(entry["ashfall_deposits"])))
    lines.append("safe corridors: " + ", ".join(safe_corridors))
    lines.append("hazardous zones: " + ", ".join(hazardous_zones))
    return lines


