    safe_corridors, _zones = forecast(hazard_map)
    grounded_flights = list()
    for region in sorted(hazard_map):
        for name, height in hazard_map[region]["grounded_flights"]:
            grounded_flights.append((region, name, height))
    return safe_corridors, grounded_flights


