        lines.append("%s: %d grounded, %d warnings, %d ashfall" % (
            region, len(entry["grounded_flights"]),
            len(entry["air_quality_warnings"]),
            len(entry["ashfall_deposits"])))
    lines.append("safe corridors: " + ", ".join(safe_corridors))
    lines.append("hazardous zones: " + ", ".join(hazardous_zones))
    return lines


