VALID_STATUSES = ("healthy", "injured", "missing")


def track(sightings):
    healthy = []
    injured = []
    missing = []
    anomalies = []
    by_zone = {}
    by_species = {}
    alerts = []

    for record in sightings:
        if not isinstance(record, tuple) or len(record) != 4:
            anomalies.append(record)
            continue
        species, zone, status, age_group = record
        if status not in VALID_STATUSES:
            anomalies.append(record)
            continue

        if zone not in by_zone:
            by_zone[zone] = []
        by_zone[zone].append(species)

        if species not in by_species:
            by_species[species] = []
        by_species[species].append(zone)

        if status == "healthy":
            healthy.append(species)
        elif status == "injured":
            injured.append(species)
            alerts.append("Injured %s (%s) reported in %s" % (species, age_group, zone))
        else:
            missing.append(species)
            alerts.append("Missing %s (%s) last seen in %s" % (species, age_group, zone))

    summary = {
        "by_zone": by_zone,
        "by_species": by_species,
        "healthy": healthy,
        "injured": injured,
        "missing": missing,
        "anomalies": anomalies,
    }
    return summary, alerts


def zone_status_counts(sightings):
    counts = {}
    for record in sightings:
        if not isinstance(record, tuple) or len(record) != 4:
            continue
        zone, status = record[1], record[2]
        if zone not in counts:
            counts[zone] = {}
        tally = counts[zone]
        tally[status] = tally.get(status, 0) + 1
    return counts


def format_report(summary, alerts, counts):
    lines = []
    lines.append("Zones observed: %d" % len(summary["by_zone"]))
    for zone in sorted(summary["by_zone"]):
        animals = ", ".join(sorted(summary["by_zone"][zone]))
        breakdown = counts.get(zone, {})
        detail = " ".join("%s=%d" % (k, breakdown[k]) for k in sorted(breakdown))
        lines.append("  %s: %s [%s]" % (zone, animals, detail))
    lines.append("Healthy: %d  Injured: %d  Missing: %d  Anomalous: %d" % (
        len(summary["healthy"]), len(summary["injured"]),
        len(summary["missing"]), len(summary["anomalies"])))
    if alerts:
        lines.append("Alerts:")
        lines.extend("  - " + a for a in alerts)
    else:
        lines.append("Alerts: none")
    return "\n".join(lines)


def main():
    sightings = [
        ("lion", "north", "healthy", "adult"),
        ("lion", "north", "injured", "cub"),
        ("zebra", "south", "healthy", "juvenile"),
        ("rhino", "east", "missing", "adult"),
        ("gazelle", "south", "unknown", "adult"),
        ("elephant", "west"),
    ]
    summary, alerts = track(sightings)
    print(format_report(summary, alerts, zone_status_counts(sightings)))


if __name__ == "__main__":
    main()

VALID_OUTCOMES = ("won", "tied", "lost", "disqualified")


def normalize(field):
    return str(field).strip().lower()


def evaluate(matches):
    won = []
    tied = []
    lost = []
    disqualified = []
    by_division = {}
    by_sport = {}
    complaints = []
    buckets = {
        "won": won,
        "tied": tied,
        "lost": lost,
        "disqualified": disqualified,
    }
    for number, match in enumerate(matches, start=1):
        record = tuple(match)
        if len(record) != 4:
            complaints.append("match %d: expected 4 fields, got %d" % (number, len(record)))
            continue
        school = normalize(record[0])
        division = normalize(record[1])
        outcome = normalize(record[2])
        sport = normalize(record[3])
        if not school:
            complaints.append("match %d: missing school name" % number)
            continue
        if outcome not in buckets:
            complaints.append("match %d: referee reported unknown outcome %r" % (number, outcome))
            continue
        buckets[outcome].append(school)
        if division not in by_division:
            by_division[division] = []
        by_division[division].append(school)
        if sport not in by_sport:
            by_sport[sport] = []
        by_sport[sport].append(school)
    summary = {}
    for outcome in VALID_OUTCOMES:
        summary[outcome] = buckets[outcome]
    summary.update(by_division)
    summary.update(by_sport)
    return summary, complaints


def standings(summary):
    points = {}
    for school in summary["won"]:
        points[school] = points.get(school, 0) + 3
    for school in summary["tied"]:
        points[school] = points.get(school, 0) + 1
    for school in summary["disqualified"]:
        points[school] = points.get(school, 0) - 1
    return points


def format_report(summary, complaints):
    lines = []
    for key in sorted(summary):
        lines.append("%-14s %s" % (key, ", ".join(summary[key]) or "-"))
    table = standings(summary)
    for school in sorted(table, key=lambda name: (-table[name], name)):
        lines.append("points %-7s %d" % (school, table[school]))
    for note in complaints:
        lines.append("complaint: " + note)
    return "\n".join(lines)


def main():
    matches = [
        ("tigers", "division one", "won", "basketball"),
        ("eagles", "division one", "lost", "basketball"),
        ("sharks", "division two", "tied", "soccer"),
        ("ravens", "division two", "tied", "soccer"),
        ("wolves", "division two", "disqualified", "swimming"),
        ("hawks", "division one", "forfeited", "soccer"),
        ("owls", "division three", "won"),
    ]
    summary, complaints = evaluate(matches)
    print(format_report(summary, complaints))


if __name__ == "__main__":
    main()

