SUPPLY_KITS = {
    "trauma": "trauma kit",
    "respiratory": "ventilator",
    "burn": "burn dressing pack",
}


def normalize(record):
    name, ward, severity, category = record
    return (
        name.strip().lower(),
        ward.strip().lower(),
        severity.strip().lower(),
        category.strip().lower(),
    )


def triage(patients):
    critical = []
    stable = []
    discharged = []
    unassigned = []
    by_ward = {}
    by_category = {}
    supply_requests = []

    for record in patients:
        name, ward, severity, category = normalize(record)

        if severity == "critical":
            critical.append(name)
        elif severity == "stable":
            stable.append(name)
        elif severity == "discharged":
            discharged.append(name)
        else:
            unassigned.append(name)

        if ward not in by_ward:
            by_ward[ward] = []
        by_ward[ward].append(name)

        if category not in by_category:
            by_category[category] = []
        by_category[category].append(name)

        if severity == "critical" and category in SUPPLY_KITS:
            supply_requests.append((ward, SUPPLY_KITS[category]))

    summary = {
        "critical": critical,
        "stable": stable,
        "discharged": discharged,
        "unassigned": unassigned,
        "wards": by_ward,
        "categories": by_category,
    }
    return summary, supply_requests


def ward_load(summary):
    loads = {}
    urgent = set(summary["critical"])
    for ward, names in summary["wards"].items():
        counts = {}
        counts["total"] = len(names)
        counts["critical"] = sum(1 for name in names if name in urgent)
        loads[ward] = counts
    return loads


def format_report(summary, supply_requests):
    lines = []
    for ward, counts in sorted(ward_load(summary).items()):
        lines.append(
            "{}: {} patients ({} critical)".format(
                ward, counts["total"], counts["critical"]
            )
        )
    if supply_requests:
        for ward, kit in supply_requests:
            lines.append("request: {} for {}".format(kit, ward))
    else:
        lines.append("request: none")
    return "\n".join(lines)


