def normalize(entry):
    """Return the four book fields, trimmed and lower-cased."""
    fields = []
    for value in entry:
        fields.append(str(value).strip().lower())
    return tuple(fields)


def organize(books):
    """Sort (title, genre, author, status) tuples into portfolios and shelves."""
    genres = {}
    authors = {}
    completed = []
    reading = []
    unread = []
    corrupted = []
    for entry in books:
        if not isinstance(entry, (tuple, list)) or len(entry) != 4:
            corrupted.append(entry)
            continue
        title, genre, author, status = normalize(entry)
        if not title or not author:
            corrupted.append(entry)
            continue
        if genre not in genres:
            genres[genre] = []
        genres[genre].append(title)
        if author not in authors:
            authors[author] = []
        authors[author].append(title)
        if status == "completed":
            completed.append(title)
        elif status in ("reading", "currently reading"):
            reading.append(title)
        else:
            unread.append(title)
    statuses = {}
    statuses["completed"] = completed
    statuses["reading"] = reading
    statuses["unread"] = unread
    metadata = {}
    metadata["titles"] = len(completed) + len(reading) + len(unread)
    metadata["genres"] = len(genres)
    metadata["authors"] = len(authors)
    metadata["corrupted"] = len(corrupted)
    print(format_summary(metadata))
