LATENCY_THRESHOLDS = {"excellent": 60, "moderate": 140}


def classify_latency(latency):
    if isinstance(latency, str):
        label = latency.lower().replace("connection", "").strip()
        if label in LATENCY_THRESHOLDS:
            return label
        return "poor"
    if latency <= LATENCY_THRESHOLDS["excellent"]:
        return "excellent"
    if latency <= LATENCY_THRESHOLDS["moderate"]:
        return "moderate"
    return "poor"


def form_squads(buckets, squad_size=2):
    squads = []
    isolated = []
    for key in buckets:
        members = buckets[key]
        for start in range(0, len(members), squad_size):
            chunk = members[start:start + squad_size]
            if len(chunk) == squad_size:
                squads.append(chunk)
            else:
                isolated.extend(chunk)
    while len(isolated) >= squad_size:
        squads.append(isolated[:squad_size])
        isolated = isolated[squad_size:]
    if isolated:
        squads.append(list(isolated))
    return squads, isolated


def match(players):
    regions = {}
    tiers = {}
    excellent = []
    moderate = []
    poor = []
    buckets = {}
    for username, region, tier, latency in players:
        if region not in regions:
            regions[region] = []
        regions[region].append(username)
        if tier not in tiers:
            tiers[tier] = []
        tiers[tier].append(username)
        quality = classify_latency(latency)
        if quality == "excellent":
            excellent.append(username)
        elif quality == "moderate":
            moderate.append(username)
        else:
            poor.append(username)
        key = (region, tier, quality)
        if key not in buckets:
            buckets[key] = []
        buckets[key].append(username)
    ordered = {}
    for key in sorted(buckets, key=lambda k: (-len(tiers[k[1]]), k)):
        ordered[key] = buckets[key]
    squads = form_squads(ordered)[0]
    return squads, regions


def format_report(squads, regions):
    lines = []
    for index, squad in enumerate(squads, start=1):
        lines.append("Squad %d: %s" % (index, ", ".join(squad)))
    for region in sorted(regions):
        lines.append("%s -> %s" % (region, ", ".join(regions[region])))
    return lines


