def classify(perishability):
    label = str(perishability).strip().lower()
    if label in ("highly perishable", "high", "perishable"):
        return "highly_perishable"
    if label in ("expired", "spoiled"):
        return "expired"
    return "stable"


def supply_gaps(by_supplier, required):
    missing = []
    reorder = {}
    for item, needed in required.items():
        supplied = 0
        for supplier, items in by_supplier.items():
            supplied += items.count(item)
        if supplied < needed:
            missing.append(item)
            reorder[item] = needed - supplied
    return missing, reorder


def distribute(shipments, required=None):
    by_warehouse = {}
    by_supplier = {}
    highly_perishable = []
    stable = []
    expired = []
    for item, warehouse, perishability, supplier in shipments:
        if warehouse not in by_warehouse:
            by_warehouse[warehouse] = []
        by_warehouse[warehouse].append(item)
        if supplier not in by_supplier:
            by_supplier[supplier] = []
        by_supplier[supplier].append(item)
        kind = classify(perishability)
        if kind == "highly_perishable":
            highly_perishable.append(item)
        elif kind == "expired":
            expired.append(item)
        else:
            stable.append(item)
    missing, _reorder = supply_gaps(by_supplier, required or {})
    return by_warehouse, missing


def report(shipments, required):
    by_warehouse, missing = distribute(shipments, required)
    by_supplier = {}
    for item, _warehouse, _perishability, supplier in shipments:
        if supplier not in by_supplier:
            by_supplier[supplier] = []
        by_supplier[supplier].append(item)
    _missing, reorder = supply_gaps(by_supplier, required)
    lines = []
    for warehouse in sorted(by_warehouse):
        lines.append("%s: %s" % (warehouse, ", ".join(sorted(by_warehouse[warehouse]))))
    for item in missing:
        lines.append("reorder %s x%d" % (item, reorder[item]))
    return "\n".join(lines)


def main():
    shipments = [
        ("apples", "north warehouse", "highly perishable", "local farms"),
        ("rice", "south warehouse", "stable", "grain co"),
        ("milk", "north warehouse", "highly perishable", "dairy plus"),
        ("lettuce", "east warehouse", "expired", "local farms"),
    ]
    print(distribute([shipments[0]]))
    print(distribute(shipments))
    print(report(shipments, {"apples": 3, "rice": 1, "bananas": 2}))


if __name__ == "__main__":
    main()

