BASE_VALUES = {
    "commercial": 300000.0,
    "residential": 200000.0,
    "industrial": 250000.0,
}
CONDITION_FACTORS = {
    "newly renovated": 1.2,
    "minor fixes": 1.0,
    "major overhaul": 0.7,
}
PREMIUM_THRESHOLD = 500000.0
TAX_RATE = 0.0125


def valuate(properties):
    """Compute market values, premium listings and tax liabilities."""
    values = {}
    premium_listings = []
    tax_liabilities = {}
    for address, city, condition, ptype in properties:
        base = BASE_VALUES.get(ptype, 150000.0)
        value = round(base * CONDITION_FACTORS.get(condition, 0.5), 2)
        values[address] = value
        tax_liabilities[address] = round(value * TAX_RATE, 2)
        if value >= PREMIUM_THRESHOLD:
            premium_listings.append(address)
    return values, premium_listings, tax_liabilities


def build_summary(type_clusters, renovated, minor, major, tax_liabilities):
    lines = []
    for ptype in sorted(type_clusters):
        lines.append("{}: {}".format(ptype, ", ".join(type_clusters[ptype])))
    lines.append("newly renovated: {}".format(len(renovated)))
    lines.append("minor fixes: {}".format(len(minor)))
    lines.append("major overhauls: {}".format(len(major)))
    total_tax = sum(tax_liabilities.values())
    lines.append("total tax liability: {:.2f}".format(total_tax))
    return lines


def assess(properties):
    """Cluster building assets and report their premium listings."""
    city_clusters = {}
    type_clusters = {}
    renovated = []
    minor_fixes = []
    major_overhauls = []
    cleaned = []
    for address, city, condition, ptype in properties:
        record = (address.strip(), city.strip().lower(),
                  condition.strip().lower(), ptype.strip().lower())
        cleaned.append(record)
        address, city, condition, ptype = record
        if city not in city_clusters:
            city_clusters[city] = []
        city_clusters[city].append(address)
        if ptype not in type_clusters:
            type_clusters[ptype] = []
        type_clusters[ptype].append(address)
        if condition == "newly renovated":
            renovated.append(address)
        elif condition == "minor fixes":
            minor_fixes.append(address)
        else:
            major_overhauls.append(address)
    _values, premium_listings, tax_liabilities = valuate(cleaned)
    for line in build_summary(type_clusters, renovated, minor_fixes,
                              major_overhauls, tax_liabilities):
        print(line)
    return city_clusters, premium_listings


if __name__ == "__main__":
    portfolio = [
        ("Main Street", "Springfield", "newly renovated", "commercial"),
        ("Elm Avenue", "Springfield", "major overhaul", "residential"),
        ("Harbor Road", "Shelbyville", "minor fixes", "industrial"),
    ]
    clusters, premium = assess(portfolio)
    print("clusters:", clusters)
    print("premium:", premium)
    print(assess([("Main Street", "Springfield", "newly renovated", "commercial")]))

def normalize(cargo):
    """Accept a single 4-tuple or an iterable of 4-tuples and return a list."""
    if isinstance(cargo, tuple) and cargo and isinstance(cargo[0], str):
        return [cargo]
    shipments = []
    for entry in cargo:
        if len(entry) != 4:
            raise ValueError("each shipment needs commodity, planet, legality, guild")
        shipments.append(tuple(entry))
    return shipments


def customs_check(contraband, restricted):
    """Seize illegal cargo and fine the guilds responsible for it."""
    seized_goods = []
    fined_merchants = {}
    for commodity, planet, legality, guild in contraband:
        seized_goods.append((commodity, planet))
        fined_merchants[guild] = fined_merchants.get(guild, 0) + 500
    for commodity, planet, legality, guild in restricted:
        if planet in ("mars", "earth"):
            seized_goods.append((commodity, planet))
            fined_merchants[guild] = fined_merchants.get(guild, 0) + 150
    return seized_goods, fined_merchants


def trade(cargo):
    """Sort shipments by destination and guild, then clear them through customs."""
    destination_cargo = {}
    guild_cargo = {}
    legal_goods = []
    contraband = []
    restricted_items = []
    for shipment in normalize(cargo):
        commodity, planet, legality, guild = shipment
        if planet not in destination_cargo:
            destination_cargo[planet] = []
        destination_cargo[planet].append(commodity)
        if guild not in guild_cargo:
            guild_cargo[guild] = []
        guild_cargo[guild].append(commodity)
        if legality == "legal":
            legal_goods.append(shipment)
        elif legality == "contraband":
            contraband.append(shipment)
        else:
            restricted_items.append(shipment)
    seized_goods, fined_merchants = customs_check(contraband, restricted_items)
    for commodity, planet in seized_goods:
        destination_cargo[planet].remove(commodity)
    print(manifest(destination_cargo, guild_cargo, len(legal_goods), fined_merchants))
    return destination_cargo, seized_goods


def manifest(destination_cargo, guild_cargo, legal_count, fined_merchants):
    """Build a human readable manifest of the completed sorting run."""
    lines = []
    for planet in sorted(destination_cargo):
        lines.append("%s -> %s" % (planet, ", ".join(destination_cargo[planet]) or "empty"))
    for guild in sorted(guild_cargo):
        lines.append("%s handled %d lot(s)" % (guild, len(guild_cargo[guild])))
    lines.append("cleared legal shipments: %d" % legal_count)
    for guild in sorted(fined_merchants):
        lines.append("%s fined %d credits" % (guild, fined_merchants[guild]))
    return "\n".join(lines)


def main():
    print(trade(("spices", "mars", "legal", "trade guild")))
    fleet = [
        ("spices", "mars", "legal", "trade guild"),
        ("blasters", "mars", "contraband", "shadow guild"),
        ("ore", "vega", "restricted", "miners guild"),
        ("silk", "earth", "legal", "trade guild"),
        ("serum", "earth", "restricted", "shadow guild"),
    ]
    print(trade(fleet))


if __name__ == "__main__":
    main()

