def _tier(capacity):
    """Map a crowd capacity (number) or an explicit tier label to a tier name."""
    if isinstance(capacity, str):
        label = capacity.strip().lower()
        if "headline" in label:
            return "headline"
        if "support" in label:
            return "supporting"
        return "local"
    if capacity >= 5000:
        return "headline"
    if capacity >= 1000:
        return "supporting"
    return "local"


def ticketing(bands, sell_out_ratio=0.85):
    """Estimate attendance per stage and collect sold out shows and VIP lists."""
    expected = {}
    sold_out = []
    vip_lists = {}
    for name, stage, _genre, capacity in bands:
        seats = capacity if isinstance(capacity, (int, float)) else 750
        attendance = int(seats * sell_out_ratio)
        expected[name] = attendance
        if attendance >= seats:
            sold_out.append(name)
        if _tier(capacity) == "headline":
            if stage not in vip_lists:
                vip_lists[stage] = []
            vip_lists[stage].append(name)
    return expected, sold_out, vip_lists


def schedule(bands):
    """Allocate bands to stages and genres, splitting them into billing tiers."""
    stage_allocations = {}
    genre_allocations = {}
    headline_acts = []
    supporting_acts = []
    local_openers = []
    tiers = {
        "headline": headline_acts,
        "supporting": supporting_acts,
        "local": local_openers,
    }
    for name, stage, genre, capacity in bands:
        if stage not in stage_allocations:
            stage_allocations[stage] = []
        stage_allocations[stage].append(name)
        if genre not in genre_allocations:
            genre_allocations[genre] = []
        genre_allocations[genre].append(name)
        tiers[_tier(capacity)].append(name)
    return stage_allocations, headline_acts


def report(bands):
    """Build printable lines describing the schedule and the ticketing outlook."""
    stage_allocations, headline_acts = schedule(bands)
    expected, sold_out, vip_lists = ticketing(bands)
    lines = []
    for stage in sorted(stage_allocations):
        acts = ", ".join(stage_allocations[stage])
        lines.append("{0}: {1}".format(stage, acts))
        guests = vip_lists.get(stage, [])
        if guests:
            lines.append("  VIP for: " + ", ".join(guests))
    for name in sorted(expected):
        lines.append("  {0} expects {1} fans".format(name, expected[name]))
    if headline_acts:
        lines.append("Headliners: " + ", ".join(headline_acts))
    if sold_out:
        lines.append("Sold out: " + ", ".join(sold_out))
    return lines


def main():
    lineup = [
        ("rock band", "main stage", "rock", "headline act"),
        ("jazz trio", "tent stage", "jazz", 1200),
        ("garage kids", "tent stage", "rock", 400),
        ("synth wave", "main stage", "electronic", 6000),
    ]
    for line in report(lineup):
        print(line)
    print(schedule([("rock band", "main stage", "rock", "headline act")]))


if __name__ == "__main__":
    main()

