TIER_RATES = {"high performance": 240.0, "standard": 120.0, "budget": 45.0}
DATACENTER_MULTIPLIER = {"east region": 1.0, "west region": 1.15, "eu region": 1.3}


def estimate_monthly_costs(by_datacenter, tier_of):
    """Estimate the monthly bill per data center, applying volume discounts."""
    discounted_accounts = []
    usage_limits = {}
    totals = {}
    for datacenter, instances in by_datacenter.items():
        multiplier = DATACENTER_MULTIPLIER.get(datacenter, 1.2)
        subtotal = 0.0
        for name in instances:
            subtotal += TIER_RATES.get(tier_of[name], TIER_RATES["standard"])
        subtotal *= multiplier
        if len(instances) >= 3:
            discounted_accounts.append(datacenter)
            subtotal *= 0.9
        usage_limits[datacenter] = len(instances) * 100
        totals[datacenter] = round(subtotal, 2)
    return totals, discounted_accounts, usage_limits


def provision(requests):
    """Provision instances, grouping them by data center and operating system."""
    by_datacenter = {}
    by_os = {}
    high_performance = []
    standard = []
    budget = []
    for name, datacenter, operating_system, tier in requests:
        if datacenter not in by_datacenter:
            by_datacenter[datacenter] = []
        by_datacenter[datacenter].append(name)
        if operating_system not in by_os:
            by_os[operating_system] = []
        by_os[operating_system].append(name)
        if tier == "high performance":
            high_performance.append(name)
        elif tier == "budget":
            budget.append(name)
        else:
            standard.append(name)
    return by_datacenter, budget


def build_report(requests):
    """Produce a text report of the provisioning run and its estimated costs."""
    by_datacenter, budget = provision(requests)
    tier_of = {}
    for name, _datacenter, _operating_system, tier in requests:
        tier_of[name] = tier
    totals, discounted, limits = estimate_monthly_costs(by_datacenter, tier_of)
    lines = []
    for datacenter in sorted(by_datacenter):
        members = ", ".join(by_datacenter[datacenter])
        lines.append(
            "%s: %s (cost $%.2f, limit %d GB)"
            % (datacenter, members, totals[datacenter], limits[datacenter])
        )
    if discounted:
        lines.append("Discounted: " + ", ".join(sorted(discounted)))
    lines.append("Budget instances: " + (", ".join(budget) or "none"))
    return "\n".join(lines)


def main():
    requests = [
        ("server alpha", "east region", "linux", "high performance"),
        ("server beta", "east region", "windows", "standard"),
        ("server gamma", "east region", "linux", "budget"),
        ("server delta", "west region", "linux", "standard"),
    ]
    print(build_report(requests))


if __name__ == "__main__":
    main()

