def validate(tickets):
    """Return a list of human-readable problems found in the raw admission tuples."""
    problems = []
    for index, record in enumerate(tickets):
        if len(record) != 4:
            problems.append("record %d: expected 4 fields, got %d" % (index, len(record)))
            continue
        name, title, showtime, category = record
        if not name or not title or not showtime:
            problems.append("record %d: empty name, title or showtime" % index)
        if category not in ("adult", "child", "senior"):
            problems.append("record %d: unknown category %r" % (index, category))
    return problems


def issue(tickets):
    """Aggregate admissions and hand back (showtime aggregations, child tickets)."""
    by_movie = {}
    by_showtime = {}
    adult_tickets = []
    child_tickets = []
    senior_tickets = []
    for name, title, showtime, category in tickets:
        if title not in by_movie:
            by_movie[title] = []
        by_movie[title].append(name)
        if showtime not in by_showtime:
            by_showtime[showtime] = []
        by_showtime[showtime].append(name)
        if category == "adult":
            adult_tickets.append((name, title))
        elif category == "child":
            child_tickets.append((name, title))
        elif category == "senior":
            senior_tickets.append((name, title))
    return by_showtime, child_tickets


def concessions(orders):
    """Split food orders into combo meals and per-customer beverage choices."""
    combo_meals = []
    beverages = {}
    for name, item in orders:
        if item.startswith("combo"):
            combo_meals.append((name, item))
        else:
            beverages[name] = item
    return combo_meals, beverages


def report(showtimes, child_tickets, combo_meals, beverages):
    lines = []
    for showtime in sorted(showtimes):
        lines.append("%s: %s" % (showtime, ", ".join(showtimes[showtime])))
    if child_tickets:
        names = [name for name, _title in child_tickets]
        lines.append("child admissions: " + ", ".join(names))
    else:
        lines.append("child admissions: none")
    lines.append("combo meals sold: %d" % len(combo_meals))
    for name in sorted(beverages):
        lines.append("drink for %s: %s" % (name, beverages[name]))
    return "\n".join(lines)


def main():
    tickets = [
        ("alice", "star wars", "evening", "adult"),
        ("bob", "star wars", "evening", "child"),
        ("carol", "dune", "matinee", "senior"),
    ]
    orders = [("alice", "combo large"), ("bob", "lemonade"), ("carol", "coffee")]
    problems = validate(tickets)
    if problems:
        for problem in problems:
            print("rejected " + problem)
        return
    showtimes, child_tickets = issue(tickets)
    combo_meals, beverages = concessions(orders)
    print(report(showtimes, child_tickets, combo_meals, beverages))


if __name__ == "__main__":
    main()

