TRIGGER_LABELS = [
    "extreme danger",
    "high danger",
    "moderate danger",
    "low danger",
    "unrated",
    "restricted access",
    "controlled blasting",
    "patrol dispatched",
]


def validate(reports):
    accepted = []
    rejected = []
    for report in reports:
        if len(report) != 4:
            rejected.append(report)
            continue
        region, depth, angle, code = report
        if not isinstance(code, int) or code < 0 or code > 7:
            rejected.append(report)
            continue
        accepted.append((region, depth, angle, code))
    return accepted, rejected


def assess(reports):
    extreme = []
    high = []
    moderate = []
    low = []
    unrated = []
    restricted = []
    blasting = []
    patrol = []
    peaks = {}
    buckets = [extreme, high, moderate, low, unrated, restricted, blasting, patrol]
    for report in reports:
        region, depth, angle, code = report
        buckets[code].append(report)
        if region not in peaks or depth > peaks[region]:
            peaks[region] = depth
    return (extreme, high, moderate, low, unrated, restricted, blasting, patrol, peaks)


def count_by_label(buckets):
    counts = {}
    for label, bucket in zip(TRIGGER_LABELS, buckets):
        counts[label] = len(bucket)
    return counts


def average_slopes(reports):
    angles = {}
    for region, _depth, angle, _code in reports:
        angles.setdefault(region, [])
        angles[region].append(angle)
    means = {}
    for region, values in angles.items():
        means[region] = round(sum(values) / len(values), 1)
    return means


def format_summary(counts, peaks, means):
    lines = []
    for label in TRIGGER_LABELS:
        lines.append("{:<20} {}".format(label, counts[label]))
    for region in sorted(peaks):
        lines.append("region {}: peak depth {} cm, mean slope {} deg".format(
            region, peaks[region], means[region]))
    return "\n".join(lines)


def main():
    raw = [(5, 120, 40, 0), (6, 40, 20, 3), (5, 95, 38, 6),
           (7, 60, 31, 9), (6, 75, 25, 1), (7, 60, 31)]
    accepted, rejected = validate(raw)
    result = assess(accepted)
    buckets, peaks = result[:8], result[8]
    print(result)
    print(format_summary(count_by_label(buckets), peaks, average_slopes(accepted)))
    for report in rejected:
        print("discarded malformed report:", report)


if __name__ == "__main__":
    main()

