def validate(measurements):
    """Return the readings that have the expected shape, plus a list of problems."""
    clean = []
    problems = []
    for index, reading in enumerate(measurements):
        if len(reading) != 4:
            problems.append("reading %d: expected 4 fields" % index)
            continue
        status = reading[3]
        if not isinstance(status, int) or not 0 <= status <= 7:
            problems.append("reading %d: bad status %r" % (index, status))
            continue
        clean.append(tuple(reading))
    return clean, problems


def model(measurements):
    optimal = []
    overheating = []
    pressure_drop = []
    scaling = []
    cold_influx = []
    venting = []
    maintenance = []
    sensor_failure = []
    max_temp = {}
    buckets = (
        optimal, overheating, pressure_drop, scaling,
        cold_influx, venting, maintenance, sensor_failure,
    )
    for well_id, temperature, pressure, status in measurements:
        buckets[status].append((well_id, temperature, pressure, status))
        if well_id not in max_temp or temperature > max_temp[well_id]:
            max_temp[well_id] = temperature
    return (optimal, overheating, pressure_drop, scaling,
            cold_influx, venting, maintenance, sensor_failure, max_temp)


def summarize(result):
    """Turn the model output into a status -> count mapping."""
    counts = {}
    for name, bucket in zip(STATUS_NAMES, result[:8]):
        counts[name] = len(bucket)
    return counts


def format_report(result, problems):
    lines = []
    for name, count in summarize(result).items():
        lines.append("%-20s %d" % (name, count))
    for well_id in sorted(result[8]):
        lines.append("well %s peak temperature %s" % (well_id, result[8][well_id]))
    for problem in problems:
        lines.append("rejected -> " + problem)
    return "\n".join(lines)


def main():
    raw = [
        (4, 250, 100, 0),
        (5, 120, 50, 4),
        (4, 310, 95, 1),
        (6, 180, 20, 2),
        (5, 90, 40, 9),
    ]
    readings, problems = validate(raw)
    result = model(readings)
    print(format_report(result, problems))


if __name__ == "__main__":
    main()

STATUS_NAMES = (
    "podium finishers",
    "qualifiers",
    "time limit expired",
    "disqualified",
    "retired early",
    "protested",
    "equipment failure",
    "unresolved",
)


def validate(logs):
    """Return a list of human readable problems found in the raw log entries."""
    errors = []
    for position, entry in enumerate(logs):
        if len(entry) != 4:
            errors.append("entry %d must hold exactly four values" % position)
            continue
        boat_id, elapsed, penalty, flag = entry
        if elapsed < 0 or penalty < 0:
            errors.append("boat %s has a negative time component" % boat_id)
        if not 0 <= flag <= 7:
            errors.append("boat %s has status flag %s outside 0..7" % (boat_id, flag))
    return errors


def score(logs):
    podium = []
    qualifiers = []
    expired = []
    disqualified = []
    retired = []
    protested = []
    equipment = []
    unresolved = []
    final_times = {}
    buckets = [podium, qualifiers, expired, disqualified,
               retired, protested, equipment, unresolved]
    for boat_id, elapsed, penalty, flag in logs:
        buckets[flag].append((boat_id, elapsed, penalty, flag))
        final_times[boat_id] = elapsed + penalty
    return (podium, qualifiers, expired, disqualified,
            retired, protested, equipment, unresolved, final_times)


def group_by_status(result):
    """Map each non-empty status name to the boats classified under it."""
    grouped = {}
    for name, bucket in zip(STATUS_NAMES, result[:8]):
        if bucket:
            grouped[name] = bucket
    return grouped


def format_report(result):
    lines = []
    grouped = group_by_status(result)
    for name in STATUS_NAMES:
        bucket = grouped.get(name)
        if bucket:
            ids = ", ".join(str(boat[0]) for boat in bucket)
            lines.append("%-20s %d boat(s): %s" % (name, len(bucket), ids))
    lines.append("--- corrected times ---")
    for boat_id, total in sorted(result[8].items(), key=lambda item: item[1]):
        lines.append("boat %s finished on %s minutes" % (boat_id, total))
    return "\n".join(lines)


def main():
    logs = [(12, 300, 10, 0), (14, 400, 0, 3), (7, 355, 5, 1),
            (9, 512, 0, 6), (21, 298, 12, 0), (3, 480, 30, 5)]
    problems = validate(logs)
    if problems:
        for message in problems:
            print("invalid log:", message)
        return
    result = score(logs)
    print(format_report(result))


if __name__ == "__main__":
    main()

ALERT_LABELS = (
    "immediate helicopter dispatch",
    "ground team deploy",
    "standby",
    "false alarm",
    "lost contact",
    "low battery warning",
    "out of bounds",
    "resolved",
)


def validate_signals(signals):
    problems = []
    for position, signal in enumerate(signals):
        if not isinstance(signal, tuple) or len(signal) != 4:
            problems.append("record %d is not a 4-tuple" % position)
            continue
        alert = signal[3]
        if not isinstance(alert, int) or not 0 <= alert <= 7:
            problems.append("record %d has invalid alert %r" % (position, alert))
    return problems


def coordinate(signals):
    problems = validate_signals(signals)
    if problems:
        raise ValueError("; ".join(problems))
    helicopter = []
    ground_team = []
    standby = []
    false_alarm = []
    lost_contact = []
    low_battery = []
    out_of_bounds = []
    resolved = []
    altitudes = {}
    buckets = (
        helicopter, ground_team, standby, false_alarm,
        lost_contact, low_battery, out_of_bounds, resolved,
    )
    for signal in signals:
        signal_id, altitude, _battery, alert = signal
        buckets[alert].append(signal)
        altitudes[signal_id] = altitude
    return buckets + (altitudes,)


def summarize(buckets):
    counts = {}
    for label, bucket in zip(ALERT_LABELS, buckets):
        counts[label] = len(bucket)
    return counts


def battery_watch(low_battery, lost_contact):
    watch = {}
    for signal_id, _altitude, battery, _alert in list(low_battery) + list(lost_contact):
        watch[signal_id] = battery
    return watch


def format_report(buckets, altitudes):
    lines = []
    counts = summarize(buckets)
    for label in ALERT_LABELS:
        lines.append("%-30s %d" % (label, counts[label]))
    watch = battery_watch(buckets[5], buckets[4])
    for signal_id in sorted(watch):
        lines.append(
            "recharge beacon %d at altitude %d (battery %d%%)"
            % (signal_id, altitudes[signal_id], watch[signal_id])
        )
    highest = max(altitudes, key=lambda key: altitudes[key])
    lines.append("highest beacon: %d at %d" % (highest, altitudes[highest]))
    return lines


def main():
    feed = [(9, 2500, 100, 0), (10, 3000, 10, 5), (11, 900, 55, 2), (12, 4100, 5, 4)]
    result = coordinate(feed)
    print(result)
    for line in format_report(result[:8], result[8]):
        print(line)


if __name__ == "__main__":
    main()

