    for index, record in enumerate(vehicles):
        if len(record) != 4:
            problems.append("record %d must hold exactly 4 fields" % index)
            continue
        vehicle_id, charge, capacity, queue = record
        if not isinstance(queue, int) or not 0 <= queue <= 7:
            problems.append("vehicle %r has invalid queue %r" % (vehicle_id, queue))
        if charge > capacity:
            problems.append("vehicle %r charged above capacity" % (vehicle_id,))
