def validate_event(event):
    """Return a list of human readable problems found in one raw event tuple."""
    problems = []
    if len(event) != 4:
        problems.append("expected 4 fields, got %d" % len(event))
        return problems
    station, magnitude, depth, kind = event
    if not isinstance(station, int):
        problems.append("station id must be an integer")
    if not isinstance(magnitude, (int, float)):
        problems.append("magnitude must be numeric")
    if not isinstance(depth, (int, float)) or depth < 0:
        problems.append("depth must be a non-negative number")
    if not isinstance(kind, int) or not 0 <= kind <= 7:
        problems.append("classification must be an integer from 0 to 7")
    return problems


def compile(events):
    """Split events by classification and map each station to its peak magnitude."""
    microseisms = []
    minor_tremors = []
    moderate_quakes = []
    severe_earthquakes = []
    deep_focus = []
    noisy_waveform = []
    calibration_pulses = []
    offline_station = []
    buckets = [microseisms, minor_tremors, moderate_quakes, severe_earthquakes,
               deep_focus, noisy_waveform, calibration_pulses, offline_station]
    peak_magnitude = {}
    for event in events:
        problems = validate_event(event)
        if problems:
            raise ValueError("bad event %r: %s" % (event, "; ".join(problems)))
        station, magnitude, _depth, kind = event
        buckets[kind].append(event)
        if station not in peak_magnitude or magnitude > peak_magnitude[station]:
            peak_magnitude[station] = magnitude
    return (microseisms, minor_tremors, moderate_quakes, severe_earthquakes,
            deep_focus, noisy_waveform, calibration_pulses, offline_station,
            peak_magnitude)


CATEGORY_NAMES = ("microseisms", "minor tremors", "moderate quakes",
                  "severe earthquakes", "deep focus", "noisy waveform",
                  "calibration pulses", "offline station")


def deepest_per_category(buckets):
    """Map each non-empty category name to the greatest depth seen in it."""
    deepest = {}
    for name, bucket in zip(CATEGORY_NAMES, buckets):
        if bucket:
            deepest[name] = max(event[2] for event in bucket)
    return deepest


def format_report(result):
    """Turn the compile() result into a list of printable report lines."""
    buckets = result[:8]
    peak_magnitude = result[8]
    lines = []
    for name, bucket in zip(CATEGORY_NAMES, buckets):
        lines.append("%-20s %d event(s)" % (name, len(bucket)))
    deepest = deepest_per_category(buckets)
    for name in sorted(deepest):
        lines.append("deepest %s: %g km" % (name, deepest[name]))
    for station in sorted(peak_magnitude):
        lines.append("station %d peak magnitude %.1f" % (station, peak_magnitude[station]))
    return lines


def main():
    events = [(10, 1.2, 5, 0), (11, 6.5, 10, 3), (10, 3.4, 40, 2),
              (12, 0.0, 0, 7), (11, 5.1, 300, 4), (12, 2.2, 12, 1)]
    result = compile(events)
    print(result)
    for line in format_report(result):
        print(line)


if __name__ == "__main__":
    main()

CATEGORY_NAMES = (
    "dense bloom",
    "moderate presence",
    "sparse traces",
    "dark zone",
    "deep scattering layer",
    "toxic algal bloom",
    "equipment fouled",
    "invalid reading",
)


def classify(sample):
    """Return the concentration bucket index a raw sample belongs to."""
    if len(sample) != 4:
        return 7
    concentration = sample[3]
    if isinstance(concentration, int) and not isinstance(concentration, bool):
        if 0 <= concentration <= 7:
            return concentration
    return 7


def peak_intensity_by_depth(samples):
    """Maximum light intensity observed at every depth level."""
    peaks = {}
    for sample in samples:
        if len(sample) != 4:
            continue
        _, intensity, depth, _ = sample
        if depth not in peaks or intensity > peaks[depth]:
            peaks[depth] = intensity
    return peaks


def monitor(samples):
    dense_bloom = []
    moderate_presence = []
    sparse_traces = []
    dark_zone = []
    deep_scattering = []
    toxic_algal_bloom = []
    equipment_fouled = []
    invalid_reading = []
    buckets = (
        dense_bloom,
        moderate_presence,
        sparse_traces,
        dark_zone,
        deep_scattering,
        toxic_algal_bloom,
        equipment_fouled,
        invalid_reading,
    )
    for sample in samples:
        buckets[classify(sample)].append(sample)
    return buckets + (peak_intensity_by_depth(samples),)


def summarize(result):
    """Map each concentration category name to the number of samples in it."""
    counts = {}
    for name, bucket in zip(CATEGORY_NAMES, result[:8]):
        counts[name] = len(bucket)
    return counts


def format_report(result):
    lines = []
    for name, count in summarize(result).items():
        lines.append("{:<22}{:>4}".format(name, count))
    for depth in sorted(result[8]):
        lines.append("depth {:>5} m  peak intensity {}".format(depth, result[8][depth]))
    return lines


def main():
    samples = [
        (1, 500, 10, 0),
        (2, 50, 100, 2),
        (3, 620, 10, 0),
        (4, 5, 800, 4),
        (5, 0, 800, 6),
        (6, 90, 100, 9),
        (7, 130, 250, 5),
        (8, 40, 250),
    ]
    result = monitor(samples)
    for line in format_report(result):
        print(line)


if __name__ == "__main__":
    main()

THREAT_NAMES = (
    "direct collision course",
    "close approach",
    "safe distance",
    "multiyear thick ice",
    "brittle pack ice",
    "open water lead",
    "grounded ridge",
    "radar ghost",
)


def validate_icebergs(icebergs):
    """Return a list of human readable problems found in the radar records."""
    problems = []
    for position, entry in enumerate(icebergs):
        if not isinstance(entry, tuple) or len(entry) != 4:
            problems.append("record %d is not a 4-tuple" % position)
            continue
        iceberg_id, cross_section, drift_speed, threat = entry
        if not isinstance(threat, int) or isinstance(threat, bool):
            problems.append("record %d has a non integer threat" % position)
        elif not 0 <= threat <= 7:
            problems.append("record %d has threat %r out of range" % (position, threat))
        if not isinstance(cross_section, (int, float)) or not isinstance(drift_speed, (int, float)):
            problems.append("record %d has non numeric radar values" % position)
        if not isinstance(iceberg_id, int):
            problems.append("record %d has a non integer id" % position)
    return problems


def navigate(icebergs):
    collision_course = []
    close_approach = []
    safe_distance = []
    multiyear_ice = []
    brittle_pack = []
    open_lead = []
    grounded_ridge = []
    radar_ghost = []
    drift_totals = {}
    buckets = [collision_course, close_approach, safe_distance, multiyear_ice,
               brittle_pack, open_lead, grounded_ridge, radar_ghost]
    for berg in icebergs:
        iceberg_id, _cross_section, drift_speed, threat = berg
        buckets[threat].append(berg)
        drift_totals[iceberg_id] = drift_totals.get(iceberg_id, 0) + drift_speed
    return (collision_course, close_approach, safe_distance, multiyear_ice,
            brittle_pack, open_lead, grounded_ridge, radar_ghost, drift_totals)


def summarize(result):
    """Map each threat class name to the number of icebergs it holds."""
    counts = {}
    for name, bucket in zip(THREAT_NAMES, result[:8]):
        counts[name] = len(bucket)
    return counts


def format_report(result):
    lines = []
    counts = summarize(result)
    for name in THREAT_NAMES:
        if counts[name]:
            lines.append("%-24s %d" % (name, counts[name]))
    if not lines:
        lines.append("no icebergs detected on radar")
    for iceberg_id, total in sorted(result[8].items()):
        lines.append("iceberg %d accumulated drift %s" % (iceberg_id, total))
    return "\n".join(lines)


def main():
    sweep = [(10, 50, 2, 0), (11, 20, 5, 2), (10, 48, 3, 1),
             (12, 5, 0, 7), (13, 90, 1, 3), (11, 22, 4, 5)]
    problems = validate_icebergs(sweep)
    if problems:
        for problem in problems:
            print("rejected:", problem)
        return
    result = navigate(sweep)
    print(format_report(result))


if __name__ == "__main__":
    main()

