        anaerobic,
        high_biomass,
        pristine_sterile,
        subglacial_river_fed,
        isolated_pocket,
    )
    for lake in lakes:
        lake_id, _pressure, oxygen, environment = lake
        buckets[environment].append(tuple(lake))
        if lake_id not in max_oxygen or oxygen > max_oxygen[lake_id]:
            max_oxygen[lake_id] = oxygen
    return (*buckets, max_oxygen)


