    for name, members in zip(CATEGORY_NAMES, categories):
        summary[name] = len(members)
    return summary


def pressure_bands(lakes, width=100):
    bands = {}
    for lake_id, pressure, _oxygen, _environment in lakes:
        key = (pressure // width) * width
        bands.setdefault(key, []).append(lake_id)
    return bands


