def normalize(text):
    """Return only the lowercased alphanumeric characters of *text*."""
    kept = []
    for char in text:
        if char.isalnum():
            kept.append(char.lower())
    return "".join(kept)


def is_palindrome(text):
    """True if *text* reads the same both ways, ignoring case and punctuation."""
    cleaned = normalize(text)
    return cleaned == cleaned[::-1]


def palindromic_words(text):
    """List the individual words of *text* that are palindromes on their own."""
    found = []
    for word in text.split():
        stripped = normalize(word)
        if len(stripped) > 1 and is_palindrome(stripped):
            found.append(word)
    return found


def classify(phrases):
    """Split *phrases* into palindromes and non-palindromes."""
    groups = {}
    groups["palindrome"] = []
    groups["not palindrome"] = []
    for phrase in phrases:
        key = "palindrome" if is_palindrome(phrase) else "not palindrome"
        groups[key].append(phrase)
    return groups


def letter_counts(text):
    """Count how often each significant letter or digit occurs in *text*."""
    counts = {}
    for char in normalize(text):
        counts[char] = counts.get(char, 0) + 1
    return counts


def odd_count_letters(text):
    """Characters appearing an odd number of times (at most one in a palindrome)."""
    odd = []
    for char, total in sorted(letter_counts(text).items()):
        if total % 2:
            odd.append(char)
    return odd


def report(phrases):
    """Build printable lines describing each phrase in *phrases*."""
    lines = []
    groups = classify(phrases)
    for label in ("palindrome", "not palindrome"):
        lines.append("{0} ({1}):".format(label.upper(), len(groups[label])))
        for phrase in groups[label]:
            details = []
            words = palindromic_words(phrase)
            if words:
                details.append("inner palindromes: " + ", ".join(words))
            odd = odd_count_letters(phrase)
            if odd:
                details.append("odd counts: " + "".join(odd))
            suffix = " [" + "; ".join(details) + "]" if details else ""
            lines.append("  {0!r}{1}".format(phrase, suffix))
    return lines


