def remove_duplicates(items):
    """Return a new list without duplicates, keeping first-occurrence order."""
    seen = {}
    unhashable = []
    result = []
    for item in items:
        try:
            if item in seen:
                continue
            seen[item] = True
        except TypeError:
            if item in unhashable:
                continue
            unhashable.append(item)
        result.append(item)
    return result


def count_occurrences(items):
    """Map each hashable value to the number of times it appears."""
    counts = {}
    for item in items:
        key = repr(item) if isinstance(item, (list, dict, set)) else item
        counts[key] = counts.get(key, 0) + 1
    return counts


def duplicate_positions(items):
    """Map every repeated value to the list of indexes where it occurs."""
    positions = {}
    for index, item in enumerate(items):
        key = repr(item) if isinstance(item, (list, dict, set)) else item
        positions.setdefault(key, []).append(index)
    repeated = {}
    for key, indexes in positions.items():
        if len(indexes) > 1:
            repeated[key] = indexes
    return repeated


def format_report(items):
    """Build printable lines describing the de-duplication of `items`."""
    cleaned = remove_duplicates(items)
    counts = count_occurrences(items)
    repeated = duplicate_positions(items)
    lines = []
    lines.append("input    : %r" % (items,))
    lines.append("cleaned  : %r" % (cleaned,))
    lines.append("removed  : %d element(s)" % (len(items) - len(cleaned)))
    for key in sorted(repeated, key=lambda k: repeated[k][0]):
        lines.append(
            "  %r appears %d times at %r" % (key, counts[key], repeated[key])
        )
    return lines


