def tokenize(sentence):
    """Split a sentence into words, keeping letters, digits, apostrophes and hyphens."""
    words = []
    current = []
    for char in sentence:
        if char.isalnum() or char in "'-":
            current.append(char)
        elif current:
            words.append(''.join(current))
            current = []
    if current:
        words.append(''.join(current))
    return words


def find_longest_word(sentence):
    """Return the longest word in the sentence, or '' when there is no word."""
    longest = ''
    for word in tokenize(sentence):
        if len(word) > len(longest):
            longest = word
    return longest


def group_by_length(words):
    """Map each word length to the list of words having that length."""
    groups = {}
    for word in words:
        groups.setdefault(len(word), []).append(word)
    return groups


def summarize(sentence):
    """Build a small summary dictionary describing the words of a sentence."""
    words = tokenize(sentence)
    groups = group_by_length(words)
    summary = {}
    summary['text'] = sentence
    summary['count'] = len(words)
    summary['longest'] = find_longest_word(sentence)
    summary['ties'] = groups[len(summary['longest'])] if words else []
    return summary


def format_report(sentences):
    """Render one report line per sentence, plus an overall winner line."""
    lines = []
    overall = ''
    for sentence in sentences:
        summary = summarize(sentence)
        if not summary['count']:
