def merge_dictionaries(dict1, dict2):
    """Return a new dict with all pairs from both; dict2 wins on conflicts."""
    merged = {}
    for key, value in dict1.items():
        merged[key] = value
    for key, value in dict2.items():
        merged[key] = value
    return merged


def merge_many(dicts):
    """Fold a sequence of dictionaries left to right, later ones winning."""
    result = {}
    for mapping in dicts:
        result = merge_dictionaries(result, mapping)
    return result


def find_conflicts(dict1, dict2):
    """Map every shared key to the pair of values that disagree."""
    conflicts = {}
    for key in dict1:
        if key in dict2 and dict1[key] != dict2[key]:
            conflicts[key] = (dict1[key], dict2[key])
    return conflicts


def group_by_origin(dict1, dict2):
    """Split the merged key set into keys only in dict1, only in dict2, both."""
    only_first = []
    only_second = []
    shared = []
    for key in merge_dictionaries(dict1, dict2):
        if key not in dict2:
            only_first.append(key)
        elif key not in dict1:
            only_second.append(key)
        else:
            shared.append(key)
    return {'only_first': only_first, 'only_second': only_second,
            'shared': shared}


def describe_merge(dict1, dict2):
    """Build human readable lines summarising what a merge would do."""
    lines = []
    merged = merge_dictionaries(dict1, dict2)
    lines.append('merged size: %d' % len(merged))
    groups = group_by_origin(dict1, dict2)
    for name in ('only_first', 'only_second', 'shared'):
        keys = sorted(groups[name])
        lines.append('%s: %s' % (name, ', '.join(keys) if keys else '-'))
    overrides = []
    for key, (old, new) in sorted(find_conflicts(dict1, dict2).items()):
        overrides.append('%s %r -> %r' % (key, old, new))
    if overrides:
        lines.append('overridden: ' + '; '.join(overrides))
    return lines


def main():
    first = {'a': 1, 'b': 2}
    second = {'b': 3, 'c': 4}
    print(merge_dictionaries(first, second))
    for line in describe_merge(first, second):
        print(line)

    defaults = {'host': 'localhost', 'port': 80, 'debug': False}
    profile = {'port': 8080}
    overrides = {'debug': True, 'user': 'ana'}
    config = merge_many([defaults, profile, overrides])
    for key in sorted(config):
        print('%s = %r' % (key, config[key]))


if __name__ == '__main__':
    main()

