    values.append(current)
    return values


def parse_csv_text(text):
    """Parse a multi-line CSV document into a list of value lists."""
    rows = list()
    for line in text.splitlines():
        if not line.strip():
            continue
        rows.append(parse_csv_line(line))
    return rows


def build_records(rows):
    """Turn [header, *data_rows] into a list of dictionaries."""
    if not rows:
        return list()
    header = rows[0]
    records = list()
    for row in rows[1:]:
        record = dict()
        for index, name in enumerate(header):
            record[name] = row[index] if index < len(row) else ""
        records.append(record)
    return records


def detect_numeric_columns(records, header):
    """Return the header names whose values all look like numbers."""
    numeric = list()
    for name in header:
        column = [record[name] for record in records]
        if column and all(_is_number(value) for value in column):
            numeric.append(name)
    return numeric


def _is_number(value):
    try:
        float(value)
    except ValueError:
        return False
    return True


def column_sums(records, names):
    """Sum the given columns across all records."""
    totals = dict()
    for name in names:
