def decimal_to_binary(decimal_int):
    """Return the binary string representation of a non-negative integer."""
    if isinstance(decimal_int, bool) or not isinstance(decimal_int, int):
        raise TypeError("decimal_to_binary expects an int, got %r" % (decimal_int,))
    if decimal_int < 0:
        raise ValueError("decimal_to_binary expects a non-negative int")
    if decimal_int == 0:
        return "0"
    digits = []
    remaining = decimal_int
    while remaining > 0:
        digits.append(str(remaining % 2))
        remaining //= 2
    digits.reverse()
    return "".join(digits)


def parse_inputs(text):
    """Split whitespace-separated text into accepted ints and rejected tokens."""
    numbers = []
    rejected = []
    for token in text.split():
        try:
            value = int(token)
        except ValueError:
            rejected.append(token)
            continue
        if value < 0:
            rejected.append(token)
        else:
            numbers.append(value)
    return numbers, rejected


def convert_all(numbers):
    """Convert many integers, caching results so repeats cost nothing."""
    cache = {}
    conversions = []
    for value in numbers:
        if value not in cache:
            cache[value] = decimal_to_binary(value)
        conversions.append((value, cache[value]))
    return conversions


def group_by_width(conversions):
    """Map each bit-length to the decimal values that need that many bits."""
    groups = {}
    for value, bits in conversions:
        groups.setdefault(len(bits), []).append(value)
    return groups


def format_report(conversions, rejected):
    lines = []
    width = max((len(bits) for _, bits in conversions), default=1)
    for value, bits in conversions:
        lines.append("%6d -> %s" % (value, bits.rjust(width)))
    for length in sorted(group_by_width(conversions)):
        members = group_by_width(conversions)[length]
        lines.append("%d bit(s): %s" % (length, ", ".join(str(m) for m in members)))
    if rejected:
        lines.append("skipped: " + ", ".join(rejected))
    return "\n".join(lines)


def main():
    sample = "0 1 2 5 11 11 64 255 1023 -3 twelve"
    numbers, rejected = parse_inputs(sample)
    conversions = convert_all(numbers)
    print(format_report(conversions, rejected))


if __name__ == "__main__":
