STATUS_TEXT = {
    200: 'OK',
    404: 'Not Found',
    500: 'Internal Server Error',
}


def check_http_status(status_code):
    """Return a descriptive string for common HTTP status codes."""
    return STATUS_TEXT.get(status_code, 'Unknown Status')


def parse_status_codes(lines):
    """Extract the integer status code from each 'METHOD PATH CODE' line."""
    codes = []
    for line in lines:
        parts = line.split()
        if len(parts) < 3:
            continue
        try:
            codes.append(int(parts[-1]))
        except ValueError:
            continue
    return codes


def tally_statuses(codes):
    """Count how often each status code occurs."""
    counts = {}
    for code in codes:
        counts[code] = counts.get(code, 0) + 1
    return counts


def group_by_description(counts):
    """Map each description to the list of codes that produced it."""
    groups = {}
    for code in sorted(counts):
        description = check_http_status(code)
        if description not in groups:
            groups[description] = []
        groups[description].append(code)
    return groups


def format_report(counts):
    """Build printable report lines from a code -> occurrences mapping."""
    report = []
    total = sum(counts.values())
    for description, codes in sorted(group_by_description(counts).items()):
        hits = sum(counts[code] for code in codes)
        shown = ', '.join(str(code) for code in codes)
        report.append('%-22s %s (%d of %d)' % (description, shown, hits, total))
    return report


def main():
    log = [
        'GET /index.html 200',
        'GET /missing 404',
        'POST /api/orders 500',
        'GET /style.css 200',
        'GET /secret 401',
        'HEAD /',
        'GET /report 2x0',
    ]
    codes = parse_status_codes(log)
    counts = tally_statuses(codes)
    for line in format_report(counts):
        print(line)

    unknown = {}
    for code in counts:
        if check_http_status(code) == 'Unknown Status':
            unknown[code] = counts[code]
    if unknown:
        print('Needs a description: ' + ', '.join(str(c) for c in sorted(unknown)))


if __name__ == '__main__':
    main()

