def count_uppercase(text):
    """Return the number of uppercase letters in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    count = 0
    for char in text:
        if char.isupper():
            count += 1
    return count


def uppercase_letters(text):
    """Return the uppercase letters of text in order of appearance."""
    letters = []
    for char in text:
        if char.isupper():
            letters.append(char)
    return letters


def letter_frequency(text):
    """Map each uppercase letter in text to how often it occurs."""
    frequency = {}
    for char in uppercase_letters(text):
        frequency[char] = frequency.get(char, 0) + 1
    return frequency


def counts_per_word(text):
    """Map each word of text to its number of uppercase letters."""
    per_word = {}
    for word in text.split():
        per_word[word] = count_uppercase(word)
    return per_word


def format_frequency(frequency):
    """Render a letter frequency mapping as 'A x2, B x1'."""
    parts = []
    for letter in sorted(frequency):
        parts.append("%s x%d" % (letter, frequency[letter]))
    return ", ".join(parts) if parts else "none"


def report(texts):
    """Build a human readable report for a sequence of strings."""
    lines = []
    for text in texts:
        total = count_uppercase(text)
        lines.append("%r -> %d uppercase" % (text, total))
        lines.append("    letters: " + format_frequency(letter_frequency(text)))
        loud_words = []
        for word, count in counts_per_word(text).items():
            if count:
                loud_words.append(word)
        lines.append("    words with uppercase: " + (" ".join(loud_words) or "none"))
    return lines


