def filter_odd(numbers):
    """Return a new list containing only the odd numbers from `numbers`."""
    odd_numbers = []
    for value in numbers:
        if value % 2 != 0:
            odd_numbers.append(value)
    return odd_numbers


def parse_numbers(text):
    """Parse a whitespace/comma separated string into a list of integers."""
    cleaned = text.replace(",", " ")
    numbers = []
    for token in cleaned.split():
        numbers.append(int(token))
    return numbers


def group_by_parity(numbers):
    """Split numbers into a mapping {'odd': [...], 'even': [...]}."""
    groups = {}
    groups["odd"] = filter_odd(numbers)
    evens = []
    for value in numbers:
        if value % 2 == 0:
            evens.append(value)
    groups["even"] = evens
    return groups


def count_occurrences(numbers):
    """Count how many times each number appears."""
    counts = {}
    for value in numbers:
        counts[value] = counts.get(value, 0) + 1
    return counts


def summarize(numbers):
    """Build a small report about the odd numbers in `numbers`."""
    odd_numbers = filter_odd(numbers)
    report = {}
    report["input_size"] = len(numbers)
    report["odd"] = odd_numbers
    report["odd_count"] = len(odd_numbers)
    report["odd_sum"] = sum(odd_numbers)
    report["repeated_odd"] = sorted(
        value for value, n in count_occurrences(odd_numbers).items() if n > 1
    )
    return report


def format_report(report):
    """Render a report dictionary as a list of printable lines."""
    lines = []
    lines.append("input size : {}".format(report["input_size"]))
    lines.append("odd values : {}".format(report["odd"]))
    lines.append("odd count  : {}".format(report["odd_count"]))
    lines.append("odd sum    : {}".format(report["odd_sum"]))
    if report["repeated_odd"]:
        lines.append("repeated   : {}".format(report["repeated_odd"]))
    return lines


def main():
    inputs = ["1, 2, 3, 4, 5", "2 4 6", "7 7 8 9 9 9 10"]
    parity_totals = {}
    for raw in inputs:
        numbers = parse_numbers(raw)
        print("input: {!r}".format(raw))
        for line in format_report(summarize(numbers)):
            print("  " + line)
        for kind, values in group_by_parity(numbers).items():
            parity_totals[kind] = parity_totals.get(kind, 0) + len(values)
    print("totals: {}".format(parity_totals))


if __name__ == "__main__":
    main()

def char_frequency(text):
    """Count occurrences of each character in text, ignoring case."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    frequency_map = {}
    for char in text.lower():
        frequency_map[char] = frequency_map.get(char, 0) + 1
    return frequency_map


def group_by_count(frequency_map):
    """Invert a frequency map into count -> sorted list of characters."""
    groups = {}
    for char, count in frequency_map.items():
        chars = groups.get(count)
        if chars is None:
            chars = []
            groups[count] = chars
        chars.append(char)
    for count in groups:
        groups[count].sort()
    return groups


def most_common(frequency_map, limit=3):
    """Return up to `limit` (char, count) pairs, highest count first."""
    ranked = sorted(frequency_map.items(), key=lambda pair: (-pair[1], pair[0]))
    return ranked[:limit]


def describe_char(char):
    """Human readable label for a character key."""
    labels = {" ": "<space>", "\t": "<tab>", "\n": "<newline>"}
    return labels.get(char, char)


def format_report(text):
    """Build a multi-line report about the characters found in text."""
    frequency_map = char_frequency(text)
    lines = []
    lines.append("text: {!r}".format(text))
    lines.append("distinct characters: {}".format(len(frequency_map)))
    for char, count in most_common(frequency_map):
        lines.append("  {} -> {}".format(describe_char(char), count))
    groups = group_by_count(frequency_map)
    repeated = {}
    for count, chars in groups.items():
        if count > 1:
            repeated[count] = chars
    if repeated:
        for count in sorted(repeated, reverse=True):
            shown = " ".join(describe_char(c) for c in repeated[count])
            lines.append("  seen {} times: {}".format(count, shown))
    else:
        lines.append("  no repeated characters")
    return "\n".join(lines)


def main():
    samples = ["hello", "Python", "Mississippi River", ""]
    totals = {}
    for sample in samples:
        print(format_report(sample))
        print("-" * 40)
        for char, count in char_frequency(sample).items():
            totals[char] = totals.get(char, 0) + count
    print("combined totals across {} samples:".format(len(samples)))
    for char, count in most_common(totals, limit=5):
        print("  {} -> {}".format(describe_char(char), count))


if __name__ == "__main__":
    main()

