import os
import sys


def count_file_lines(filepath):
    """Return the number of lines in the file at filepath."""
    line_count = 0
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for _line in handle:
            line_count += 1
    return line_count


def blank_line_numbers(filepath):
    """Return the 1-based numbers of the lines that contain only whitespace."""
    blanks = []
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for number, line in enumerate(handle, start=1):
            if not line.strip():
                blanks.append(number)
    return blanks


def count_many(paths):
    """Map each readable path to its line count, skipping unreadable entries."""
    counts = {}
    for path in paths:
        if os.path.isfile(path):
            counts[path] = count_file_lines(path)
    return counts


def group_by_size(counts, threshold=100):
    """Split a path -> line count mapping into 'small' and 'large' buckets."""
    groups = {}
    for path, total in counts.items():
        key = "small" if total <= threshold else "large"
        groups.setdefault(key, []).append(path)
    for bucket in groups.values():
        bucket.sort()
    return groups


def format_report(counts, threshold=100):
    """Build the printable report lines for the counted files."""
    report = []
    groups = group_by_size(counts, threshold)
    for key in ("small", "large"):
        members = groups.get(key, [])
        if members:
