def parse_date(text):
    """Turn a 'YYYY-MM-DD' string into a date object."""
    if not isinstance(text, str):
        raise TypeError("date must be given as a string")
    pieces = text.strip().split("-")
    if len(pieces) != 3:
        raise ValueError("expected format YYYY-MM-DD, got %r" % text)
    widths = (4, 2, 2)
    fields = {}
    for name, piece, width in zip(("year", "month", "day"), pieces, widths):
        if len(piece) != width or not piece.isdigit():
            raise ValueError("bad %s component in %r" % (name, text))
        fields[name] = int(piece)
    return date(**fields)


def days_remaining(start_date_str, end_date_str):
    """Number of days between the start date and the (future) end date."""
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    return (end - start).days


def breakdown(days):
    """Split a day count into weeks and leftover days."""
    magnitude = abs(days)
    units = {}
    units["week"] = magnitude // 7
    units["day"] = magnitude % 7
    return units


def describe(days):
    """Readable description of a day count, e.g. '4 weeks, 2 days'."""
    parts = []
    for label, value in breakdown(days).items():
        if value:
            parts.append("%d %s%s" % (value, label, "" if value == 1 else "s"))
    if not parts:
        return "the same day"
    text = ", ".join(parts)
    return text + " ago" if days < 0 else text


def countdown_report(pairs):
    """Compute day counts for (start, end) pairs, collecting bad input."""
    report = {}
    failures = []
    for start_text, end_text in pairs:
        try:
