def tokenize(text):
    """Split *text* into words, using the space character as the separator."""
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    words = []
    current = []
    for ch in text:
        if ch == " ":
            if current:
                words.append("".join(current))
                current = []
        else:
            current.append(ch)
    if current:
        words.append("".join(current))
    return words


def count_words(text):
    """Return the number of space-separated words in *text*."""
    word_count = len(tokenize(text))
    return word_count


def word_frequencies(text):
    """Map each word of *text* to the number of times it occurs."""
    frequencies = {}
    for word in tokenize(text):
        frequencies[word] = frequencies.get(word, 0) + 1
    return frequencies


def group_by_length(text):
    """Map word lengths to the list of words having that length."""
    groups = {}
    for word in tokenize(text):
        bucket = groups.get(len(word))
        if bucket is None:
            bucket = []
            groups[len(word)] = bucket
        bucket.append(word)
    return groups


def format_report(text):
    """Build a multi-line human readable summary of *text*."""
    lines = []
    lines.append("text     : %r" % text)
    lines.append("words    : %d" % count_words(text))
    repeated = {}
    for word, hits in word_frequencies(text).items():
        if hits > 1:
            repeated[word] = hits
    if repeated:
        pairs = sorted(repeated.items(), key=lambda item: (-item[1], item[0]))
        lines.append("repeated : " + ", ".join("%s x%d" % p for p in pairs))
    for length in sorted(group_by_length(text)):
        members = group_by_length(text)[length]
        lines.append("  len %-3d %s" % (length, " ".join(members)))
    return "\n".join(lines)


def main():
    samples = [
        "This is a test sentence.",
        "  Hello   world  ",
        "the cat and the dog and the bird",
        "",
    ]
    for sample in samples:
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
