def cubes_up_to(limit):
    """Return the cubes of every integer from 0 to limit (inclusive)."""
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an int, got %r" % (limit,))
    if limit < 0:
        cubes_list = []
        return cubes_list
    cubes_list = [n ** 3 for n in range(limit + 1)]
    return cubes_list


def parse_limits(text):
    """Split a comma separated string into valid ints and rejected tokens."""
    limits = []
    rejected = []
    for token in text.split(","):
        token = token.strip()
        if not token:
            continue
        try:
            limits.append(int(token))
        except ValueError:
            rejected.append(token)
    return limits, rejected


def group_by_last_digit(cubes):
    """Map the final decimal digit of each cube to the cubes having it."""
    groups = {}
    for cube in cubes:
        groups.setdefault(cube % 10, []).append(cube)
    return groups


def collect_cubes(limits):
    """Compute the cube list for every requested limit, keyed by the limit."""
    table = {}
    for limit in limits:
        table[limit] = cubes_up_to(limit)
    return table


def format_report(limit, cubes):
    """Build the report lines describing one cube list."""
    lines = ["limit %d -> %s" % (limit, cubes)]
    if not cubes:
        lines.append("  (no cubes: negative limit)")
        return lines
    lines.append("  count %d, largest %d, total %d"
                 % (len(cubes), cubes[-1], sum(cubes)))
    groups = group_by_last_digit(cubes)
    for digit in sorted(groups):
        members = ", ".join(str(cube) for cube in groups[digit])
        lines.append("  ends in %d: %s" % (digit, members))
    return lines


def build_report(text):
    """Turn a textual list of limits into a printable report."""
    limits, rejected = parse_limits(text)
    output = []
    for token in rejected:
        output.append("skipping unparsable limit %r" % token)
    table = collect_cubes(limits)
    for limit in limits:
