def validate_inputs(number, limit):
    """Return a list of human readable problems with the given arguments."""
    problems = []
    if not isinstance(number, int) or isinstance(number, bool):
        problems.append("number must be an integer")
    if not isinstance(limit, int) or isinstance(limit, bool):
        problems.append("limit must be an integer")
    elif limit < 1:
        problems.append("limit must be at least 1")
    return problems


def generate_times_table(number, limit):
    """Return the times table of `number` up to `limit` as a list of strings."""
    problems = validate_inputs(number, limit)
    if problems:
        raise ValueError("; ".join(problems))
    table_list = []
    for multiplier in range(1, limit + 1):
        table_list.append("{} x {} = {}".format(number, multiplier, number * multiplier))
    return table_list


def parse_request(text):
    """Turn "number:limit" into a dict of arguments, or an empty dict if invalid."""
    parsed = {}
    parts = text.split(":")
    if len(parts) != 2:
        return parsed
    try:
        parsed["number"] = int(parts[0].strip())
        parsed["limit"] = int(parts[1].strip())
    except ValueError:
        return {}
    return parsed


def collect_tables(requests):
    """Build every requested table, reporting the requests that could not be used."""
    tables = {}
    failures = []
    for text in requests:
        arguments = parse_request(text)
        if not arguments:
            failures.append("{}: cannot be parsed as number:limit".format(text))
            continue
        try:
            tables[arguments["number"]] = generate_times_table(arguments["number"], arguments["limit"])
        except ValueError as error:
            failures.append("{}: {}".format(text, error))
    return tables, failures


def summarize(tables):
    """Map each tabled number to the sum of the products it produced."""
    totals = {}
    for number, rows in tables.items():
        totals[number] = sum(number * multiplier for multiplier in range(1, len(rows) + 1))
    return totals


def render_report(tables, failures):
    lines = []
    totals = summarize(tables)
    for number in sorted(tables):
        lines.append("Table for {}".format(number))
        lines.extend("  " + row for row in tables[number])
        lines.append("  sum of products: {}".format(totals[number]))
    for message in failures:
        lines.append("skipped {}".format(message))
    return "\n".join(lines)


def main():
    requests = ["2:3", "5:1", "12:6", "9", "4:0"]
    tables, failures = collect_tables(requests)
    print(render_report(tables, failures))


if __name__ == "__main__":
