DIGIT_VALUES = dict()
for _index, _char in enumerate("0123456789abcdef"):
    DIGIT_VALUES[_char] = _index
    DIGIT_VALUES[_char.upper()] = _index


def normalize(hex_string):
    """Strip whitespace and an optional 0x/0X prefix from a hex literal."""
    text = hex_string.strip()
    if text[:2] in ("0x", "0X"):
        text = text[2:]
    return text.replace("_", "")


def hex_to_decimal(hex_string):
    if not isinstance(hex_string, str):
        raise TypeError("hex_string must be a str")
    digits = normalize(hex_string)
    if not digits:
        raise ValueError("hex_string contains no hexadecimal digits")
    decimal_num = 0
    for char in digits:
        if char not in DIGIT_VALUES:
            raise ValueError("invalid hexadecimal digit: %r" % char)
        decimal_num = decimal_num * 16 + DIGIT_VALUES[char]
    return decimal_num


def convert_many(hex_strings):
    """Convert a sequence of literals, returning values and error messages."""
    values = list()
    errors = list()
    for item in hex_strings:
        try:
            values.append(hex_to_decimal(item))
        except (TypeError, ValueError) as exc:
            errors.append("%r -> %s" % (item, exc))
    return values, errors


def group_by_width(hex_strings):
    """Map the number of significant hex digits to the decimal values found."""
    groups = dict()
    for item in hex_strings:
        digits = normalize(item).lstrip("0") or "0"
        groups.setdefault(len(digits), list()).append(hex_to_decimal(item))
    return groups


def format_table(hex_strings):
    rows = list()
    for item in hex_strings:
        rows.append("%-10s %12d" % (item, hex_to_decimal(item)))
    return "\n".join(rows)


