from datetime import date

_PARSE_CACHE = {}


def parse_date(text):
    """Turn a 'YYYY-MM-DD' string into a date object, with caching."""
    if not isinstance(text, str):
        raise TypeError('date must be a string, got %r' % type(text).__name__)
    cached = _PARSE_CACHE.get(text)
    if cached is not None:
        return cached
    parts = text.split('-')
    if len(parts) != 3:
        raise ValueError('expected YYYY-MM-DD, got %r' % text)
    if len(parts[0]) != 4 or len(parts[1]) != 2 or len(parts[2]) != 2:
        raise ValueError('expected YYYY-MM-DD, got %r' % text)
    numbers = []
    for part in parts:
        if not part.isdigit():
            raise ValueError('non-numeric component in %r' % text)
        numbers.append(int(part))
    value = date(numbers[0], numbers[1], numbers[2])
    _PARSE_CACHE[text] = value
    return value


def collect_problems(texts):
    """Return a list of (text, message) for every input that cannot be parsed."""
    problems = []
    for text in texts:
        try:
            parse_date(text)
        except (TypeError, ValueError) as exc:
            problems.append((text, str(exc)))
    return problems


def days_between_dates(start_date_str, end_date_str):
    """Signed number of days from start_date_str to end_date_str."""
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    return (end - start).days


def summarize(pairs):
    """Count how many pairs move forward, backward or stay on the same day."""
    totals = {}
    for start_text, end_text in pairs:
        delta = days_between_dates(start_text, end_text)
        if delta > 0:
            key = 'forward'
        elif delta < 0:
            key = 'backward'
        else:
            key = 'same day'
        totals[key] = totals.get(key, 0) + 1
    return totals


def format_report(pairs):
    """Build a human readable report for a sequence of (start, end) pairs."""
    lines = []
    for start_text, end_text in pairs:
        delta = days_between_dates(start_text, end_text)
        lines.append('%s -> %s : %+d day(s)' % (start_text, end_text, delta))
    totals = summarize(pairs)
    for key in sorted(totals):
        lines.append('%-9s %d pair(s)' % (key + ':', totals[key]))
    return '\n'.join(lines)


def main():
    pairs = [
        ('2023-01-01', '2023-01-05'),
        ('2023-01-01', '2022-12-25'),
        ('2020-02-28', '2020-03-01'),
        ('2024-06-10', '2024-06-10'),
    ]
    inputs = []
    for start_text, end_text in pairs:
        inputs.append(start_text)
        inputs.append(end_text)
    problems = collect_problems(inputs)
    if problems:
        for text, message in problems:
            print('invalid date %r: %s' % (text, message))
        return
    print(format_report(pairs))


if __name__ == '__main__':
    main()

