def validate_task(name, start, end):
    """Return a list of problems found with a single task definition."""
    problems = []
    if not isinstance(start, int) or not isinstance(end, int):
        problems.append("{}: times must be integers".format(name))
        return problems
    if not (0 <= start <= 24) or not (0 <= end <= 24):
        problems.append("{}: times must fall between 0 and 24".format(name))
    if start >= end:
        problems.append("{}: start ({}) must precede end ({})".format(name, start, end))
    return problems


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    """True when the two half-open intervals share at least one hour."""
    return task1_start < task2_end and task2_start < task1_end


def find_conflicts(tasks):
    """Return every pair of task names whose time ranges overlap."""
    conflicts = []
    names = sorted(tasks)
    for i, first in enumerate(names):
        a_start, a_end = tasks[first]
        for second in names[i + 1:]:
            b_start, b_end = tasks[second]
            if has_overlap(a_start, a_end, b_start, b_end):
                conflicts.append((first, second))
    return conflicts


def busy_hours(tasks):
    """Map each occupied hour to the names of the tasks covering it."""
    hours = {}
    for name in sorted(tasks):
        start, end = tasks[name]
        for hour in range(start, end):
            hours.setdefault(hour, []).append(name)
    return hours


def free_slots(tasks, day_start=0, day_end=24):
    """List the maximal stretches of the day with nothing scheduled."""
    occupied = busy_hours(tasks)
    slots = []
    open_at = None
    for hour in range(day_start, day_end):
        if hour in occupied:
            if open_at is not None:
                slots.append((open_at, hour))
                open_at = None
        elif open_at is None:
            open_at = hour
    if open_at is not None:
        slots.append((open_at, day_end))
    return slots


def build_report(tasks):
    lines = []
    errors = []
    for name in sorted(tasks):
        start, end = tasks[name]
        errors.extend(validate_task(name, start, end))
    if errors:
        return errors
    conflicts = find_conflicts(tasks)
    if conflicts:
        for first, second in conflicts:
            lines.append("conflict: {} overlaps {}".format(first, second))
    else:
        lines.append("no conflicts")
    for start, end in free_slots(tasks):
        lines.append("free: {:02d}:00-{:02d}:00".format(start, end))
    return lines


def main():
    schedule = {}
    schedule["standup"] = (9, 10)
    schedule["design review"] = (11, 14)
    schedule["pairing"] = (9, 12)
    schedule["retro"] = (16, 17)
    for line in build_report(schedule):
        print(line)
    print("boundary case:", has_overlap(9, 10, 10, 12))


if __name__ == "__main__":
    main()

