def validate_matrix(matrix):
    """Check that matrix is a rectangular list of lists of numbers."""
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    lengths = []
    for row in matrix:
        if not isinstance(row, list):
            raise TypeError("every row of matrix must be a list")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("matrix entries must be int or float")
        lengths.append(len(row))
    if len(set(lengths)) > 1:
        raise ValueError("all rows must have the same length")


def transpose_matrix(matrix):
    """Return a new matrix whose rows are the columns of the given matrix."""
    validate_matrix(matrix)
    transposed = []
    if not matrix:
        return transposed
    for index in range(len(matrix[0])):
        column = []
        for row in matrix:
            column.append(row[index])
        transposed.append(column)
    return transposed


def matrix_shape(matrix):
    """Return (rows, columns) of a validated matrix."""
    validate_matrix(matrix)
    if not matrix:
        return (0, 0)
    return (len(matrix), len(matrix[0]))


def column_stats(matrix):
    """Map each column index to a summary of that column's values."""
    stats = {}
    for index, column in enumerate(transpose_matrix(matrix)):
        stats[index] = {
            "minimum": min(column),
            "maximum": max(column),
            "total": sum(column),
        }
    return stats


def format_matrix(matrix):
    """Render a matrix as aligned rows of text."""
    validate_matrix(matrix)
    width = 0
    for row in matrix:
        for value in row:
            width = max(width, len(str(value)))
    lines = []
    for row in matrix:
        cells = []
        for value in row:
            cells.append(str(value).rjust(width))
        lines.append("[ " + "  ".join(cells) + " ]")
    return "\n".join(lines)


def main():
    samples = [[[1, 2, 3], [4, 5, 6]], [[10]], [[1.5, -2], [0, 7], [3, 3]]]
    for matrix in samples:
        print("original", matrix_shape(matrix))
        print(format_matrix(matrix))
        result = transpose_matrix(matrix)
        print("transposed", matrix_shape(result))
        print(format_matrix(result))
        for index, summary in column_stats(matrix).items():
            print("column %d -> %s" % (index, summary))
        print()
    empty = []
    print("empty transpose:", transpose_matrix(empty))


if __name__ == "__main__":
    main()

