def count_values(numbers):
    """Return a dict mapping each value in numbers to its frequency."""
    counts = {}
    for value in numbers:
        counts[value] = counts.get(value, 0) + 1
    return counts


def find_mode(numbers):
    """Return the most frequent element of numbers."""
    if not numbers:
        raise ValueError("find_mode() requires a non-empty list")
    counts = count_values(numbers)
    best_value = numbers[0]
    best_count = 0
    for value, count in counts.items():
        if count > best_count:
            best_value = value
            best_count = count
    return best_value


def all_modes(numbers):
    """Return every value tied for the highest frequency, in first-seen order."""
    counts = count_values(numbers)
    top = max(counts.values())
    modes = []
    seen = set()
    for value in numbers:
        if counts[value] == top and value not in seen:
            seen.add(value)
            modes.append(value)
    return modes


def group_by_frequency(numbers):
    """Return a dict mapping a frequency to the sorted values having it."""
    groups = {}
    for value, count in count_values(numbers).items():
        groups.setdefault(count, []).append(value)
    for count in groups:
        groups[count].sort()
    return groups


def parse_numbers(text):
    """Parse whitespace- or comma-separated numbers from text."""
    numbers = []
    for token in text.replace(",", " ").split():
        number = float(token)
        if number.is_integer():
            number = int(number)
        numbers.append(number)
    return numbers


def format_report(numbers):
    """Build a human-readable summary of the modes of numbers."""
    lines = []
    lines.append("data:  " + ", ".join(str(n) for n in numbers))
    lines.append("mode:  " + str(find_mode(numbers)))
    ties = all_modes(numbers)
    if len(ties) > 1:
        lines.append("ties:  " + ", ".join(str(n) for n in ties))
    groups = group_by_frequency(numbers)
    for count in sorted(groups, reverse=True):
        values = ", ".join(str(v) for v in groups[count])
        lines.append("x{0:<4} {1}".format(count, values))
    return "\n".join(lines)


def main(argv):
    """Read one list of numbers per input line and report its mode."""
    if len(argv) > 1:
        sources = [" ".join(argv[1:])]
    else:
        import sys
        sources = sys.stdin.read().splitlines()
    for source in sources:
        numbers = parse_numbers(source)
        if numbers:
            print(format_report(numbers))


if __name__ == "__main__":
    import sys
    main(sys.argv)

