def count_chars(s):
    """Return a mapping from character to the number of times it appears in s."""
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def index_map(s):
    """Return a mapping from character to the list of indices where it occurs."""
    positions = {}
    for i, ch in enumerate(s):
        if ch not in positions:
            positions[ch] = []
        positions[ch].append(i)
    return positions


def first_unique_char(s):
    """Return the index of the first non-repeating character, or -1 if none."""
    if not isinstance(s, str):
        raise TypeError("s must be a str")
    counts = count_chars(s)
    for i, ch in enumerate(s):
        if counts[ch] == 1:
            return i
    return -1


def all_unique_indices(s):
    """Return the indices of every character that occurs exactly once, in order."""
    uniques = []
    for ch, spots in index_map(s).items():
        if len(spots) == 1:
            uniques.append(spots[0])
    uniques.sort()
    return uniques


def duplicate_groups(s):
    """Group the repeated characters of s by how often they appear."""
    groups = {}
    for ch, total in count_chars(s).items():
        if total > 1:
            if total not in groups:
                groups[total] = []
            groups[total].append(ch)
    for chars in groups.values():
        chars.sort()
    return groups


def format_report(s):
    """Build a human readable summary of the uniqueness analysis of s."""
    lines = []
    index = first_unique_char(s)
    if index == -1:
        lines.append("%r -> -1 (no unique character)" % s)
    else:
        lines.append("%r -> %d (%r)" % (s, index, s[index]))
    lines.append("  unique indices: %s" % all_unique_indices(s))
    for total in sorted(duplicate_groups(s)):
        chars = duplicate_groups(s)[total]
        lines.append("  seen %dx: %s" % (total, "".join(chars)))
    return "\n".join(lines)


def main():
    samples = ["leetcode", "loveleetcode", "aabb", "", "swiss cheese"]
    for sample in samples:
        print(format_report(sample))


if __name__ == "__main__":
    main()

