import math
import sys


def geometric_mean(numbers):
    """Return the geometric mean, or 0.0 for empty/non-positive input."""
    if not numbers:
        return 0.0
    logs = []
    for value in numbers:
        if value <= 0:
            return 0.0
        logs.append(math.log(value))
    return math.exp(sum(logs) / len(logs))


def parse_numbers(text):
    """Split text on commas/whitespace into floats, reporting bad tokens."""
    values = []
    errors = []
    for token in text.replace(",", " ").split():
        try:
            values.append(float(token))
        except ValueError:
            errors.append(token)
    return values, errors


def parse_datasets(lines):
    """Read "name: 1 2 4" lines into a mapping plus a mapping of bad tokens."""
    datasets = {}
    problems = {}
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if ":" in line:
            name, raw = line.split(":", 1)
        else:
            name, raw = "unnamed", line
        name = name.strip()
        values, errors = parse_numbers(raw)
        datasets[name] = values
        if errors:
            problems[name] = errors
    return datasets, problems


def summarize(datasets):
    report = {}
    for name, values in datasets.items():
        report[name] = geometric_mean(values)
    return report


def format_report(report, problems):
    lines = []
    for name in sorted(report):
        mean = report[name]
        if mean > 0.0:
            lines.append("%s: %.4f" % (name, mean))
        else:
            lines.append("%s: undefined" % name)
        skipped = problems.get(name, [])
        if skipped:
            lines.append("  skipped tokens: " + ", ".join(skipped))
    return "\n".join(lines)


def main():
    datasets, problems = parse_datasets(sys.stdin.read().splitlines())
    if not datasets:
        print("no datasets given")
        return
    report = summarize(datasets)
    pooled = []
    for values in datasets.values():
        pooled.extend(values)
    report["<pooled>"] = geometric_mean(pooled)
    print(format_report(report, problems))


if __name__ == "__main__":
    main()

