def generate_permutations(lst):
    """Return a list containing every ordering of the elements of `lst`."""
    result = []
    if not lst:
        return [[]]
    for index, item in enumerate(lst):
        rest = lst[:index] + lst[index + 1:]
        for tail in generate_permutations(rest):
            result.append([item] + tail)
    return result


def unique_permutations(lst):
    """Like generate_permutations, but collapse orderings equal element-wise."""
    seen = {}
    ordered = []
    for perm in generate_permutations(lst):
        key = tuple(perm)
        if key not in seen:
            seen[key] = True
            ordered.append(perm)
    return ordered


def group_by_first(perms):
    """Map each leading element to the permutations that start with it."""
    groups = {}
    for perm in perms:
        groups.setdefault(perm[0], []).append(perm)
    return groups


def format_permutations(perms):
    """Render permutations as human readable text lines."""
    lines = []
    for perm in perms:
        lines.append("[" + ", ".join(repr(item) for item in perm) + "]")
    return lines


def describe(label, sample):
    """Print a small report for one sample list and return its permutation count."""
    perms = generate_permutations(sample)
    distinct = unique_permutations(sample)
    print("%s: %r -> %d permutations (%d distinct)"
          % (label, sample, len(perms), len(distinct)))
    for line in format_permutations(distinct):
        print("    " + line)
    groups = group_by_first(distinct)
    for first in sorted(groups, key=repr):
        print("    starting with %r: %d" % (first, len(groups[first])))
    return len(perms)


def main():
    summary = {}
    samples = [[1, 2], ['a'], ['x', 'y', 'z'], [1, 1, 2]]
    for number, sample in enumerate(samples, start=1):
        label = "sample %d" % number
        summary[label] = describe(label, sample)
    print("totals:")
    for label in sorted(summary):
        print("  %s -> %d" % (label, summary[label]))


if __name__ == "__main__":
    main()

