def _validate(name, value):
    if not isinstance(value, str):
        raise TypeError("{} must be a str, got {}".format(name, type(value).__name__))
    return value


def find_occurrence_positions(main_string, sub_string):
    """Return the start indexes of every non-overlapping case-insensitive match."""
    _validate("main_string", main_string)
    _validate("sub_string", sub_string)
    positions = []
    if not sub_string:
        return positions
    haystack = main_string.lower()
    needle = sub_string.lower()
    start = 0
    while True:
        index = haystack.find(needle, start)
        if index < 0:
            return positions
        positions.append(index)
        start = index + len(needle)


def count_substring_occurrences_ci(main_string, sub_string):
    """Count case-insensitive occurrences of sub_string inside main_string."""
    return len(find_occurrence_positions(main_string, sub_string))


def count_many(main_string, sub_strings):
    """Map each candidate substring to its case-insensitive count."""
    counts = {}
    for candidate in sub_strings:
        counts[candidate] = count_substring_occurrences_ci(main_string, candidate)
    return counts


def group_by_count(counts):
    """Invert a count mapping into count -> sorted list of substrings."""
    groups = {}
    for candidate, total in counts.items():
        bucket = groups.get(total)
        if bucket is None:
            bucket = []
            groups[total] = bucket
        bucket.append(candidate)
    for bucket in groups.values():
        bucket.sort()
    return groups


def format_report(main_string, sub_strings):
    """Build a human-readable report of matches found in main_string."""
    counts = count_many(main_string, sub_strings)
    lines = []
    lines.append('Text: "{}"'.format(main_string))
    for candidate in sub_strings:
        positions = find_occurrence_positions(main_string, candidate)
        where = ", ".join(str(p) for p in positions) if positions else "none"
        lines.append("  {!r}: {} (at {})".format(candidate, counts[candidate], where))
    for total in sorted(group_by_count(counts), reverse=True):
        names = ", ".join(repr(name) for name in group_by_count(counts)[total])
        lines.append("  count {} -> {}".format(total, names))
    return "\n".join(lines)


def main():
    samples = [
        ("Hello world, World wide web", ["world", "wide", "moon"]),
        ("Python is Fun", ["fun", "python", "is"]),
    ]
    for text, candidates in samples:
        print(format_report(text, candidates))
    print(count_substring_occurrences_ci("Hello world, World wide web", "world"))
    print(count_substring_occurrences_ci("Python is Fun", "fun"))


if __name__ == "__main__":
    main()

