def remove_duplicates_unordered(items):
    """Return a new list containing each distinct element of *items* once."""
    seen = {}
    unique = []
    for item in items:
        try:
            key = (type(item).__name__, item)
            is_new = key not in seen
        except TypeError:
            key = None
            is_new = not any(other is item or other == item for other in unique)
        if is_new:
            if key is not None:
                seen[key] = True
            unique.append(item)
    return unique


def count_occurrences(items):
    """Map each distinct hashable element to how many times it appears."""
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return counts


def duplicate_values(items):
    """Return the distinct elements that occur more than once."""
    repeated = []
    for value, count in count_occurrences(items).items():
        if count > 1:
            repeated.append(value)
    return repeated


def group_by_type(items):
    """Group distinct elements by the name of their type."""
    groups = {}
    for item in remove_duplicates_unordered(items):
        groups.setdefault(type(item).__name__, []).append(item)
    return groups


def format_report(items):
    """Build a multi-line human-readable summary of the deduplication."""
    unique = remove_duplicates_unordered(items)
    lines = []
    lines.append("input    : %r" % (items,))
    lines.append("unique   : %r" % (unique,))
    lines.append("removed  : %d element(s)" % (len(items) - len(unique)))
    repeated = duplicate_values(items)
    if repeated:
        lines.append("duplicated: %r" % (sorted(repeated, key=repr),))
    for type_name in sorted(group_by_type(items)):
        members = group_by_type(items)[type_name]
        lines.append("  %-6s -> %r" % (type_name, members))
    return "\n".join(lines)


def main():
    samples = []
    samples.append([1, 2, 2, 3, 1, 4])
    samples.append(['a', 'b', 'a', 'c'])
    samples.append([1, 'a', 1.0, 'a', None, None])
    samples.append([])
    for sample in samples:
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

