_POPCOUNT_CACHE = {}


def count_set_bits(n):
    """Return the number of '1' bits in the binary representation of n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("count_set_bits expects an int")
    if n < 0:
        raise ValueError("count_set_bits expects a non-negative integer")
    cached = _POPCOUNT_CACHE.get(n)
    if cached is not None:
        return cached
    total = 0
    rest = n
    while rest:
        rest &= rest - 1
        total += 1
    _POPCOUNT_CACHE[n] = total
    return total


def bit_positions(n):
    """Return the indices of the set bits of n, least significant first."""
    positions = []
    index = 0
    rest = n
    while rest:
        if rest & 1:
            positions.append(index)
        rest >>= 1
        index += 1
    return positions


def group_by_popcount(numbers):
    """Map each population count to the sorted numbers that have it."""
    groups = {}
    for value in numbers:
        bucket = groups.setdefault(count_set_bits(value), [])
        bucket.append(value)
    for bucket in groups.values():
        bucket.sort()
    return groups


def parse_numbers(text):
    """Read whitespace or comma separated non-negative integers from text."""
    numbers = []
    for token in text.replace(",", " ").split():
        numbers.append(int(token))
    return numbers


def format_report(numbers):
    """Build a human readable popcount report for the given numbers."""
    lines = []
    for value in numbers:
        bits = bit_positions(value)
        lines.append(
            "{0:>5} = 0b{1:<12} bits={2} positions={3}".format(
                value, format(value, "b"), count_set_bits(value), bits
            )
        )
    groups = group_by_popcount(numbers)
    lines.append("")
    for popcount in sorted(groups):
        members = ", ".join(str(v) for v in groups[popcount])
        lines.append("popcount {0}: {1}".format(popcount, members))
    return "\n".join(lines)


def main():
    samples = parse_numbers("5, 10, 0, 1, 255, 1024, 4095, 7")
    print(format_report(samples))
    print("")
    print("count_set_bits(5) ->", count_set_bits(5))
    print("count_set_bits(10) ->", count_set_bits(10))


if __name__ == "__main__":
    main()

