from collections import deque


def validate_series(data, window_size):
    """Return a list of human-readable problems with the given inputs."""
    problems = []
    if not isinstance(window_size, int) or isinstance(window_size, bool):
        problems.append("window_size must be an integer")
    elif window_size < 1:
        problems.append("window_size must be at least 1")
    for index, value in enumerate(data):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            problems.append("data[%d] is not a number: %r" % (index, value))
    return problems


def calculate_sma_fixed_window(data, window_size):
    """Simple moving average over a fixed window; [] if the window is too wide."""
    problems = validate_series(data, window_size)
    if problems:
        raise ValueError("; ".join(problems))
    if window_size > len(data):
        return []
    averages = []
    window = deque()
    running_total = 0.0
    for value in data:
        window.append(value)
        running_total += value
        if len(window) > window_size:
            running_total -= window.popleft()
        if len(window) == window_size:
            averages.append(running_total / window_size)
    return averages


def describe_trend(averages):
    """Count how the moving average moves from one step to the next."""
    counts = {}
    for name in ("rising", "falling", "flat"):
        counts[name] = 0
    for previous, current in zip(averages, averages[1:]):
        if current > previous:
            counts["rising"] += 1
        elif current < previous:
            counts["falling"] += 1
        else:
            counts["flat"] += 1
    return counts


def align_with_data(data, averages):
    """Pair every data point with its moving average, or None when undefined."""
    offset = len(data) - len(averages)
    aligned = []
    for index, value in enumerate(data):
        if averages and index >= offset:
            aligned.append((value, averages[index - offset]))
        else:
            aligned.append((value, None))
    return aligned


def format_report(data, window_size):
    lines = []
    averages = calculate_sma_fixed_window(data, window_size)
    lines.append("window=%d points=%d averages=%d" % (window_size, len(data), len(averages)))
    for value, average in align_with_data(data, averages):
        shown = "-" if average is None else "%.2f" % average
        lines.append("  %8s  %8s" % (value, shown))
    if averages:
        trend = describe_trend(averages)
        lines.append("  trend: " + ", ".join("%s=%d" % item for item in sorted(trend.items())))
    return "\n".join(lines)


def main():
    samples = [([10, 20, 30, 40, 50], 3), ([1, 2, 3, 4], 2), ([5, 5, 5], 4)]
    for data, window_size in samples:
        print(format_report(data, window_size))
        print()


if __name__ == "__main__":
    main()

