import os
import tempfile


def read_first_n_lines(filepath, n):
    """Return at most the first n lines (with newline characters) of a file."""
    lines = []
    if n <= 0:
        return lines
    with open(filepath, "r", encoding="utf-8") as handle:
        for line in handle:
            lines.append(line)
            if len(lines) == n:
                break
    return lines


def create_sample_file(filepath, text_lines):
    """Write the given logical lines to filepath, one per line."""
    with open(filepath, "w", encoding="utf-8") as handle:
        for text in text_lines:
            handle.write(text + "\n")
    return filepath


def line_stats(lines):
    """Compute simple statistics about a list of raw lines."""
    stats = {}
    stats["count"] = len(lines)
    stats["chars"] = sum(len(line.rstrip("\n")) for line in lines)
    stats["blank"] = sum(1 for line in lines if not line.strip())
    stats["longest"] = max((len(line.rstrip("\n")) for line in lines), default=0)
    return stats


def group_by_first_word(lines):
    """Map the first whitespace-separated token of each line to its line numbers."""
    groups = {}
    for number, line in enumerate(lines, start=1):
        words = line.split()
        if not words:
            continue
        groups.setdefault(words[0], []).append(number)
    return groups


def format_report(filepath, lines):
    """Build a human readable multi-line report about the lines that were read."""
    rows = []
    stats = line_stats(lines)
    rows.append("File: {}".format(os.path.basename(filepath)))
    rows.append("Lines read: {count}, characters: {chars}".format(**stats))
    rows.append("Blank lines: {blank}, longest line: {longest}".format(**stats))
    for token, numbers in sorted(group_by_first_word(lines).items()):
        positions = ", ".join(str(number) for number in numbers)
        rows.append("  {:<8} -> lines {}".format(token, positions))
    return "\n".join(rows)


def main():
    sample = ["Line 1", "Line 2", "Line 3", "", "Line 5 is a little longer"]
    directory = tempfile.mkdtemp()
    path = create_sample_file(os.path.join(directory, "data.txt"), sample)
    results = {}
    for n in (0, 2, 5, 99):
        results[n] = read_first_n_lines(path, n)
    for n, lines in results.items():
        print("read_first_n_lines(path, {}) -> {!r}".format(n, lines))
    print(format_report(path, results[99]))
    os.remove(path)
    os.rmdir(directory)


if __name__ == "__main__":
    main()

class Node:
    """A binary tree node holding a value and two optional children."""

    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right


def build_tree(values):
    """Build a binary tree from a level-order sequence; None means 'no node'."""
    nodes = []
    for value in values:
        nodes.append(Node(value) if value is not None else None)
    for index, node in enumerate(nodes):
        if node is None:
            continue
        left_index = 2 * index + 1
        right_index = left_index + 1
        if left_index < len(nodes):
            node.left = nodes[left_index]
        if right_index < len(nodes):
            node.right = nodes[right_index]
    return nodes[0] if nodes else None


def is_symmetric(root):
    """Return True when the tree is a mirror image of itself."""
    if root is None:
        return True
    stack = []
    stack.append((root.left, root.right))
    while stack:
        left, right = stack.pop()
        if left is None and right is None:
            continue
        if left is None or right is None:
            return False
        if left.value != right.value:
            return False
        stack.append((left.left, right.right))
        stack.append((left.right, right.left))
    return True


def level_order(root):
    """Return the tree as a list of levels, using None for missing children."""
    levels = []
    current = [root] if root is not None else []
    while any(node is not None for node in current):
        row = []
        following = []
        for node in current:
            row.append(node.value if node is not None else None)
            following.append(node.left if node is not None else None)
            following.append(node.right if node is not None else None)
        levels.append(row)
        current = following
    return levels


def format_levels(levels):
    """Render levels as readable text, one line per depth."""
    lines = []
    for depth, row in enumerate(levels):
        cells = ["_" if value is None else str(value) for value in row]
        lines.append("depth {0}: {1}".format(depth, " ".join(cells)))
    return "\n".join(lines)


def main():
    cases = [
        ("mirrored", [1, 2, 2, 3, 4, 4, 3]),
        ("lopsided", [1, 2, 2, None, 3, None, 3]),
        ("empty", []),
    ]
    summary = {}
    for name, values in cases:
        root = build_tree(values)
        summary[name] = is_symmetric(root)
        print("--- {0} ---".format(name))
        print(format_levels(level_order(root)) or "(no nodes)")
    for name, symmetric in summary.items():
        print("{0}: symmetric={1}".format(name, symmetric))


if __name__ == "__main__":
    main()

