import string

def tokenize(text):
    """Split text into lowercase words, dropping punctuation."""
    words = []
    current = []
    for char in text.lower():
        if char.isalnum() or char == "'":
            current.append(char)
        elif current:
            words.append("".join(current).strip("'"))
            current = []
    if current:
        words.append("".join(current).strip("'"))
    return [word for word in words if word]


def word_counts(text):
    """Count occurrences of each word in text, ignoring case and punctuation."""
    counts = {}
    for word in tokenize(text):
        counts[word] = counts.get(word, 0) + 1
    return counts


def group_by_count(counts):
    """Invert a count mapping into count -> sorted list of words."""
    groups = {}
    for word, number in counts.items():
        if number not in groups:
            groups[number] = []
        groups[number].append(word)
    for number in groups:
        groups[number].sort()
    return groups


def top_words(counts, limit=3):
    """Return the most frequent words, ties broken alphabetically."""
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


def punctuation_profile(text):
    """Count the punctuation marks that tokenize() discards."""
    marks = {}
    for char in text:
        if char in string.punctuation and char != "'":
            marks[char] = marks.get(char, 0) + 1
    return marks


def report(text):
    """Build a human-readable summary of the word statistics of text."""
    counts = word_counts(text)
    lines = []
    lines.append("text: {!r}".format(text))
    lines.append("distinct words: {}".format(len(counts)))
    lines.append("total words: {}".format(sum(counts.values())))
    for word, number in top_words(counts):
        lines.append("  {:<10} {}".format(word, number))
    groups = group_by_count(counts)
    for number in sorted(groups, reverse=True):
        lines.append("  seen {}x: {}".format(number, ", ".join(groups[number])))
    marks = punctuation_profile(text)
    if marks:
        pieces = []
        for mark in sorted(marks):
            pieces.append("{}={}".format(mark, marks[mark]))
        lines.append("punctuation: " + " ".join(pieces))
    return "\n".join(lines)


def main():
    samples = [
        "Hello world, hello Python!",
        "A B A B C",
        "The rain in Spain; the rain isn't plain -- it's rain.",
    ]
    for sample in samples:
        print(report(sample))
        print()


if __name__ == "__main__":
    main()

