import sys


class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def parse_list(text):
    """Turn a string like '1->2->3' into a list of integers ('' -> empty list)."""
    values = []
    for token in text.split("->"):
        token = token.strip()
        if token:
            values.append(int(token))
    return values


def parse_cases(lines):
    """Read 'list, n' lines into cases, collecting complaints about bad lines."""
    cases = []
    problems = []
    for number, line in enumerate(lines, 1):
        line = line.strip()
        if not line:
            continue
        list_text, separator, count_text = line.partition(",")
        if not separator:
            problems.append("line {}: expected 'list, n'".format(number))
            continue
        try:
            count = int(count_text)
        except ValueError:
            problems.append("line {}: bad n {!r}".format(number, count_text.strip()))
            continue
        cases.append((list_text.strip(), count))
    return cases, problems


def build_list(values):
    """Build a singly linked list from an iterable of values, return its head."""
    head = None
    tail = None
    for value in values:
        node = ListNode(value)
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head


def to_values(head):
    out = []
    node = head
    while node is not None:
        out.append(node.val)
        node = node.next
    return out


def format_list(head):
    parts = [str(value) for value in to_values(head)]
    return "->".join(parts) if parts else "None"


def remove_nth_from_end(head, n):
    """Remove the nth node counted from the end and return the new head."""
    if n < 1:
        raise ValueError("n must be at least 1")
    sentinel = ListNode(0, head)
    lead = sentinel
    for _ in range(n):
        if lead.next is None:
            raise ValueError("n is larger than the length of the list")
        lead = lead.next
    trail = sentinel
    while lead.next is not None:
        lead = lead.next
        trail = trail.next
    trail.next = trail.next.next
    return sentinel.next


def summarize(cases):
    """Run each (text, n) case, returning a results mapping and a list of errors."""
    results = {}
    errors = []
    for text, n in cases:
        try:
            head = build_list(parse_list(text))
            results[(text, n)] = format_list(remove_nth_from_end(head, n))
        except ValueError as exc:
            errors.append("{!r} with n={}: {}".format(text, n, exc))
    return results, errors


def main():
    cases, problems = parse_cases(sys.stdin)
    results, errors = summarize(cases)
    for text, n in cases:
        if (text, n) in results:
            print("{} (n={}) -> {}".format(text or "None", n, results[(text, n)]))
    for message in problems + errors:
        print("rejected:", message)


if __name__ == "__main__":
    main()

