def validate_input(nums):
    """Check that nums is a list of distinct integers and return it unchanged."""
    if not isinstance(nums, list):
        raise TypeError("nums must be a list")
    counts = {}
    for value in nums:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("nums must contain only integers")
        counts[value] = counts.get(value, 0) + 1
    repeated = [value for value, times in counts.items() if times > 1]
    if repeated:
        raise ValueError("nums must be distinct, repeated: %r" % (repeated,))
    return nums


def generate_subsets(nums):
    """Return the power set of a list of distinct integers."""
    validate_input(nums)
    subsets = []
    current = []

    def backtrack(start):
        subsets.append(list(current))
        for index in range(start, len(nums)):
            current.append(nums[index])
            backtrack(index + 1)
            current.pop()

    backtrack(0)
    return subsets


def group_by_size(subsets):
    """Map each subset size to the list of subsets having that size."""
    groups = {}
    for subset in subsets:
        groups.setdefault(len(subset), []).append(subset)
    return groups


def subset_sums(subsets):
    """Map each achievable subset sum to how many subsets reach it."""
    totals = {}
    for subset in subsets:
        total = sum(subset)
        totals[total] = totals.get(total, 0) + 1
    return totals


def format_subset(subset):
    if not subset:
        return "{}"
    return "{" + ", ".join(str(value) for value in subset) + "}"


def format_report(nums):
    """Build a human readable listing of the power set of nums."""
    subsets = generate_subsets(nums)
    groups = group_by_size(subsets)
    lines = []
    lines.append("input: %s" % format_subset(nums))
    lines.append("subsets: %d" % len(subsets))
    for size in sorted(groups):
        rendered = [format_subset(subset) for subset in groups[size]]
        lines.append("  size %d: %s" % (size, " ".join(rendered)))
    sums = subset_sums(subsets)
    peak = max(sums, key=lambda total: (sums[total], total))
    lines.append("  most common sum: %d (%d subsets)" % (peak, sums[peak]))
    return "\n".join(lines)


def main():
    samples = [[1, 2, 3], [], [4, -1, 7, 0]]
    for sample in samples:
        print(format_report(sample))
        print()


if __name__ == "__main__":
