def filter_by_length(strings: list[str], min_length: int) -> list[str]:
    """Return the strings that are strictly longer than min_length."""
    if not isinstance(min_length, int):
        raise TypeError("min_length must be an integer")
    kept = []
    for text in strings:
        if len(text) > min_length:
            kept.append(text)
    return kept


def reject_by_length(strings: list[str], min_length: int) -> list[str]:
    """Return the strings that are too short for the given threshold."""
    dropped = []
    for text in strings:
        if len(text) <= min_length:
            dropped.append(text)
    return dropped


def group_by_length(strings: list[str]) -> dict[int, list[str]]:
    """Map each observed length to the strings having that length."""
    buckets = {}
    for text in strings:
        buckets.setdefault(len(text), []).append(text)
    return buckets


