def parse_csv_string(csv_data: str) -> list[list[str]]:
    """Split a multi-line CSV string into a list of rows of string fields."""
    rows = []
    for line in csv_data.split("\n"):
        if line == "" and not rows:
            continue
        fields = []
        for field in line.split(","):
            fields.append(field.strip())
        rows.append(fields)
    return rows


def column_widths(rows: list[list[str]]) -> dict[int, int]:
    """Map each column index to the width of its widest field."""
    widths = {}
    for row in rows:
        for index, field in enumerate(row):
            if len(field) > widths.get(index, 0):
                widths[index] = len(field)
    return widths


def format_table(rows: list[list[str]]) -> str:
    """Render the parsed rows as a padded, pipe-separated table."""
    widths = column_widths(rows)
    lines = []
    for row in rows:
        cells = []
        for index, field in enumerate(row):
            cells.append(field.ljust(widths[index]))
        lines.append(" | ".join(cells).rstrip())
    return "\n".join(lines)


def column_values(rows: list[list[str]], header: str) -> list[str]:
    """Collect the values under the named header column."""
    if not rows:
        return []
    labels = rows[0]
    if header not in labels:
        raise KeyError("no such column: " + header)
    position = labels.index(header)
    values = []
    for row in rows[1:]:
        if position < len(row):
            values.append(row[position])
    return values


def numeric_summary(rows: list[list[str]]) -> dict[str, float]:
    """Average every column whose data values all look like numbers."""
    averages = {}
    if not rows:
        return averages
    for header in rows[0]:
        values = column_values(rows, header)
        numbers = []
        for value in values:
            try:
                numbers.append(float(value))
            except ValueError:
                numbers = []
                break
        if numbers:
            averages[header] = sum(numbers) / len(numbers)
    return averages


def main() -> None:
    sample = "Name,Age\nAlice,30\nBob,24"
    rows = parse_csv_string(sample)
    print(rows)
    print(format_table(rows))
    print(column_values(rows, "Name"))
    for header, mean in numeric_summary(rows).items():
        print(f"mean {header}: {mean:.1f}")
    print(parse_csv_string("A,B\n1,2"))


if __name__ == "__main__":
    main()

