def has_substring_case_insensitive(main_string: str, sub_string: str) -> bool:
    """Return True if sub_string occurs in main_string, ignoring case."""
    if not isinstance(main_string, str) or not isinstance(sub_string, str):
        raise TypeError("both arguments must be strings")
    return sub_string.casefold() in main_string.casefold()


def find_all_positions(main_string: str, sub_string: str) -> list:
    """Return the start indexes of every case-insensitive match."""
    positions = []
    if not sub_string:
        return positions
    haystack = main_string.casefold()
    needle = sub_string.casefold()
    start = haystack.find(needle)
    while start != -1:
        positions.append(start)
        start = haystack.find(needle, start + 1)
    return positions


def match_report(main_string: str, sub_strings) -> dict:
    """Map each candidate substring to its match information."""
    report = {}
    for candidate in sub_strings:
        found = has_substring_case_insensitive(main_string, candidate)
        report[candidate] = {
            "found": found,
            "positions": find_all_positions(main_string, candidate),
        }
    return report


def group_by_result(report: dict) -> dict:
    """Split a report into the substrings that matched and those that did not."""
    groups = {}
    for candidate, info in report.items():
        key = "found" if info["found"] else "missing"
        if key not in groups:
            groups[key] = []
        groups[key].append(candidate)
    return groups


def format_report(main_string: str, report: dict) -> str:
    lines = []
    lines.append("text: %r" % main_string)
    for candidate, info in report.items():
        marker = "yes" if info["found"] else "no"
        detail = ", ".join(str(p) for p in info["positions"])
        lines.append("  %-10s -> %-3s [%s]" % (candidate, marker, detail))
    groups = group_by_result(report)
    for key in sorted(groups):
        lines.append("  %s: %s" % (key, " ".join(sorted(groups[key]))))
    return "\n".join(lines)


def main() -> None:
    samples = {}
    samples["Hello World"] = ["world", "HELLO", "lo Wo", "python"]
    samples["Python"] = ["java", "THON", "py"]
    samples["banana bandana"] = ["ANA", "band", "nan"]
    for text, candidates in samples.items():
        print(format_report(text, match_report(text, candidates)))
        print()
    print(has_substring_case_insensitive("Hello World", "world"))
    print(has_substring_case_insensitive("Python", "java"))


if __name__ == "__main__":
    main()

